  wire [7:0] w_split;
  wire [7:0] x_split;
  wire [7:0] y_split;
  wire [7:0] z_split;
  assign w_split = input_concatenated[27:20];
  assign x_split = input_concatenated[19:12];
  assign y_split = input_concatenated[11:4];
  assign z_split = input_concatenated[3:0];

