module TopModule (
  input clk,
  input areset,
  input x,
  output z
);

  // Define the states of the Mealy finite-state machine
  typedef enum {A, B} state_t;

  // Define the one-hot encoding for the states
  typedef enum {A0, A1, B0, B1} one_hot_state_t;

  // Define the state variable
  state_t state;

  // Define the one-hot state variable
  one_hot_state_t one_hot_state;

  // Define the output variable
  wire z;

  // Define the state transition logic
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= A;
      one_hot_state <= A0;
    end else begin
      case (state)
        A: begin
          if (x == 0) begin
            state <= A;
            one_hot_state <= A0;
          end else begin
            state <= B;
            one_hot_state <= A1;
          end
        end
        B: begin
          if (x == 0) begin
            state <= B;
            one_hot_state <= B0;
          end else begin
            state <= B;
            one_hot_state <= B1;
          end
        end
      endcase
    end
  end

  // Define the output logic
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      z <= 0;
    end else begin
      z <= one_hot_state == B1;
    end
  end

endmodule

