module TopModule (
  input  [5:0] y,
  input        w,
  output       Y1,
  output       Y3
);

  // Define the state machine states
  typedef enum {A, B, C, D, E, F} state_t;

  // Define the state machine variables
  state_t state = A;
  reg [1:0] y1_next;
  reg [1:0] y3_next;

  // Define the state machine logic
  always @(posedge w or posedge y) begin
    if (w) begin
      state <= A;
    end else begin
      case (state)
        A: begin
          if (y[1] == 1) begin
            y1_next = 2'b10;
            y3_next = 2'b01;
          end else begin
            y1_next = 2'b00;
            y3_next = 2'b00;
          end
        end
        B: begin
          if (y[1] == 1) begin
            y1_next = 2'b00;
            y3_next = 2'b01;
          end else begin
            y1_next = 2'b00;
            y3_next = 2'b00;
          end
        end
        C: begin
          if (y[1] == 1) begin
            y1_next = 2'b00;
            y3_next = 2'b01;
          end else begin
            y1_next = 2'b00;
            y3_next = 2'b00;
          end
        end
        D: begin
          if (y[1] == 1) begin
            y1_next = 2'b00;
            y3_next = 2'b01;
          end else begin
            y1_next = 2'b00;
            y3_next = 2'b00;
          end
        end
        E: begin
          if (y[1] == 1) begin
            y1_next = 2'b00;
            y3_next = 2'b01;
          end else begin
            y1_next = 2'b00;
            y3_next = 2'b00;
          end
        end
        F: begin
          if (y[1] == 1) begin
            y1_next = 2'b00;
            y3_next = 2'b01;
          end else begin
            y1_next = 2'b00;
            y3_next = 2'b00;
          end
        end
      endcase
    end
  end

  // Assign the next-state signals to the output ports
  assign Y1 = y1_next;
  assign Y3 = y3_next;

endmodule

