module TopModule (
  input clk,
  input load,
  input [511:0] data,
  output reg [511:0] q
);

  reg [511:0] next_q;
  reg [511:0] current_q;

  always @(posedge clk) begin
    if (load) begin
      current_q <= data;
    end else begin
      current_q <= next_q;
    end
  end

  always @(posedge clk) begin
    next_q[0] <= (current_q[511] ^ current_q[510]);
    next_q[511] <= (current_q[0] ^ current_q[1]);
    for (int i = 1; i < 511; i = i + 1) begin
      next_q[i] <= (current_q[i - 1] ^ current_q[i + 1]);
    end
  end

  assign q = current_q;

