module TopModule (
  input clk,
  input [7:0] in,
  input reset,
  output done
);

  reg [2:0] state;
  reg [7:0] message;
  reg [7:0] byte_count;
  reg done_flag;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= 3'b000;
      message <= 8'b00000000;
      byte_count <= 0;
      done_flag <= 0;
    end else begin
      case (state)
        3'b000: begin
          if (in[3] == 1) begin
            state <= 3'b001;
            byte_count <= 1;
            message <= in;
          end
        end
        3'b001: begin
          if (in[3] == 1) begin
            state <= 3'b010;
            byte_count <= 2;
            message <= in;
          end
        end
        3'b010: begin
          if (in[3] == 1) begin
            state <= 3'b000;
            done_flag <= 1;
          end
        end
        default: begin
          state <= 3'b000;
        end
      endcase

      if (done_flag) begin
        done <= 1;
      end else begin
        done <= 0;
      end
    end
  end

endmodule

module TopModule (
  input clk,
  input aresetn,
  input x,
  output reg z
);

  // Define the states of the FSM
  typedef enum {IDLE, DETECTING_101, DETECTING_101_OVERLAP} state_t;
  state_t current_state = IDLE;

  // Define the output signal z
  reg z;

  // Define the state variables
  reg [1:0] state_1;
  reg [1:0] state_2;

  // Define the state transition logic
  always @(posedge clk or posedge aresetn) begin
    if (aresetn) begin
      current_state <= IDLE;
      state_1 <= 2'b00;
      state_2 <= 2'b00;
      z <= 1'b0;
    end else begin
      case (current_state)
        IDLE: begin
          if (x == 1'b1) begin
            state_1 <= 2'b01;
            state_2 <= 2'b00;
          end
        end
        DETECTING_101: begin
          if (x == 1'b0) begin
            state_1 <= 2'b00;
            state_2 <= 2'b00;
          end else if (x == 1'b1) begin
            state_1 <= 2'b01;
            state_2 <= 2'b01;
          end
        end
        DETECTING_101_OVERLAP: begin
          if (x == 1'b0) begin
            state_1 <= 2'b00;
            state_2 <= 2'b00;
          end else if (x == 1'b1) begin
            state_1 <= 2'b01;
            state_2 <= 2'b01;
          end
        end
      endcase

      // Update the output signal z
      case (state_1)
        2'b00: z <= 1'b0;
        2'b01: z <= 1'b1;
      endcase
    end
  end

endmodule

module TopModule (
