module TopModule (
  input clk,
  input reset,
  input w,
  output z
);

  // Define state codes
  parameter A = 1'b0, B = 1'b1, C = 2'b00, D = 2'b01, E = 2'b10, F = 2'b11;

  // State variables
  reg [1:0] state;

  // State flip-flops
  reg [1:0] next_state;

  // Reset logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= A;
    end else begin
      state <= next_state;
    end
  end

  // State table
  always @(posedge clk) begin
    case (state)
      A: begin
        if (w) begin
          next_state <= B;
        end else begin
          next_state <= A;
        end
      end
      B: begin
        if (w) begin
          next_state <= C;
        end else begin
          next_state <= D;
        end
      end
      C: begin
        if (w) begin
          next_state <= E;
        end else begin
          next_state <= D;
        end
      end
      D: begin
        if (w) begin
          next_state <= F;
        end else begin
          next_state <= A;
        end
      end
      E: begin
        if (w) begin
          next_state <= E;
        end else begin
          next_state <= D;
        end
      end
      F: begin
        if (w) begin
          next_state <= C;
        end else begin
          next_state <= D;
        end
      end
    endcase
  end

  // Output assignment
  assign z = state;

