  output [9:0] next_state,
  output out1,
  output out2
);

  // Define the state machine states
  localparam [9:0] S0 = 10'b0000000000;
  localparam [9:0] S1 = 10'b0000000001;
  localparam [9:0] S2 = 10'b0000000010;
  localparam [9:0] S3 = 10'b0000000011;
  localparam [9:0] S4 = 10'b0000000100;
  localparam [9:0] S5 = 10'b0000000101;
