  localparam [9:0] S7 = 10'b0000000111;
  localparam [9:0] S8 = 10'b0000001000;
  localparam [9:0] S9 = 10'b0000001001;

  // Define the state transition logic
  always @(posedge in or posedge state) begin
    case (state)
      S0: begin
        if (in == 1) begin
          next_state = S1;
          out1 = 1'b0;
          out2 = 1'b0;
        end else begin
          next_state = S0;
          out1 = 1'b0;
          out2 = 1'b0;
        end
      end
      S1: begin
        if (in == 1) begin
          next_state = S2;
          out1 = 1'b0;
          out2 = 1'b0;
        end else begin
          next_state = S0;
          out1 = 1'b0;
          out2 = 1'b0;
        end
      end
      S2: begin
        if (in == 1) begin
          next_state = S3;
          out1 = 1'b0;
          out2 = 1'b0;
        end else begin
          next_state = S0;
          out1 = 1'b0;
          out2 = 1'b0;
        end
      end
      S3: begin
        if (in == 1) begin
          next_state = S4;
          out1 = 1'b0;
          out2 = 1'b0;
        end else begin
          next_state = S0;
          out1 = 1'b0;
          out2 = 1'b0;
        end
      end
      S4: begin
        if (in == 1) begin
          next_state = S0;
          out1 = 1'b0;
          out2 = 1'b0;
        end else begin
          next_state = S0;
          out1 = 1'b0;
          out2 = 1'b0;
        end
      end
      S5: begin
        if (in == 1) begin
          next_state = S8;
          out1 = 1'b0;
          out2 = 1'b0;
        end else begin
          next_state = S6;
          out1 = 1'b0;
          out2 = 1'b0;
        end
      end
      S6: begin
        if (in == 1) begin
          next_state = S9;
          out1 = 1'b0;
          out2 = 1'b0;
        end else begin
          next_state = S7;
          out1 = 1'b0;
          out2 = 1'b0;
        end
      end
      S7: begin
        if (in == 1) begin
          next_state = S0;
          out1 = 1'b0;
          out2 = 1'b0;
        end else begin
          next_state = S7;
          out1 = 1'b0;
          out2 = 1'b0;
        end
      end
      S8: begin
        if (in == 1) begin
          next_state = S0;
          out1 = 1'b0;
          out2 = 1'b0;
        end else begin
          next_state = S1;
          out1 = 1'b0;
          out2 = 1'b0;
        end
      end
      S9: begin
        if (in == 1) begin
          next_state = S0;
          out1 = 1'b0;
          out2 = 1'b0;
        end else begin
          next_state = S1;
          out1 = 1'b0;
          out2 = 1'b0;
        end
      end
      default: begin
        next_state = state;
        out1 = 1'b0;
        out2 = 1'b0;
      end
    endcase
  end

endmodule

module TopModule (
  input clk,
  input load,
  input [255:0] data,
  output reg [255:0] q
);

  // Define the 16x16 grid as a 2D array of 1-bit registers
  reg [15:0] grid [15:0];

  // Initialize the grid with the initial state
  initial begin
    for (int i = 0; i < 16; i++) begin
      for (int j = 0; j < 16; j++) begin
        grid[i][j] = data[i * 16 + j];
      end
    end
  end

  // Update the grid state every clock cycle
  always @(posedge clk) begin
    if (load) begin
      for (int i = 0; i < 16; i++) begin
        for (int j = 0; j < 16; j++) begin
          grid[i][j] = data[i * 16 + j];
        end
      end
    end else begin
      for (int i = 0; i < 16; i++) begin
        for (int j = 0; j < 16; j++) begin
          int count = 0;
          for (int di = -1; di <= 1; di++) begin
            for (int dj = -1; dj <= 1; dj++) begin
              if (di == 0 && dj == 0) continue;
              int ni = (i + di + 16) % 16;
              int nj = (j + dj + 16) % 16;
              count += grid[ni][nj];
            end
          end
          if (count == 0) begin
            grid[i][j] = 0;
          end else if (count == 1) begin
            grid[i][j] = 0;
          end else if (count == 2) begin
            grid[i][j] = grid[i][j];
          end else if (count == 3) begin
            grid[i][j] = 1;
          end else if (count == 4) begin
            grid[i][j] = 0;
          end
        end
      end
    end
  end

  // Output the updated grid state
  assign q = pack_grid(grid);

  // Helper function to pack the grid into a single 256-bit vector
  function [255:0] pack_grid(input [15:0] grid [15:0]);
    for (int i = 0; i < 16; i++) begin
      for (int j = 0; j < 16; j++) begin
        pack_grid = pack_grid | (grid[i][j] << (i * 16 + j));
      end
    end
  endfunction

endmodule

