  input b,
  output q,
  output state
);

  reg [1:0] memory;
  reg [1:0] state;

  always @(posedge clk) begin
    if (a == 1'b1) begin
      memory <= b;
    end
    if (b == 1'b1) begin
      memory <= a;
    end
    q <= memory;
    state <= memory;
  end

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  // State codes
  localparam A = 3'b000;
  localparam B = 3'b001;
  localparam C = 3'b010;
  localparam D = 3'b011;

  // State variables
  reg [2:0] state;
  reg [2:0] next_state;

  // State flip-flops
  reg [2:0] state_reg;
  reg [2:0] next_state_reg;

  // Request signals
  reg [2:0] r0;
  reg [2:0] r1;
  reg [2:0] r2;

  // Grant signals
  reg [2:0] g0;
  reg [2:0] g1;
  reg [2:0] g2;

  // Resetn signal
  reg resetn_reg;

  // State table
  always @(posedge clk or posedge resetn) begin
    if (resetn) begin
      state_reg <= A;
      next_state_reg <= A;
      r0 <= 3'b000;
      r1 <= 3'b000;
      r2 <= 3'b000;
      g0 <= 3'b000;
      g1 <= 3'b000;
      g2 <= 3'b000;
      resetn_reg <= 1'b1;
    end else begin
      state_reg <= next_state_reg;
      resetn_reg <= 1'b0;
    end
  end

  always @(posedge clk or posedge resetn) begin
    if (resetn) begin
      next_state_reg <= A;
    end else begin
      case (state_reg)
        A: begin
          if (r0 == 3'b000) begin
            next_state_reg <= A;
          end else if (r1 == 3'b000) begin
            next_state_reg <= B;
          end else if (r2 == 3'b000) begin
            next_state_reg <= C;
          end else begin
            next_state_reg <= D;
          end
        end
        B: begin
          if (r0 == 3'b000) begin
            next_state_reg <= B;
          end else if (r1 == 3'b000) begin
            next_state_reg <= A;
          end else if (r2 == 3'b000) begin
            next_state_reg <= C;
          end else begin
            next_state_reg <= D;
          end
        end
        C: begin
          if (r0 == 3'b000) begin
            next_state_reg <= C;
          end else if (r1 == 3'b000) begin
            next_state_reg <= A;
          end else if (r2 == 3'b000) begin
            next_state_reg <= B;
          end else begin
            next_state_reg <= D;
          end
        end
        D: begin
          if (r0 == 3'b000) begin
            next_state_reg <= D;
          end else if (r1 == 3'b000) begin
            next_state_reg <= A;
          end else if (r2 == 3'b000) begin
            next_state_reg <= B;
          end else begin
            next_state_reg <= D;
          end
        end
      endcase
    end
  end

  // Request signals
  always @(posedge clk or posedge resetn) begin
    if (resetn) begin
      r0 <= 3'b000;
      r1 <= 3'b000;
      r2 <= 3'b000;
    end else begin
      r0 <= r[0];
      r1 <= r[1];
      r2 <= r[2];
    end
  end

  // Grant signals
  always @(posedge clk or posedge resetn) begin
    if (resetn) begin
      g0 <= 3'b000;
      g1 <= 3'b000;
      g2 <= 3'b000;
    end else begin
      case (state_reg)
        A: begin
          g0 <= 3'b000;
          g1 <= 3'b000;
          g2 <= 3'b000;
        end
        B: begin
          g0 <= 3'b000;
          g1 <= 3'b000;
          g2 <= 3'b000;
        end
        C: begin
          g0 <= 3'b000;
          g1 <= 3'b000;
          g2 <= 3'b000;
        end
        D: begin
          g0 <= 3'b000;
          g1 <= 3'b000;
          g2 <= 3'b000;
        end
      endcase
    end
  end

  // Output assignment
  assign g = state_reg;

endmodule

