module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  input dig,
  output walk_left,
  output walk_right,
  output aaah,
  output digging
);

  // Define the states of the state machine
  typedef enum {IDLE, WALK_LEFT, WALK_RIGHT, FALLING, DIGGING} state_t;

  // Define the variables for the state machine
  state_t state = IDLE;
  reg [1:0] direction = 0; // 0 = left, 1 = right
  reg [1:0] bump_count = 0; // 0 = no bump, 1 = bump on left, 2 = bump on right, 3 = bump on both
  reg [1:0] ground_count = 0; // 0 = no ground, 1 = ground
  reg [1:0] dig_count = 0; // 0 = not digging, 1 = digging

  // Define the logic for the state machine
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= IDLE;
      direction <= 0;
      bump_count <= 0;
      ground_count <= 0;
      dig_count <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (bump_left) begin
            bump_count <= 1;
          end else if (bump_right) begin
            bump_count <= 2;
          end else if (ground) begin
            ground_count <= 1;
          end
          if (dig) begin
            dig_count <= 1;
          end
          if (bump_count == 1 || bump_count == 2 || ground_count == 1 || dig_count == 1) begin
            state <= FALLING;
          end else if (bump_count == 3) begin
            state <= WALK_RIGHT;
          end else if (bump_count == 0) begin
            state <= WALK_LEFT;
          end
        end
        WALK_LEFT: begin
          if (bump_left) begin
            bump_count <= 1;
          end else if (bump_right) begin
            bump_count <= 2;
          end else if (ground) begin
            ground_count <= 1;
          end
          if (dig) begin
            dig_count <= 1;
          end
          if (bump_count == 1 || bump_count == 2 || ground_count == 1 || dig_count == 1) begin
            state <= FALLING;
          end else if (bump_count == 3) begin
            state <= WALK_RIGHT;
          end else if (bump_count == 0) begin
            state <= WALK_LEFT;
          end
        end
        WALK_RIGHT: begin
          if (bump_left) begin
            bump_count <= 1;
          end else if (bump_right) begin
            bump_count <= 2;
          end else if (ground) begin
            ground_count <= 1;
          end
          if (dig) begin
            dig_count <= 1;
          end
          if (bump_count == 1 || bump_count == 2 || ground_count == 1 || dig_count == 1) begin
            state <= FALLING;
          end else if (bump_count == 3) begin
            state <= WALK_LEFT;
          end else if (bump_count == 0) begin
            state <= WALK_RIGHT;
          end
        end
        FALLING: begin
          if (ground) begin
            ground_count <= 0;
            state <= WALK_LEFT;
          end
        end
        DIGGING: begin
          if (ground) begin
            ground_count <= 0;
            state <= WALK_LEFT;
          end
        end
      endcase
    end
  end

  // Define the logic for the outputs
  assign walk_left = (state == WALK_LEFT);
  assign walk_right = (state == WALK_RIGHT);
  assign aaah = (state == FALLING);
  assign digging = (state == DIGGING);

endmodule

