  reg [23:0] out_bytes_reg;
  reg [2:0] state;
  reg done_reg;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      in_reg <= 8'b0;
      out_bytes_reg <= 24'b0;
      state <= 3'b0;
      done_reg <= 1'b0;
    end else begin
      in_reg <= in;
      case (state)
        3'b000: begin
          if (in_reg[3] == 1'b1) begin
            state <= 3'b001;
            out_bytes_reg <= in_reg;
          end
        end
        3'b001: begin
          if (in_reg[3] == 1'b1) begin
            state <= 3'b010;
            out_bytes_reg <= {out_bytes_reg[23:16], in_reg[2:0]};
          end
        end
        3'b010: begin
          if (in_reg[3] == 1'b1) begin
            state <= 3'b000;
            out_bytes_reg <= {out_bytes_reg[23:16], in_reg[2:0]};
            done_reg <= 1'b1;
          end
        end
        default: begin
          state <= 3'b000;
          out_bytes_reg <= 24'b0;
          done_reg <= 1'b0;
        end
      endcase
    end
  end

  assign out_bytes = out_bytes_reg;
  assign done = done_reg;

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  input dig,
  output walk_left,
  output walk_right,
  output aaah,
  output digging
);

  // Define the states of the FSM
  typedef enum {IDLE, FALLING, DIGGING, SPLATTERING} FSM_STATE;

  // Define the variables for the FSM
  reg [1:0] state;
  reg [1:0] prev_state;
  reg [1:0] direction;
  reg [1:0] fall_count;
  reg [1:0] splatter_count;

  // Initialize the FSM state
  initial begin
    state = IDLE;
    prev_state = IDLE;
    direction = 0;
    fall_count = 0;
    splatter_count = 0;
  end

  // Update the FSM state on the positive edge of the clock
  always @(posedge clk) begin
    prev_state = state;
    case (state)
      IDLE:
        if (bump_left) begin
          state = FALLING;
          direction = 1;
        end else if (bump_right) begin
          state = FALLING;
          direction = 0;
        end else if (dig) begin
          state = DIGGING;
        end else if (ground) begin
          state = IDLE;
        end
      FALLING:
        fall_count++;
        if (ground) begin
          state = IDLE;
          fall_count = 0;
        end
      DIGGING:
        if (ground) begin
          state = IDLE;
          fall_count = 0;
        end
      SPLATTERING:
        splatter_count++;
        if (splatter_count >= 20) begin
          state = IDLE;
          fall_count = 0;
          splatter_count = 0;
        end
    endcase
  end

  // Output the FSM state
  assign walk_left = (state == IDLE) ? 1'b0 : (state == FALLING) ? 1'b1 : 1'b0;
  assign walk_right = (state == IDLE) ? 1'b0 : (state == FALLING) ? 1'b0 : 1'b1;
  assign aaah = (state == IDLE) ? 1'b0 : (state == FALLING) ? 1'b0 : 1'b0;
  assign digging = (state == IDLE) ? 1'b0 : (state == FALLING) ? 1'b0 : 1'b0;

endmodule

