		case (state)
			3'b000: begin
				if (VSYNC_cam && HREF_cam) begin
					state <= 3'b001;
				end
			end
			3'b001: begin
				if (input_wrusedw < 100) begin
					state <= 3'b001;
				end else if (output_rdusedw < 100) begin
					state <= 3'b010;
				end else if (sd_ready && valid_data && !STOP_capt) begin
					state <= 3'b011;
				end else if (STOP_capt) begin
					state <= 3'b000;
				end
			end
			3'b010: begin
				if (output_rdusedw < 100) begin
					state <= 3'b010;
				end else if (sd_ready && valid_data && !STOP_capt) begin
					state <= 3'b011;
				end else if (STOP_capt) begin
					state <= 3'b000;
				end
			end
			3'b011: begin
				if (sd_ready && valid_data && !STOP_capt) begin
					state <= 3'b011;
				end else if (STOP_capt) begin
					state <= 3'b000;
				end
			end
