module top_properties (
    input logic clock,
    input logic read,
    input logic write,
    input logic ready
);

    // Define the FAIL macro for timing relationship enforcement
    `define FAIL 100ns

    // Assertion 1: Check for mutually exclusive read and write conditions at every positive clock edge
    property read_write_mutually_exclusive;
        @(posedge clock) begin
            @(posedge clock) begin
                if (read && write) begin
                    $error("Read and write signals cannot be asserted simultaneously.");
                end
            end
        end
    endproperty

    // Assertion 2: Enforce a timing relationship between the write and ready signals
    property write_ready_timing;
        @(posedge clock) begin
            @(posedge clock) begin
                if (write) begin
                    @(posedge clock) begin
                        if (ready) begin
                            $error("Write signal cannot be asserted after ready signal is set.");
                        end
                    end
                end
            end
        end
    endproperty

    // Generate the assertions
    assert property(read_write_mutually_exclusive);
    assert property(write_ready_timing);

endmodule

