		// Stage 0: Perform subtraction
		stage0 <= a - d;

		// Stage 1: Perform multiplication
		intermediate_result <= stage0 * b;

		// Stage 2: Add c
		stage2 <= intermediate_result + c;

		// Output the final result after XOR reduction
		out <= stage2[7];
	end
end

endmodule

module mulor_2_stage_signed_8_bit(
	input signed [7:0] a,
	input signed [7:0] b,
	input signed [7:0] c,
	output [7:0] out,
	input clk);

reg [15:0] stage0, stage1;
reg [7:0] result;

always @(posedge clk) begin
    // First stage: Multiply a and b
    stage0 = a * b;

    // Second stage: Combine stage0 with c using bitwise OR
    result = stage0 | c;

    // Output the lower 8 bits of the result
    out <= result[7:0];
end

endmodule

module addmulsub_1_stage_unsigned_11_bit(
