        8'b00001011, 8'b00001100, 8'b00001101, 8'b00001110, 8'b00001111
    };

    // Compute the sine and cosine values based on the phase input
    always @(posedge phase) begin
        sin <= sine_values[phase];
        cos <= cosine_values[phase];
    end

endmodule

