module round
  #(parameter bits_in=0,
    parameter bits_out=0,
    parameter round_to_zero=0,       
    parameter round_to_nearest=1,    
    parameter trunc=0)               
    (input [bits_in-1:0] in,
     output [bits_out-1:0] out,
     output [bits_in-bits_out:0] err);

  // Internal signals
  reg [bits_in-1:0] input_bits;
  reg [bits_in-1:0] output_bits;
  reg [bits_in-1:0] error_bits;
  reg [bits_in-1:0] correction_bits;
  reg [bits_in-1:0] higher_order_bits;
  reg [bits_in-1:0] lower_order_bits;
  reg [bits_in-1:0] round_mode;

  // Parameters
  parameter bits_in = 8;
  parameter bits_out = 4;
  parameter round_to_zero = 0;
  parameter round_to_nearest = 1;
  parameter trunc = 0;

  // Assignments
  assign input_bits = in;
  assign round_mode = round_to_zero | round_to_nearest | trunc;

  // Rounding logic
  always @(posedge clk or negedge rst) begin
    if (rst) begin
      output_bits <= 0;
      error_bits <= 0;
      correction_bits <= 0;
      higher_order_bits <= 0;
      lower_order_bits <= 0;
    end else begin
      if (round_mode == round_to_zero) begin
        output_bits <= input_bits;
        error_bits <= input_bits;
      end else if (round_mode == round_to_nearest) begin
        higher_order_bits = input_bits >> (bits_in - bits_out);
        lower_order_bits = input_bits & ((1 << bits_out) - 1);
        correction_bits = (lower_order_bits + 1) >> 1;
        output_bits = higher_order_bits | correction_bits;
        error_bits = input_bits - output_bits;
      } else if (round_mode == trunc) begin
        output_bits = input_bits & ((1 << bits_out) - 1);
        error_bits = input_bits - output_bits;
      end
    end
  end

  // Output assignment
  assign out = output_bits;
  assign err = error_bits;
endmodule

