module hardcopyiv_hssi_aux_clock_div (
    clk,     
    reset,   
    enable_d, 
    d,        
    clkout   
);

input clk,reset;
input enable_d;
input [7:0] d;
output clkout;

reg [7:0] divide_factor;
reg [7:0] count;
reg [7:0] extra_latency;
reg [7:0] output;
reg [7:0] last_divide_factor;
reg [7:0] last_count;
reg [7:0] last_extra_latency;
reg [7:0] last_output;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        divide_factor <= 8'b0;
        count <= 8'b0;
        extra_latency <= 8'b0;
        output <= 8'b0;
        last_divide_factor <= 8'b0;
        last_count <= 8'b0;
        last_extra_latency <= 8'b0;
        last_output <= 8'b0;
    end else begin
        if (enable_d) begin
            if (divide_factor != last_divide_factor) begin
                count <= 8'b0;
                extra_latency <= 8'b0;
                output <= 8'b0;
            end
            if (count == divide_factor - 1) begin
                output <= d;
                count <= 8'b0;
                extra_latency <= extra_latency - 1;
            end else begin
                count <= count + 1;
            end
        end
        last_divide_factor <= divide_factor;
        last_count <= count;
        last_extra_latency <= extra_latency;
        last_output <= output;
    end
end

assign clkout = output;

endmodule

