module pes_elevator (request_floor, in_current_floor, clk, reset, complete, direction, 
over_time, over_weight, weight_alert, door_alert, out_current_floor) ;

input [7:0]request_floor; 
input [7:0]in_current_floor; 
input clk; 
input reset; 
input over_time; 
input over_weight; 



output direction; 
output complete;
output door_alert;
output weight_alert;
output [7:0] out_current_floor;

reg [7:0] current_floor;
reg [1:0] direction;
reg complete;
reg door_alert;
reg weight_alert;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        current_floor <= in_current_floor;
        direction <= 2'b00;
        complete <= 1'b0;
        door_alert <= 1'b0;
        weight_alert <= 1'b0;
    end else begin
        if (over_time) begin
            door_alert <= 1'b1;
            weight_alert <= 1'b1;
        end else if (over_weight) begin
            door_alert <= 1'b1;
            weight_alert <= 1'b1;
        end else if (request_floor != current_floor) begin
            if (request_floor > current_floor) begin
                direction <= 2'b01;
            end else begin
                direction <= 2'b10;
            end
            current_floor <= request_floor;
            complete <= 1'b0;
        end else begin
            complete <= 1'b1;
        end
    end
end

assign direction = direction;
assign complete = complete;
assign door_alert = door_alert;
assign weight_alert = weight_alert;
assign out_current_floor = current_floor;

endmodule

