module AXI_WRITE_DATA_CHANNEL_model(
input wire clk,
input wire resetn,
input wire [31:0] data,
input wire go,
output reg done,
output wire [31:0] WDATA,
output reg [3:0] WSTRB,
output reg WVALID,
input wire WREADY
);

parameter NUM_STATES = 4;
parameter IDLE = 0;
parameter RUNNING = 1;
parameter COMPLETE = 2;
parameter RESET = 3;

reg [1:0] current_state;
reg [1:0] next_state;

always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
        current_state <= RESET;
        done <= 0;
        WDATA <= 0;
        WSTRB <= 0;
        WVALID <= 0;
    end else begin
        current_state <= next_state;
        done <= WVALID;
        WDATA <= data;
        WSTRB <= {3'b000, data[7:4]};
        WVALID <= go;
    end
end

always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
        next_state <= RESET;
    end else begin
        case (current_state)
            IDLE: begin
                if (go) begin
                    next_state <= RUNNING;
                end else begin
                    next_state <= IDLE;
                end
            end
            RUNNING: begin
                if (WREADY) begin
                    next_state <= COMPLETE;
                end else begin
                    next_state <= RUNNING;
                end
            end
            COMPLETE: begin
                next_state <= IDLE;
            end
            default: begin
                next_state <= RESET;
            end
        endcase
    end
end

endmodule

