module sep32_cnt(
    input           clk,
    input           cen,
    input           zero,
    output reg [4:0]    cnt
    );

    reg [4:0]    last_zero;
    reg [4:0]    cnt;

    always @(posedge clk or posedge cen) begin
        if (cen) begin
            if (zero && !last_zero) begin
                cnt <= 5'b00001;
            end else if (!zero && last_zero) begin
                cnt <= cnt + 1'b1;
            end
            last_zero <= zero;
        end else begin
            cnt <= 5'b00000;
        end
    end

endmodule

