module receiver(input wire rx,
		output reg rdy,
		input wire rdy_clr,
		input wire clk_50m,rst,
		input wire clken,
		output reg [7:0] data);

	// State machine states
	localparam IDLE = 0;
	localparam START = 1;
	localparam DATA = 2;
	localparam STOP = 3;

	// Internal signals
	reg [1:0] state;
	reg [7:0] data_reg;
	reg [1:0] bit_count;
	reg [1:0] bit_index;
	reg [1:0] start_count;
	reg [1:0] stop_count;
	reg [1:0] clear_count;

	// Clock enable and reset
	reg clk_en;
	reg rst_en;

	// Initialize state machine
	initial begin
		state = IDLE;
		data_reg = 8'b0;
		bit_count = 0;
		bit_index = 0;
		start_count = 0;
		stop_count = 0;
		clear_count = 0;
		clk_en = 0;
		rst_en = 0;
		rdy = 0;
		data = 8'b0;
	end

	// Clock and reset
	always @(posedge clk_50m or posedge rst) begin
		if (rst) begin
			state = IDLE;
			data_reg = 8'b0;
			bit_count = 0;
			bit_index = 0;
			start_count = 0;
			stop_count = 0;
			clear_count = 0;
			clk_en = 0;
			rst_en = 1;
			rdy = 0;
			data = 8'b0;
		end else begin
			rst_en = 0;
			if (clk_en) begin
				case (state)
					IDLE: begin
						if (rx) begin
							state = START;
							start_count = 1;
						end
					end
					START: begin
						if (rx) begin
							state = DATA;
							bit_count = 0;
							bit_index = 0;
							start_count = 0;
						end else begin
							state = IDLE;
						end
					end
					DATA: begin
						if (rx) begin
							data_reg[bit_index] = rx;
							bit_index = bit_index + 1;
							if (bit_index == 8) begin
								state = STOP;
								stop_count = 1;
							end
						end else begin
							state = IDLE;
						end
					end
					STOP: begin
						if (rx) begin
							state = IDLE;
							stop_count = 0;
						end else begin
							state = STOP;
						end
					end
				endcase
			end
		end
	end

	// Ready signal
	always @(posedge clk_50m or posedge rst) begin
		if (rst) begin
			rdy = 0;
		end else begin
			if (state == IDLE) begin
				rdy = 0;
			end else if (state == START) begin
				rdy = 0;
			end else if (state == DATA) begin
				if (bit_index == 8) begin
					rdy = 1;
				end else begin
					rdy = 0;
				end
			end else if (state == STOP) begin
				if (stop_count == 1) begin
					rdy = 1;
				end else begin
					rdy = 0;
				end
			end
		end
	end

	// Clear ready signal
	always @(posedge clk_50m or posedge rst) begin
		if (rst) begin
			clear_count = 0;
		end else begin
			if (clear_count == 1) begin
				rdy = 0;
			end else begin
				clear_count = 0;
			end
		end
	end

	// Clock enable
	always @(posedge clk_50m or posedge rst) begin
		if (rst) begin
			clk_en = 0;
		end else begin
			if (clken) begin
				clk_en = 1;
			end else begin
				clk_en = 0;
			end
		end
	end

endmodule

