            valid_R_next <= 2'b00;
            pc_R_next <= 32'b0;
            src0_value_R_next <= 32'b0;
            src1_value_R_next <= 32'b0;
            dst_rob_R_next <= 4'b0000;
            imm_R_next <= 26'b0;
            fid_R_next <= 8'b0;
            bru_cmd_R_next <= 2'b00;
            bagu_cmd_R_next <= 2'b00;
        end else begin
            valid_R_next <= valid_R;
            bp_pattern_R_next <= bp_pattern;
            bp_taken_R_next <= bp_taken;
            bp_hit_R_next <= bp_hit;
            bp_target_R_next <= bp_target;
            pc_R_next <= pc;
            src0_value_R_next <= src0_value;
            src1_value_R_next <= src1_value;
            dst_rob_R_next <= dst_rob;
            imm_R_next <= imm;
            fid_R_next <= fid;
            bru_cmd_R_next <= bru_cmd;
            bagu_cmd_R_next <= bagu_cmd;
        end
    end

    // Capture signals based on i_valid
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            valid_R <= 2'b00;
        end else begin
            if (i_valid) begin
                valid_R_next <= 2'b01;
            end else begin
                valid_R_next <= valid_R;
            end
        end
    end

    // Capture branch prediction signals
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            bp_pattern_R <= 2'b00;
            bp_taken_R <= 1'b0;
            bp_hit_R <= 1'b0;
            bp_target_R <= 32'b0;
        end else begin
            if (i_valid) begin
                bp_pattern_R_next <= i_bp_pattern;
                bp_taken_R_next <= i_bp_taken;
                bp_hit_R_next <= i_bp_hit;
                bp_target_R_next <= i_bp_target;
            end else begin
                bp_pattern_R_next <= bp_pattern_R;
                bp_taken_R_next <= bp_taken_R;
                bp_hit_R_next <= bp_hit_R;
                bp_target_R_next <= bp_target_R;
            end
        end
    end

    // Capture additional signals based on i_valid
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            pc_R_next <= 32'b0;
            src0_value_R_next <= 32'b0;
            src1_value_R_next <= 32'b0;
            dst_rob_R_next <= 4'b0000;
            imm_R_next <= 26'b0;
            fid_R_next <= 8'b0;
            bru_cmd_R_next <= 2'b00;
            bagu_cmd_R_next <= 2'b00;
        end else begin
            if (i_valid) begin
                pc_R_next <= i_pc;
                src0_value_R_next <= i_src0_value;
                src1_value_R_next <= i_src1_value;
                dst_rob_R_next <= i_dst_rob;
                imm_R_next <= i_imm;
                fid_R_next <= i_fid;
                bru_cmd_R_next <= i_bru_cmd;
                bagu_cmd_R_next <= i_bagu_cmd;
            end else begin
                pc_R_next <= pc_R;
                src0_value_R_next <= src0_value_R;
                src1_value_R_next <= src1_value_R;
                dst_rob_R_next <= dst_rob_R;
                imm_R_next <= imm_R;
                fid_R_next <= fid_R;
                bru_cmd_R_next <= bru_cmd_R;
                bagu_cmd_R_next <= bagu_cmd_R;
            end
        end
    end

    // Output the captured signals
    assign o_bp_pattern = bp_pattern_R;
    assign o_bp_taken = bp_taken_R;
    assign o_bp_hit = bp_hit_R;
    assign o_bp_target = bp_target_R;
    assign o_valid = valid_R_next;
    assign o_pc = pc_R_next;
    assign o_src0_value = src0_value_R_next;
    assign o_src1_value = src1_value_R_next;
    assign o_dst_rob = dst_rob_R_next;
    assign o_imm = imm_R_next;
    assign o_fid = fid_R_next;
    assign o_bru_cmd = bru_cmd_R_next;
    assign o_bagu_cmd = bagu_cmd_R_next;
endmodule

