module oh_oai32 #(parameter DW = 1 ) 
   (
    input [DW-1:0]  a0,
    input [DW-1:0]  a1,
    input [DW-1:0]  a2,
    input [DW-1:0]  b0,
    input [DW-1:0]  b1, 
    output [DW-1:0] z
    );
    // First OR operation group
    wire [DW-1:0] or1;
    or1 = a0 | a1 | a2;

    // Second OR operation group
    wire [DW-1:0] or2;
    or2 = b0 | b1;

    // AND operation between the two OR groups
    wire [DW-1:0] and_result;
    and_result = or1 & or2;

    // Logical negation of the AND result
    wire [DW-1:0] z_result;
    z_result = ~and_result;

    // Assign the result to the output
    assign z = z_result;
endmodule

