module UARTTransmitter(
  input        clock,
               reset,
               io_valid,
  input  [7:0] io_bits,
  input        tick,
  output       io_ready,
               tx
);

  // State machine states
  typedef enum {IDLE, START, DATA, STOP} state_t;
  state_t state = IDLE;

  // Data register
  reg [7:0] data_reg = 8'b0;

  // Output signals
  reg io_ready = 1'b0;
  reg tx = 1'b0;

  // State machine logic
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      data_reg <= 8'b0;
      io_ready <= 1'b0;
      tx <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          if (io_valid) begin
            state <= START;
            data_reg <= io_bits;
          end
        end
        START: begin
          tx <= 1'b0;
          state <= DATA;
        end
        DATA: begin
          tx <= data_reg[0];
          data_reg >>= 1;
          if (data_reg == 8'b0) begin
            state <= STOP;
          end
        end
        STOP: begin
          tx <= 1'b1;
          state <= IDLE;
        end
      endcase
      io_ready <= (state == IDLE);
    end
  end

endmodule

