module io_ps2_keyboard(
input wire clk,
input wire kbd_clk,
input wire kbd_dat,
output reg interrupt,
output reg [7:0] scanCode
);

parameter CLK_SPEED = 1000000; // Clock speed in Hz
parameter timeout_const = 100; // Timeout constant in cycles
parameter debounce_const = 5; // Debounce constant in cycles

reg [7:0] shift_reg; // Register to store incoming data bits
reg clk_filter; // Filter to manage signal transitions
reg timeout; // Flag to indicate timeout
reg bitsCount; // Counter to track the number of bits received
reg [7:0] scanCode; // Output register for the decoded keyboard scan code

// Clock divider to generate a 100Hz clock from the system clock
always @(posedge clk) begin
    if (clk_filter == 0) begin
        clk_filter <= 1;
    end else begin
        clk_filter <= 0;
    end
end

// Debounce logic to filter out noise or spurious signals
always @(posedge clk_filter) begin
    if (kbd_clk == 1) begin
        if (kbd_dat == 1) begin
            if (bitsCount < debounce_const) begin
                bitsCount <= bitsCount + 1;
            end else begin
                bitsCount <= 0;
            end
        end else begin
            bitsCount <= 0;
        end
    end
end

// Timeout logic to handle delays between data bits
always @(posedge clk_filter) begin
    if (bitsCount == timeout_const) begin
        timeout <= 1;
    end else begin
        timeout <= 0;
    end
end

// Decode the keyboard scan code
always @(posedge clk_filter) begin
    if (timeout == 1) begin
        timeout <= 0;
        scanCode <= 0;
    end else if (bitsCount == 8) begin
        scanCode <= shift_reg;
        interrupt <= 1;
    end else if (bitsCount < 8) begin
        shift_reg <= shift_reg << 1;
        shift_reg[0] <= kbd_dat;
    end
end

endmodule

