module vga_controller(
input wire RST,
input wire CLK,
output wire H_SYNC,
output wire V_SYNC,
output wire [10:0] X,
output wire [10:0] Y,
output wire DISP_EN
);

parameter H_ACTIVE = 1280;
parameter V_ACTIVE = 720;
parameter H_SYNC_PORCH = 10;
parameter V_SYNC_PORCH = 10;
parameter H_SYNC_WIDTH = 10;
parameter V_SYNC_WIDTH = 10;
parameter H_TOTAL_PIXELS = H_ACTIVE + H_SYNC_PORCH + H_SYNC_WIDTH;
parameter V_TOTAL_PIXELS = V_ACTIVE + V_SYNC_PORCH + V_SYNC_WIDTH;

reg [10:0] X_reg;
reg [10:0] Y_reg;
reg H_SYNC_reg;
reg V_SYNC_reg;
reg DISP_EN_reg;

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        X_reg <= 1280'b0;
        Y_reg <= 720'b0;
        H_SYNC_reg <= 1'b0;
        V_SYNC_reg <= 1'b0;
        DISP_EN_reg <= 1'b0;
    end else begin
        X_reg <= X_reg + 1'b1;
        Y_reg <= Y_reg + 1'b1;

        if (X_reg == H_TOTAL_PIXELS - 1) begin
            X_reg <= 1280'b0;
            Y_reg <= Y_reg + 1'b1;
        end

        if (Y_reg == V_TOTAL_PIXELS - 1) begin
            X_reg <= 1280'b0;
            Y_reg <= 720'b0;
            H_SYNC_reg <= 1'b0;
            V_SYNC_reg <= 1'b0;
            DISP_EN_reg <= 1'b0;
        end

        if (X_reg == H_ACTIVE - 1) begin
            H_SYNC_reg <= 1'b1;
        end

        if (Y_reg == V_ACTIVE - 1) begin
            V_SYNC_reg <= 1'b1;
        end

        if (X_reg == H_ACTIVE - 1 && Y_reg == V_ACTIVE - 1) begin
            DISP_EN_reg <= 1'b1;
        end
    end
end

assign H_SYNC = H_SYNC_reg;
assign V_SYNC = V_SYNC_reg;
assign X = X_reg;
assign Y = Y_reg;
assign DISP_EN = DISP_EN_reg;

endmodule

