module ps2controller (
    input reset,
    input i_clock,
    input i_data,
    output scan_ready,
    output [7:0] scan_code
) begin
    reg [7:0] scan_code_reg;
    reg [3:0] data_counter;
    reg [1:0] parity;
    reg [1:0] stop_bit;
    reg [1:0] valid_code;
    reg [1:0] ready;

    always @(posedge i_clock or posedge reset) begin
        if (reset) begin
            scan_code_reg <= 8'b0;
            data_counter <= 4'b0;
            parity <= 2'b0;
            stop_bit <= 2'b0;
            valid_code <= 2'b0;
            ready <= 2'b0;
        end else begin
            if (i_data) begin
                data_counter <= data_counter + 1'b1;
                if (data_counter == 4'b1111) begin
                    if (parity == 2'b0) begin
                        valid_code <= 2'b1;
                    end else begin
                        valid_code <= 2'b0;
                    end
                    scan_code_reg <= scan_code_reg << 1;
                    scan_code_reg[0] <= i_data;
                    parity <= (scan_code_reg[0] ^ scan_code_reg[1] ^ scan_code_reg[2] ^ scan_code_reg[3]) & 2'b1;
                    stop_bit <= (scan_code_reg[4] ^ scan_code_reg[5] ^ scan_code_reg[6] ^ scan_code_reg[7]) & 2'b1;
                    if (stop_bit == 2'b1) begin
                        ready <= 2'b1;
                    end else begin
                        ready <= 2'b0;
                    end
                    data_counter <= 4'b0;
                end
            end
        end
    end

    assign scan_ready = ready;
    assign scan_code = scan_code_reg;
endmodule

