module SPI_Slave
  #(parameter SPI_MODE = 0)
  (
   input            i_Rst_L,    
   input            i_Clk,      
   output reg       o_RX_DV,    
   output reg [7:0] o_RX_Byte,  
   input            i_TX_DV,    
   input  [7:0]     i_TX_Byte,  
   input      i_SPI_Clk,
   output reg o_SPI_MISO,
   input      i_SPI_MOSI,
   input      i_SPI_CS_n        
   );

  // Internal registers
  reg [7:0] data_in;
  reg [7:0] data_out;
  reg [2:0] bit_count;
  reg [1:0] mode;
  reg [1:0] clk_phase;
  reg [1:0] clk_polarity;
  reg [1:0] rx_flag;
  reg [1:0] tx_flag;

  // Clock domain crossing logic
  reg clk_crossing;

  // State machine for SPI operation
  always @(posedge i_Clk or posedge i_Rst_L) begin
    if (i_Rst_L) begin
      data_in <= 8'b0;
      data_out <= 8'b0;
      bit_count <= 3'b0;
      mode <= 2'b0;
      clk_phase <= 2'b0;
      clk_polarity <= 2'b0;
      rx_flag <= 2'b0;
      tx_flag <= 2'b0;
      clk_crossing <= 1'b0;
    end else begin
      if (clk_crossing) begin
        data_in <= data_out;
        bit_count <= 3'b0;
        mode <= 2'b0;
        clk_phase <= 2'b0;
        clk_polarity <= 2'b0;
        rx_flag <= 2'b0;
        tx_flag <= 2'b0;
        clk_crossing <= 1'b0;
      end else begin
        if (i_SPI_CS_n) begin
          if (mode == 2'b0) begin
            if (clk_phase == 2'b0) begin
              if (i_TX_DV) begin
                data_out <= i_TX_Byte;
                bit_count <= 3'b0;
                mode <= 2'b1;
                clk_phase <= 2'b1;
                clk_polarity <= 2'b0;
                tx_flag <= 2'b1;
              end else begin
                bit_count <= bit_count + 1'b1;
                if (bit_count == 8'b11111111) begin
                  rx_flag <= 2'b1;
                end
              end
            end else begin
              if (i_RX_DV) begin
                data_in <= data_out;
                bit_count <= 3'b0;
                mode <= 2'b1;
                clk_phase <= 2'b0;
                rx_flag <= 2'b1;
              end else begin
                bit_count <= bit_count + 1'b1;
                if (bit_count == 8'b11111111) begin
                  tx_flag <= 2'b1;
                end
              end
            end
          end else if (mode == 2'b1) begin
            if (clk_phase == 2'b0) begin
              if (i_TX_DV) begin
                data_out <= i_TX_Byte;
                bit_count <= 3'b0;
                mode <= 2'b0;
                clk_phase <= 2'b1;
                clk_polarity <= 2'b0;
                tx_flag <= 2'b1;
              end else begin
                bit_count <= bit_count + 1'b1;
                if (bit_count == 8'b11111111) begin
                  rx_flag <= 2'b1;
                end
              end
            end else begin
              if (i_RX_DV) begin
                data_in <= data_out;
                bit_count <= 3'b0;
                mode <= 2'b0;
                clk_phase <= 2'b0;
                rx_flag <= 2'b1;
              end else begin
                bit_count <= bit_count + 1'b1;
                if (bit_count == 8'b11111111) begin
                  tx_flag <= 2'b1;
                end
              end
            end
          end
        end
      end
    end
  end

  // Output logic
  assign o_RX_DV = rx_flag;
  assign o_RX_Byte = data_in;
  assign o_SPI_MISO = data_out;
  assign o_SPI_MOSI = i_SPI_MOSI;
endmodule

