module Math_Divide(
	input CLK, 
	input [31:0] Divisor, 
	input [31:0] Divider,
	output [31:0] result, 
	output [31:0] remainder,
	inout done 
    );

reg [31:0] dividend, divisor, remainder, result;
reg [31:0] counter;
reg done;

always @(posedge CLK) begin
    if (done) begin
        result <= 0;
        remainder <= 0;
        done <= 0;
    end else begin
        if (dividend == 0) begin
            result <= 0;
            remainder <= 0;
            done <= 1;
        end else begin
            if (dividend >= divisor) begin
                remainder <= dividend - divisor;
                dividend <= remainder;
                counter <= counter + 1;
            end else begin
                result <= counter;
                remainder <= dividend;
                done <= 1;
            end
        end
    end
end

assign result = result;
assign remainder = remainder;
assign done = done;

endmodule

