module synchronize(
    input clk,
    input async_in,
    input reset,
    output reg sync_out
    );
    reg [1:0] state;
    reg [1:0] next_state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'b00;
            sync_out <= 1'b0;
        end else begin
            next_state <= state;
            if (state == 2'b00) begin
                if (async_in) begin
                    next_state <= 2'b01;
                end
            end else if (state == 2'b01) begin
                next_state <= 2'b10;
            end else if (state == 2'b10) begin
                next_state <= 2'b00;
                sync_out <= async_in;
            end
        end
        state <= next_state;
    end
endmodule

module pipelined_multiplier (
    input [size-1 : 0] a,
    input [size-1 : 0] b,
    input clk,
    output [2*size-1 : 0] pdt
);

parameter size = 8;
parameter level = 4;

reg [size-1 : 0] a_int;
reg [size-1 : 0] b_int;
reg [2*size-1 : 0] pdt_int[level];

always @(posedge clk) begin
    // Capture input values at each clock edge
    a_int <= a;
    b_int <= b;

    // Propagate intermediate results through each pipeline stage
    for (int i = 0; i < level; i++) begin
        pdt_int[i] <= pdt_int[i-1] * a_int + pdt_int[i-1] * b_int;
    end

    // Output the final product
    pdt <= pdt_int[level-1];
end

endmodule

