    .io_enq_bits_tl_state_source(io_enq_bits_tl_state_source), 
    .io_deq_ready(io_deq_ready), 
    .io_deq_valid(io_deq_valid), 
    .io_deq_bits_tl_state_size(io_deq_bits_tl_state_size), 
    .io_deq_bits_tl_state_source(io_deq_bits_tl_state_source)
  );

  // Register to track the queue's state
  reg [13:0] queue_state;
  reg maybe_full;

  // Internal signal connections
  reg [3:0] enq_bits;
  reg [3:0] deq_bits;
  reg enq_valid;
  reg deq_valid;
  reg enq_ready;
  reg deq_ready;

  // Reset logic
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      queue_state <= 14'b0;
      maybe_full <= 1'b0;
      enq_valid <= 1'b0;
      deq_valid <= 1'b0;
      enq_ready <= 1'b0;
      deq_ready <= 1'b0;
    end else begin
      if (io_enq_valid && io_enq_ready) begin
        enq_bits <= io_enq_bits_tl_state_size;
        enq_valid <= 1'b1;
        enq_ready <= 1'b1;
      end else if (io_deq_valid && io_deq_ready) begin
        deq_bits <= io_deq_bits_tl_state_size;
        deq_valid <= 1'b1;
        deq_ready <= 1'b1;
      end else begin
        enq_valid <= 1'b0;
        deq_valid <= 1'b0;
        enq_ready <= 1'b0;
        deq_ready <= 1'b0;
      end
    end
  end

  // Update the queue state based on enqueue and dequeue operations
  always @(posedge clock) begin
    if (enq_valid) begin
      queue_state <= queue_state + 1'b1;
      maybe_full <= 1'b1;
    end else if (deq_valid) begin
      queue_state <= queue_state - 1'b1;
      maybe_full <= 1'b0;
    end
  end

  // Output the valid dequeue signals and the corresponding state information
  always @(posedge clock) begin
    if (deq_valid) begin
      io_deq_valid <= 1'b1;
      io_deq_bits_tl_state_size <= deq_bits;
      io_deq_bits_tl_state_source <= io_deq_bits_tl_state_source;
    end else begin
      io_deq_valid <= 1'b0;
      io_deq_bits_tl_state_size <= 14'b0;
      io_deq_bits_tl_state_source <= 1'b0;
    end
  end

endmodule

