module wideexpr_00781(ctrl, u0, u1, u2, u3, u4, u5, u6, u7, s0, s1, s2, s3, s4, s5, s6, s7, y);
input [7:0] ctrl;
  input [0:0] u0;
  input [1:0] u1;
  input [2:0] u2;
  input [3:0] u3;
  input [4:0] u4;
  input [5:0] u5;
  input [6:0] u6;
  input [7:0] u7;
  input signed [0:0] s0;
  input signed [1:0] s1;
  input signed [2:0] s2;
  input signed [3:0] s3;
  input signed [4:0] s4;
  input signed [5:0] s5;
  input signed [6:0] s6;
  input signed [7:0] s7;
  output [127:0] y;

  // Intermediate signals
  wire [15:0] y0, y1, y2, y3, y4, y5, y6, y7;

  // Logic operations based on control signal
  assign y0 = (ctrl[5] == 1'b1) ? u0 : s0;
  assign y1 = (ctrl[5] == 1'b1) ? u1 : s1;
  assign y2 = (ctrl[5] == 1'b1) ? u2 : s2;
  assign y3 = (ctrl[5] == 1'b1) ? u3 : s3;
  assign y4 = (ctrl[5] == 1'b1) ? u4 : s4;
  assign y5 = (ctrl[5] == 1'b1) ? u5 : s5;
  assign y6 = (ctrl[5] == 1'b1) ? u6 : s6;
  assign y7 = (ctrl[5] == 1'b1) ? u7 : s7;

  // Sign extension and bit masking for y2, y4, y6, y7
  assign y2 = (ctrl[6] == 1'b1) ? {16'b0, y2} : y2;
  assign y4 = (ctrl[6] == 1'b1) ? {16'b0, y4} : y4;
  assign y6 = (ctrl[6] == 1'b1) ? {16'b0, y6} : y6;
  assign y7 = (ctrl[6] == 1'b1) ? {16'b0, y7} : y7;

  // Bit shifting for y3, y5
  assign y3 = (ctrl[7] == 1'b1) ? {16'b0, y3} : y3;
  assign y5 = (ctrl[7] == 1'b1) ? {16'b0, y5} : y5;

  // Concatenation of intermediate signals to produce the final output
  assign y = {y0, y1, y2, y3, y4, y5, y6, y7};
endmodule

