module serial2parallel(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
) begin
    reg [7:0] serial_data;
    reg [2:0] counter;
    reg valid_flag;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            serial_data <= 8'b0;
            counter <= 3'b0;
            valid_flag <= 1'b0;
        end else begin
            if (din_valid) begin
                serial_data <= serial_data << 1;
                serial_data[0] <= din_serial;
                counter <= counter + 1;
                if (counter == 8) begin
                    valid_flag <= 1'b1;
                    counter <= 3'b0;
                end
            end else begin
                valid_flag <= 1'b0;
            end
