module sincf #(parameter win=1, wout=5)
(
	input clk,
	input [win-1:0] din,
	output reg [wout-1:0] dout
);
reg [win-1:0] mem [0:23];
reg [wout-1:0] sum;

always @(posedge clk) begin
    // Shift the register to the right
    for (int i = 23; i > 0; i = i - 1) begin
        mem[i] = mem[i - 1];
    end
    // Capture the current input
    mem[0] = din;
    // Calculate the sum of the last 24 inputs
    sum = 0;
    for (int i = 0; i < win; i = i + 1) begin
        sum = sum + mem[i];
    end
    // Output the sum
    dout = sum;
end
endmodule

