module uart_send(
  input sys_clk,
  input sys_rst_n,
  input uart_en,
  input [7:0] uart_din,
  output reg uart_txd
);

  // Register to track the state of the transmission
  reg [1:0] tx_flag;
  // Register to hold the data to be transmitted
  reg [7:0] tx_data;
  // Counter to track the number of clock cycles
  reg clk_cnt;
  // Counter to track the number of data bits
  reg tx_cnt;

  // Double flip-flop for enable signal
  reg [1:0] enable_reg;
  reg [1:0] enable_reg_next;

  // Clock and reset signals
  reg clk;
  reg rst;

  // State machine to control the transmission
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      tx_flag <= 2'b00;
      tx_data <= 8'b00000000;
      clk_cnt <= 0;
      tx_cnt <= 0;
      enable_reg <= 2'b00;
    end else begin
      enable_reg_next <= enable_reg;
      if (uart_en) begin
        enable_reg_next <= 2'b01;
      end
      if (enable_reg == 2'b01) begin
        if (clk_cnt == 0) begin
          tx_flag <= 2'b01;
          tx_cnt <= 0;
          clk_cnt <= 1;
        end else if (clk_cnt == 1) begin
          tx_flag <= 2'b10;
          tx_cnt <= 1;
          clk_cnt <= 2;
        end else if (clk_cnt == 2) begin
          tx_flag <= 2'b11;
          tx_cnt <= 2;
          clk_cnt <= 3;
        end else if (clk_cnt == 3) begin
          tx_flag <= 2'b00;
          tx_cnt <= 3;
          clk_cnt <= 0;
          if (tx_cnt == 3) begin
            tx_flag <= 2'b00;
            tx_cnt <= 0;
            clk_cnt <= 0;
            if (tx_data == 8'b11111111) begin
              tx_flag <= 2'b00;
              tx_cnt <= 0;
              clk_cnt <= 0;
              uart_txd <= 1'b0;
            end else begin
              tx_data <= tx_data << 1;
              tx_cnt <= 1;
              clk_cnt <= 2;
            end
          end
        end
      end
    end
    enable_reg <= enable_reg_next;
    clk <= sys_clk;
    rst <= sys_rst_n;
  end

endmodule

