module boardSynchroniser(
    input clk,
	 input synch_en,
    input toggle_en,
    input [1:0] cnt_n,
    input [1:0] cnt_m,
    input opMode,
    output reg synchroStatus = 1'b0,
    inout syncInOut
    );

    reg [1:0] state;
    reg [1:0] counter;
    reg [1:0] syncSignal;

    always @(posedge clk) begin
        if (toggle_en) begin
            state <= opMode;
        end

        if (state == 2'b00) begin
            counter <= cnt_n;
        end else if (state == 2'b01) begin
            counter <= cnt_m;
        end

        if (counter == cnt_m) begin
            syncSignal <= 1'b1;
        end else if (counter == cnt_n) begin
            syncSignal <= 1'b0;
        end

        if (state == 2'b10) begin
            state <= 2'b00;
        end
    end

    always @(posedge clk) begin
        if (toggle_en) begin
            if (syncSignal == 1'b1) begin
                syncInOut <= 1'b1;
            end else if (syncSignal == 1'b0) begin
                syncInOut <= 1'b0;
            end
        end
    end

    always @(posedge clk) begin
        if (toggle_en) begin
            if (opMode == 2'b00) begin
                synchroStatus <= syncSignal;
            end else if (opMode == 2'b01) begin
                synchroStatus <= 1'b1;
            end
        end
    end

endmodule

