         out2 <= out;
         out3 <= 0;
         state <= 1;
      end else if (state == 1) begin
         out3 <= out2;
         state <= 0;
      end
   end

   always @(posedge clk) begin
      if (state == 0) begin
         out <= out3;
      end else if (state == 1) begin
         out <= out2;
      end
   end

   always @(posedge clk) begin
      if (state == 0) begin
         case (addr)
            2'b00: out3 <= 16'b0000000000000000;
            2'b01: out3 <= 16'b0000000000000001;
            2'b10: out3 <= 16'b0000000000000010;
            2'b11: out3 <= 16'b0000000000000011;
            default: out3 <= 16'b0000000000000000;
         endcase
      end else if (state == 1) begin
         case (addr)
            2'b00: out2 <= 16'b0000000000000000;
            2'b01: out2 <= 16'b0000000000000001;
            2'b10: out2 <= 16'b0000000000000010;
            2'b11: out2 <= 16'b0000000000000011;
            default: out2 <= 16'b0000000000000000;
