module axi_bram_reader #
(
  parameter integer AXI_DATA_WIDTH = 32,
  parameter integer AXI_ADDR_WIDTH = 16,
  parameter integer BRAM_DATA_WIDTH = 32,
  parameter integer BRAM_ADDR_WIDTH = 10
)
(
  input  wire                       aclk,
  input  wire                       aresetn,

  input  wire [AXI_ADDR_WIDTH-1:0]  s_axi_awaddr,  
  input  wire                       s_axi_awvalid, 
  output wire                       s_axi_awready, 
  input  wire [AXI_DATA_WIDTH-1:0]  s_axi_wdata,   
  input  wire                       s_axi_wvalid,  
  output wire                       s_axi_wready,  
  output wire [1:0]                 s_axi_bresp,   
  output wire                       s_axi_bvalid,  
  input  wire                       s_axi_bready,  
  input  wire [AXI_ADDR_WIDTH-1:0]  s_axi_araddr,  
  input  wire                       s_axi_arvalid, 
  output wire                       s_axi_arready, 
  output wire [AXI_DATA_WIDTH-1:0]  s_axi_rdata,   
  output wire [1:0]                 s_axi_rresp,   
  output wire                       s_axi_rvalid,  
  input  wire                       s_axi_rready,  

  output wire                       bram_porta_clk,
  output wire                       bram_porta_rst,
  output wire [BRAM_ADDR_WIDTH-1:0] bram_porta_addr,
  input  wire [BRAM_DATA_WIDTH-1:0] bram_porta_rddata
);

  // Internal registers for state tracking
  reg [1:0] read_state;
  reg [AXI_ADDR_WIDTH-1:0] current_address;
  reg [AXI_DATA_WIDTH-1:0] current_data;
  reg s_axi_bvalid_reg;
  reg s_axi_rvalid_reg;

  // State machine for handling AXI read requests
  always @(posedge aclk or negedge aresetn) begin
    if (!aresetn) begin
      read_state <= 2'b00;
      current_address <= 0;
      current_data <= 0;
      s_axi_bvalid_reg <= 0;
      s_axi_rvalid_reg <= 0;
    end else begin
      case (read_state)
        2'b00: begin
          if (s_axi_arvalid) begin
            current_address <= s_axi_araddr;
            current_data <= 0;
            read_state <= 2'b01;
          end
        end
        2'b01: begin
          if (s_axi_wvalid) begin
            // Handle write request
          end
          if (s_axi_bvalid) begin
            s_axi_bvalid_reg <= 1;
          end
          if (s_axi_rvalid) begin
            s_axi_rvalid_reg <= 1;
          end
          read_state <= 2'b00;
        end
        2'b10: begin
          if (s_axi_rvalid) begin
            current_data <= s_axi_rdata;
            read_state <= 2'b01;
          end
        end
        default: begin
          read_state <= 2'b00;
        end
      endcase
    end
  end

  // AXI read request handling
  always @(posedge aclk or negedge aresetn) begin
    if (!aresetn) begin
      s_axi_bvalid <= 0;
      s_axi_rvalid <= 0;
    end else begin
      if (s_axi_arvalid && read_state == 2'b00) begin
        // Convert AXI address to BRAM-compatible address
        bram_porta_addr <= current_address;
        s_axi_bvalid <= 1;
        read_state <= 2'b01;
      end
    end
  end

  // BRAM read data handling
  always @(posedge aclk or negedge aresetn) begin
    if (!aresetn) begin
      s_axi_rdata <= 0;
      s_axi_rvalid <= 0;
    end else begin
      if (s_axi_bvalid_reg && read_state == 2'b01) begin
        // Fetch data from BRAM
        s_axi_rdata <= bram_porta_rddata;
        s_axi_rvalid <= 1;
        read_state <= 2'b10;
      end
    end
  end

endmodule

