module scan_hex_led_disp(
    input clk,reset,
    input [3:0] hex3,hex2,hex1,hex0,
    input [3:0] dp,
    output reg[3:0] en, 
    output reg[7:0] sseg
    );

    reg [3:0] digit_counter;
    reg [3:0] digit;
    reg [3:0] segment_pattern;
    reg [3:0] decimal_point_pattern;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            digit_counter <= 4'b0000;
            digit <= 4'b0000;
            segment_pattern <= 4'b0000;
            decimal_point_pattern <= 4'b0000;
            en <= 4'b0000;
            sseg <= 8'b00000000;
        end else begin
            digit_counter <= digit_counter + 1'b1;
            if (digit_counter == 4'b0001) begin
                digit_counter <= 4'b0000;
                digit <= hex3;
                segment_pattern <= hex_to_segment(hex3);
                decimal_point_pattern <= dp;
            end else if (digit_counter == 4'b0010) begin
                digit_counter <= 4'b0000;
                digit <= hex2;
                segment_pattern <= hex_to_segment(hex2);
                decimal_point_pattern <= dp;
            end else if (digit_counter == 4'b0011) begin
                digit_counter <= 4'b0000;
                digit <= hex1;
                segment_pattern <= hex_to_segment(hex1);
                decimal_point_pattern <= dp;
            end else if (digit_counter == 4'b0100) begin
                digit_counter <= 4'b0000;
                digit <= hex0;
                segment_pattern <= hex_to_segment(hex0);
                decimal_point_pattern <= dp;
            end
            en <= 4'b0001;
            sseg <= segment_pattern | decimal_point_pattern;
        end
    end

    function [3:0] hex_to_segment(input [3:0] hex);
        case (hex)
            4'b0000: hex_to_segment = 4'b00000000;
            4'b0001: hex_to_segment = 4'b00000001;
            4'b0010: hex_to_segment = 4'b00000010;
            4'b0011: hex_to_segment = 4'b00000011;
            4'b0100: hex_to_segment = 4'b00000100;
            4'b0101: hex_to_segment = 4'b00000101;
            4'b0110: hex_to_segment = 4'b00000110;
            4'b0111: hex_to_segment = 4'b00000111;
            4'b1000: hex_to_segment = 4'b00001000;
            4'b1001: hex_to_segment = 4'b00001001;
            4'b1010: hex_to_segment = 4'b00001010;
            4'b1011: hex_to_segment = 4'b00001011;
            4'b1100: hex_to_segment = 4'b00001100;
            4'b1101: hex_to_segment = 4'b00001101;
            4'b1110: hex_to_segment = 4'b00001110;
            4'b1111: hex_to_segment = 4'b00001111;
        endcase
    endfunction

endmodule

module linear_layer (
    input [63:0] x0, x1, x2, x3, x4,
    output [63:0] o0, o1, o2, o3, o4
) begin
    // Define the rotation shifts for each output
    localparam ROT0 = 5;
    localparam ROT1 = 3;
    localparam ROT2 = 1;
    localparam ROT3 = 7;
    localparam ROT4 = 2;

    // Compute the outputs using bitwise operations
    assign o0 = x0 ^ (x1 << ROT0) ^ (x2 << ROT1) ^ (x3 << ROT2) ^ (x4 << ROT3);
    assign o1 = x0 ^ (x1 << ROT1) ^ (x2 << ROT2) ^ (x3 << ROT3) ^ (x4 << ROT4);
    assign o2 = x0 ^ (x1 << ROT2) ^ (x2 << ROT3) ^ (x3 << ROT4) ^ (x4 << ROT0);
    assign o3 = x0 ^ (x1 << ROT3) ^ (x2 << ROT4) ^ (x3 << ROT0) ^ (x4 << ROT1);
    assign o4 = x0 ^ (x1 << ROT4) ^ (x2 << ROT0) ^ (x3 << ROT1) ^ (x4 << ROT2);
endmodule

module Barrel15L_16(
    input [13:0] data_i,
    input [1:0] shift_i,
    output reg [16:0] data_o
    );

    wire [16:0] tmp;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tmp <= 17'b0;
        end else begin
            tmp <= data_i[13:0] << shift_i;
        end
    end

    assign data_o = tmp;

endmodule

module decoder_3to8 
    (input [2:0] a,
     input enable,
     output reg [7:0] y
    );
always @(posedge clk or posedge rst) begin
    if (rst) begin
        y <= 8'b00000000;
    end else begin
        if (enable) begin
            case (a)
                3'b000: y <= 8'b00000001;
                3'b001: y <= 8'b00000010;
                3'b010: y <= 8'b00000100;
                3'b011: y <= 8'b00001000;
                3'b100: y <= 8'b00010000;
                3'b101: y <= 8'b00100000;
                3'b110: y <= 8'b01000000;
                3'b111: y <= 8'b10000000;
                default: y <= 8'b00000000;
            endcase
        end else begin
            y <= 8'b00000000;
        end
    end
endmodule

