module pddm (
	input sdi, 
	input signed_data, 
	output [31:0] dout, 
	input ock, uck, 
	input rstn, clk
) 
begin
    reg [31:0] sigma, undersampled_sigma;
    reg [31:0] delta, deriv;
    reg [31:0] prev_sigma;
    reg [31:0] prev_undersampled_sigma;
    reg [31:0] prev_delta;
    reg [31:0] prev_deriv;
    reg [31:0] prev_signed_data;
    reg [31:0] prev_ock;
    reg [31:0] prev_uck;
    reg [31:0] prev_rstn;
    reg [31:0] prev_clk;

    always @(posedge clk or posedge rstn) begin
        if (rstn) begin
            sigma <= 0;
            undersampled_sigma <= 0;
            delta <= 0;
            deriv <= 0;
            prev_sigma <= 0;
            prev_undersampled_sigma <= 0;
            prev_delta <= 0;
            prev_deriv <= 0;
            prev_signed_data <= 0;
            prev_ock <= 0;
            prev_uck <= 0;
            prev_rstn <= 0;
            prev_clk <= 0;
        end else begin
            if (ock) begin
                if (signed_data) begin
                    if (sdi) begin
                        sigma <= sigma + delta;
                        undersampled_sigma <= undersampled_sigma + delta;
                        delta <= delta + 1;
                        deriv <= deriv + 1;
                    end else begin
                        sigma <= sigma - delta;
                        undersampled_sigma <= undersampled_sigma - delta;
                        delta <= delta - 1;
                        deriv <= deriv - 1;
                    end
                end else begin
                    if (sdi) begin
                        sigma <= sigma + delta;
                        undersampled_sigma <= undersampled_sigma + delta;
                        delta <= delta + 1;
                        deriv <= deriv + 1;
                    end else begin
                        sigma <= sigma - delta;
                        undersampled_sigma <= undersampled_sigma - delta;
                        delta <= delta - 1;
                        deriv <= deriv - 1;
                    end
                end
            end
            if (uck) begin
                if (signed_data) begin
                    if (sdi) begin
                        sigma <= sigma - delta;
                        undersampled_sigma <= undersampled_sigma - delta;
                        delta <= delta - 1;
                        deriv <= deriv - 1;
                    end else begin
                        sigma <= sigma + delta;
                        undersampled_sigma <= undersampled_sigma + delta;
                        delta <= delta + 1;
                        deriv <= deriv + 1;
                    end
                end else begin
                    if (sdi) begin
                        sigma <= sigma - delta;
                        undersampled_sigma <= undersampled_sigma - delta;
                        delta <= delta - 1;
                        deriv <= deriv - 1;
                    end else begin
                        sigma <= sigma + delta;
                        undersampled_sigma <= undersampled_sigma + delta;
                        delta <= delta + 1;
                        deriv <= deriv + 1;
                    end
                end
            end
            prev_sigma <= sigma;
            prev_undersampled_sigma <= undersampled_sigma;
            prev_delta <= delta;
            prev_deriv <= deriv;
            prev_signed_data <= signed_data;
            prev_ock <= ock;
            prev_uck <= uck;
            prev_rstn <= rstn;
            prev_clk <= clk;
        end
    end

    always @(posedge clk or posedge rstn) begin
        if (rstn) begin
            dout <= 0;
        end else begin
            if (signed_data) begin
                if (sdi) begin
                    dout <= dout + (sigma - prev_sigma) * 2;
                end else begin
                    dout <= dout - (sigma - prev_sigma) * 2;
                end
            end else begin
                if (sdi) begin
                    dout <= dout + (sigma - prev_sigma) * 2;
                end else begin
                    dout <= dout - (sigma - prev_sigma) * 2;
                end
            end
        end
    end
endmodule

