module clk_div(input clk,
					input rst,
					input SW2,
					input SW15,
					input keyReady,
					input [3:0] BTN_OK,
					output reg[31:0]clkdiv,
					output Clk_CPU,
					output reg readn
					);
	parameter [31:0] DIVIDER = 32'h10000000; // Default clock division factor
	parameter [31:0] STEP_MODE = 32'h00000001; // Default step mode factor

	reg [31:0] step;
	reg [31:0] counter;
	reg [31:0] auto_clk;
	reg [31:0] wasReady;
	reg [31:0] readn;

	always @(posedge clk or posedge rst) begin
		if (rst) begin
			step <= 0;
			counter <= 0;
			auto_clk <= 0;
			wasReady <= 0;
			readn <= 0;
		end else begin
			if (SW2 == 1'b1) begin
				auto_clk <= DIVIDER;
			end else if (SW2 == 1'b0) begin
				auto_clk <= STEP_MODE;
			end

			if (keyReady) begin
				case (BTN_OK)
					4'b0000: step <= 0;
					4'b0001: step <= 1;
					4'b0010: step <= 2;
					4'b0011: step <= 3;
					4'b0100: step <= 4;
					4'b0101: step <= 5;
					4'b0110: step <= 6;
					4'b0111: step <= 7;
					4'b1000: step <= 8;
					4'b1001: step <= 9;
					4'b1010: step <= 10;
					4'b1011: step <= 11;
					4'b1100: step <= 12;
					4'b1101: step <= 13;
					4'b1110: step <= 14;
					4'b1111: step <= 15;
					default: step <= 0;
				endcase
			end

			if (counter == 0) begin
				counter <= auto_clk;
				wasReady <= 1;
			end else begin
				counter <= counter - 1;
				wasReady <= 0;
			end

			if (wasReady == 1) begin
				if (step > 0) begin
					counter <= step;
					wasReady <= 0;
				end
			end

			if (counter == 0) begin
				Clk_CPU <= 1'b1;
			end else begin
				Clk_CPU <= 1'b0;
			end

			if (counter == 0) begin
				readn <= 1'b1;
			end else begin
				readn <= 1'b0;
			end
		end
	end
endmodule

