module Fibonacci_Series
( 
    input wire CLK_IN,
    input wire RST_N,
    output wire [7:0]SEQUENCE
)
begin
    reg [7:0] last_fib, second_last_fib;
    reg [7:0] sum;
    reg [7:0] end_value;
    reg [7:0] current_value;

    // Initialize the registers
    always @(posedge CLK_IN or negedge RST_N) begin
        if (!RST_N) begin
            last_fib <= 8'b0;
            second_last_fib <= 8'b0;
            sum <= 8'b0;
            end_value <= 8'b0;
            current_value <= 8'b0;
        end else begin
            last_fib <= second_last_fib;
            second_last_fib <= current_value;
            sum <= last_fib + second_last_fib;
            current_value <= sum;
        end
    end

    // Check if the sequence has reached the end value
    always @(posedge CLK_IN or negedge RST_N) begin
        if (!RST_N) begin
            end_value <= 8'b0;
        end else begin
            end_value <= 8'b0;
            if (current_value == end_value) begin
                SEQUENCE <= 8'b0;
            end else begin
                SEQUENCE <= current_value;
            end
        end
    end
endmodule

