module instMem(
    input  wire        clk,
    input  wire        reset,
    input  wire [31:0] address,
    output wire [31:0] inst
) begin
    // Initialize memory contents from a specified text file
    reg [31:0] mem [0:255];
    initial begin
        $readmemh("instructions.txt", mem);
    end

    // Fetch instruction from memory
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            inst <= 32'h0;
        end else begin
            inst <= mem[address[7:0]];
        end
    end
endmodule

module memory(clk, reset, data_op, instruct_addr, data_addr, write_val, instruct_val, read_val); 
  reg [31:0] memory [0:511];  // 512 words, each 32 bits wide
  reg [31:0] instruct_val;
  reg [31:0] read_val;

  // Initialize memory with first 11 locations set to 5 during reset
  initial begin
    if (reset) begin
      for (int i = 0; i < 11; i++) begin
        memory[i] = 5;
      end
      instruct_val = 0;
      read_val = 0;
    end
  end

  // Sequential logic triggered by clock or reset
  always @(posedge clk or negedge reset) begin
    if (!reset) begin
      instruct_val = 0;
      read_val = 0;
    end else begin
      if (data_op == 1) begin
        instruct_val = memory[instruct_addr];
      end else begin
        memory[data_addr] = write_val;
        read_val = memory[data_addr];
      end
    end
  end
endmodule

