module matrix5arb (
    input clk,
    input rst_n,
    input [4:0] req,
    output [4:0] grant
    );

    // State registers to track priority levels
    reg [2:0] priority_level;
    reg [2:0] next_priority_level;

    // Variables to track the current request and grant
    reg [4:0] current_request;
    reg [4:0] current_grant;

    // State machine to manage the arbiter's behavior
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            priority_level <= 3'b000;
            next_priority_level <= 3'b000;
            current_request <= 5'b00000;
            current_grant <= 5'b00000;
        end else begin
            // Update priority level based on the current request
            if (req[4] == 1'b1) begin
                next_priority_level <= priority_level + 1'b1;
            end else begin
                next_priority_level <= priority_level;
            end

            // Update the current request and grant
            if (priority_level == 3'b000) begin
                current_request <= req;
                current_grant <= req;
            end else begin
                current_request <= current_grant;
                current_grant <= req;
            end

            // Update the priority level
            priority_level <= next_priority_level;
        end
    end

    // Output the grant signal
    assign grant = current_grant;

endmodule

module routing_buffer(clock, resetn, 
  i_datain, i_datain_valid, o_datain_stall, 
  o_dataout, i_dataout_stall, o_dataout_valid);

input clock, resetn;
input [DATA_WIDTH-1:0] i_datain;
input i_datain_valid;
output reg o_datain_stall;
output reg [DATA_WIDTH-1:0] o_dataout;
input i_dataout_stall;
output reg o_dataout_valid;

parameter INSERT_REGISTER = 1;

reg [DATA_WIDTH-1:0] data_in_reg;
reg data_in_valid_reg;
reg data_out_reg;
reg data_out_valid_reg;

always @(posedge clock or negedge resetn) begin
  if (!resetn) begin
    data_in_reg <= 0;
    data_in_valid_reg <= 0;
    data_out_reg <= 0;
    data_out_valid_reg <= 0;
    o_datain_stall <= 0;
    o_dataout_stall <= 0;
    o_dataout_valid <= 0;
  end else begin
    if (INSERT_REGISTER) begin
      data_in_reg <= i_datain;
      data_in_valid_reg <= i_datain_valid;
      if (data_in_valid_reg) begin
        data_out_reg <= data_in_reg;
        data_out_valid_reg <= 1;
      end else begin
        data_out_reg <= 0;
        data_out_valid_reg <= 0;
      end
    end else begin
      data_in_reg <= i_datain;
      data_in_valid_reg <= i_datain_valid;
      data_out_reg <= i_datain;
      data_out_valid_reg <= i_datain_valid;
    end
    if (i_dataout_stall) begin
      o_datain_stall <= 1;
      o_dataout_stall <= 1;
      o_dataout_valid <= 0;
    end else begin
      o_datain_stall <= 0;
      o_dataout_stall <= 0;
      o_dataout_valid <= data_out_valid_reg;
    end
  end
end

assign o_dataout = data_out_reg;
assign o_dataout_valid = data_out_valid_reg;

endmodule

