intermediate_wires[4] = intermediate_wires[0] | intermediate_wires[1];
intermediate_wires[5] = intermediate_wires[2] | intermediate_wires[3];
intermediate_wires[6] = intermediate_wires[4] | intermediate_wires[5];
intermediate_wires[7] = intermediate_wires[6] | intermediate_wires[7];

