module TopModule (
    input  [3:0] x,
    input  [3:0] y,
    output reg [4:0] sum
);

    // 4-bit adder with full adders
    always @(posedge clk or negedge rst) begin
        if (~rst) begin
            sum <= 5'b00000;
        end else begin
            reg [3:0] carry = 0;
            reg [3:0] temp_sum = 0;

            for (int i = 0; i < 4; i++) begin
                temp_sum = x[i] ^ y[i] ^ carry;
                carry = (x[i] & y[i]) | (x[i] & carry) | (y[i] & carry);
                sum[i] <= temp_sum;
            end

            // Check for overflow
            if (carry == 1) begin
                sum[4] <= 1'b1;
            end else begin
                sum[4] <= 1'b0;
            end
        end
    end

endmodule

