    // Create a 256-bit array to hold the 4-bit inputs
    reg [3:0] inputs [0:255];

    // Assign the 4-bit inputs to the array based on the sel value
    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            for (int i = 0; i <= 255; i = i + 1) begin
                inputs[i] = 4'b0000;
            end
        end else begin
            for (int i = 0; i <= 255; i = i + 1) begin
                inputs[i] = in[32*i:32*i+3];
            end
        end
    end

    // Select the appropriate 4-bit input based on the sel value
    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            out = 4'b0000;
        end else begin
            out = inputs[sel];
