module TopModule (
    input clk,
    input resetn,
    input in,
    output out
);

    // Define the shift register with four D flops
    reg [3:0] shiftRegister;

    // Assign the input to the first D flip flop
    assign shiftRegister[0] = in;

    // Shift the register to the left on the positive edge of the clock
    always @(posedge clk or posedge resetn) begin
        if (!resetn) begin
            shiftRegister <= 4'b0000;
        end else begin
            shiftRegister <= {shiftRegister[3:0], in};
        end
    end

    // Assign the output from the last D flip flop
    assign out = shiftRegister[3];

