    input w,
    input R,
    input E,
    input L,
    output Q
);

    // Declare a shift register with n bits
    reg [7:0] shiftRegister;

    // Process the shift register based on the input signals
    always @(posedge clk) begin
        if (E) begin
            // Load the value from R into the shift register
            shiftRegister <= R;
        end else if (L) begin
            // Load the value from w into the shift register
            shiftRegister <= w;
        end else if (R || L) begin
            // Shift the register to the left by one bit
            shiftRegister <= {shiftRegister[6:0], shiftRegister[7]};
        end
    end

    // Output the current value of the shift register
    assign Q = shiftRegister[0];

endmodule

