        end else begin
            if (slowena) begin
                case (state)
                    2'b00: begin
                        count <= count + 1'b1;
                        if (count == 4'b1000) begin
                            state <= 2'b01;
                        end
                    end
                    2'b01: begin
                        count <= count + 1'b1;
                        if (count == 4'b1000) begin
                            state <= 2'b00;
                        end
                    end
                    default: begin
                        state <= 2'b00;
                    end
                endcase
            end else begin
                count <= count + 1'b1;
