    input areset,
    input x,
    output z
);

    // Define the states of the Mealy finite-state machine
    typedef enum {A, B} state_t;

    // Define the one-hot encoding for the states
    typedef struct {
        bit [1:0] state;
    } state_onehot_t;

    // Define the state register
    state_onehot_t state_reg;

    // Define the output register
    reg [1:0] z_reg;

    // Define the state transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state_reg.state <= A;
            z_reg <= 2'b00;
        end else begin
            case (state_reg.state)
                A: begin
                    if (x == 0) begin
                        state_reg.state <= A;
                        z_reg <= 2'b00;
                    end else begin
                        state_reg.state <= B;
                        z_reg <= 2'b01;
                    end
                end
                B: begin
                    if (x == 0) begin
                        state_reg.state <= B;
                        z_reg <= 2'b01;
                    end else begin
                        state_reg.state <= A;
                        z_reg <= 2'b10;
                    end
                end
            endcase
        end
    end

    // Assign the output to the z_reg
    assign z = z_reg;

endmodule

