module TopModule (
    input clk,
    input areset,
    input bump_left,
    input bump_right,
    output wire walk_left,
    output wire walk_right
);

    // Define the states of the Moore state machine
    typedef enum {LEFT, RIGHT} State;

    // Define the internal state variable
    reg [1:0] state;

    // Define the output wire
    wire [1:0] output;

    // Define the state transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= LEFT;
            output <= LEFT;
        end else begin
            case (state)
                LEFT: begin
                    if (bump_left) begin
                        state <= RIGHT;
                    end else if (bump_right) begin
                        state <= LEFT;
                    end else begin
                        state <= LEFT;
                    end
                end
                RIGHT: begin
                    if (bump_left) begin
                        state <= LEFT;
                    end else if (bump_right) begin
                        state <= RIGHT;
                    end else begin
                        state <= RIGHT;
                    end
                end
            endcase
            output <= state;
        end
    end

    // Assign the output wire to the walk_left and walk_right ports
    assign walk_left = output[0];
    assign walk_right = output[1];

endmodule

