            reset <= 1'b1;
            clk_in <= 1'b0;
        end else begin
            gshare_index <= gshare_index + 1'b1;
            gshare_history <= gshare_history + 1'b1;
            gshare_table <= gshare_table + 1'b1;
            gshare_table_entry <= gshare_table_entry + 1'b1;
            branch_history <= branch_history + 1'b1;
            pht <= pht + 1'b1;
            pht_entry <= pht_entry + 1'b1;
            predict_state <= predict_state + 1'b1;
            train_state <= train_state + 1'b1;
            predict_taken_out <= predict_taken_out + 1'b1;
            predict_history_out <= predict_history_out + 1'b1;
            predict_valid_in <= predict_valid;
            predict_pc_in <= predict_pc;
            train_valid_in <= train_valid;
            train_taken_in <= train_taken;
            train_mispredicted_in <= train_mispredicted;
            train_history_in <= train_history;
            train_pc_in <= train_pc;
            reset <= reset;
            clk_in <= clk;
        end
    end

    // Define the branch predictor logic
    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            predict_state <= 2'b0;
            train_state <= 2'b0;
        end else begin
            if (predict_valid_in) begin
                gshare_index <= predict_pc_in[6:0];
                gshare_history <= predict_pc_in[6:0];
                gshare_table_entry[gshare_index] <= gshare_table_entry[gshare_index] + 1'b1;
                if (gshare_table_entry[gshare_index] == 2'b11) begin
                    gshare_table_entry[gshare_index] <= 2'b00;
                end
                predict_state <= 2'b0;
            end else if (train_valid_in) begin
                if (train_mispredicted_in) begin
                    gshare_table_entry[gshare_index] <= 2'b00;
                end
                pht_entry[gshare_index] <= train_history_in;
                predict_state <= 2'b0;
            end else begin
                if (predict_state == 2'b0) begin
                    gshare_index <= gshare_index + 1'b1;
                    gshare_history <= gshare_history + 1'b1;
                    gshare_table_entry[gshare_index] <= gshare_table_entry[gshare_index] + 1'b1;
                    if (gshare_table_entry[gshare_index] == 2'b11) begin
                        gshare_table_entry[gshare_index] <= 2'b00;
                    end
                    predict_state <= 2'b0;
                end else if (predict_state == 2'b1) begin
                    predict_taken_out <= gshare_table_entry[gshare_index];
                    predict_history_out <= gshare_history;
                    predict_state <= 2'b0;
                end else if (predict_state == 2'b2) begin
                    predict_taken_out <= pht_entry[gshare_index];
                    predict_history_out <= gshare_history;
                    predict_state <= 2'b0;
                end
            end
        end
    end

    // Define the branch predictor output
    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            predict_taken_out <= 1'b0;
            predict_history_out <= 7'b0;
        end else begin
            predict_taken_out <= predict_taken_out;
