module TopModule (
    input clk,
    input areset,
    input bump_left,
    input bump_right,
    input ground,
    input dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // Define the states of the FSM
    typedef enum {IDLE, FALLING, DIGGING, SPLATTERING} FSM_STATE;

    // Initialize the FSM state
    FSM_STATE current_state = IDLE;

    // Define the state transitions
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= IDLE;
            walk_left <= 0;
            walk_right <= 0;
            aaah <= 0;
            digging <= 0;
        end else begin
            case (current_state)
                IDLE: begin
                    if (bump_left) begin
                        current_state <= FALLING;
                        walk_left <= 0;
                        walk_right <= 1;
                    end else if (bump_right) begin
                        current_state <= FALLING;
                        walk_left <= 1;
                        walk_right <= 0;
                    end else if (ground) begin
                        current_state <= DIGGING;
                        walk_left <= 0;
                        walk_right <= 0;
                    end else begin
                        current_state <= IDLE;
                    end
                end
                FALLING: begin
                    if (ground) begin
                        current_state <= DIGGING;
                        walk_left <= 0;
                        walk_right <= 0;
                    end else begin
                        current_state <= FALLING;
                    end
                end
                DIGGING: begin
                    if (ground) begin
                        current_state <= IDLE;
                        walk_left <= 0;
                        walk_right <= 0;
                    end else begin
                        current_state <= DIGGING;
                    end
                end
                SPLATTERING: begin
                    current_state <= SPLATTERING;
                end
            endcase
        end
    end

    // Assign the outputs based on the current state
    assign walk_left = current_state == IDLE || current_state == FALLING || current_state == DIGGING;
    assign walk_right = current_state == IDLE || current_state == FALLING || current_state == DIGGING;
    assign aaah = current_state == IDLE || current_state == FALLING || current_state == DIGGING;
    assign digging = current_state == IDLE || current_state == FALLING || current_state == DIGGING;

endmodule

