                        state <= S_RUN;
                        cnt_val_n <= cnt_val_i;
                        cnt_n <= cnt_i;
                    end
                end
                S_RUN: begin
                    if (cnt_n == cnt_val_n) begin
                        state <= S_DONE;
                        done <= 1;
                    end
                end
                S_DONE: begin
                    state <= S_IDLE;
                    run <= 0;
                end
            endcase
        end
    end

    // Output generation
    assign run_o = run;
    assign done_o = done;
endmodule

