        mul3 = u2 * s2;
        mul4 = u3 * s3;
        mul5 = u4 * s4;
        mul6 = u5 * s5;
        mul7 = u6 * s6;
    end

    always @(posedge ctrl3) begin
        div1 = u0 / s0;
        div2 = u1 / s1;
        div3 = u2 / s2;
        div4 = u3 / s3;
        div5 = u4 / s4;
        div6 = u5 / s5;
        div7 = u6 / s6;
    end

    // Logical operations
    always @(posedge ctrl4) begin
        and1 = u0 & s0;
        and2 = u1 & s1;
        and3 = u2 & s2;
        and4 = u3 & s3;
        and5 = u4 & s4;
        and6 = u5 & s5;
        and7 = u6 & s6;
    end

    always @(posedge ctrl5) begin
        or1 = u0 | s0;
        or2 = u1 | s1;
        or3 = u2 | s2;
        or4 = u3 | s3;
        or5 = u4 | s4;
        or6 = u5 | s5;
        or7 = u6 | s6;
    end

    always @(posedge ctrl6) begin
        xor1 = u0 ^ s0;
        xor2 = u1 ^ s1;
        xor3 = u2 ^ s2;
        xor4 = u3 ^ s3;
        xor5 = u4 ^ s4;
        xor6 = u5 ^ s5;
        xor7 = u6 ^ s6;
    end

    // Shifting operations
    always @(posedge ctrl7) begin
        shift1 = u0 << s0;
        shift2 = u1 << s1;
        shift3 = u2 << s2;
        shift4 = u3 << s3;
        shift5 = u4 << s4;
        shift6 = u5 << s5;
        shift7 = u6 << s6;
    end

    // Internal signal computation
    always @(posedge ctrl0) begin
        y0 = add1;
    end

    always @(posedge ctrl1) begin
        y1 = sub1;
    end

    always @(posedge ctrl2) begin
        y2 = mul1;
    end

    always @(posedge ctrl3) begin
        y3 = div1;
    end

    always @(posedge ctrl4) begin
        y4 = and1;
    end

    always @(posedge ctrl5) begin
        y5 = or1;
    end

    always @(posedge ctrl6) begin
        y6 = xor1;
    end

    always @(posedge ctrl7) begin
        y7 = shift1;
    end

    // Output concatenation
    always @(posedge ctrl0) begin
        y = y0;
    end

    always @(posedge ctrl1) begin
        y = y0 | y1;
    end

    always @(posedge ctrl2) begin
        y = y0 | y1 | y2;
    end

    always @(posedge ctrl3) begin
        y = y0 | y1 | y2 | y3;
    end

    always @(posedge ctrl4) begin
        y = y0 | y1 | y2 | y3 | y4;
    end

    always @(posedge ctrl5) begin
