    end

    always @(posedge ctrl6) begin
        y = y0 | y1 | y2 | y3 | y4 | y5 | y6;
    end

    always @(posedge ctrl7) begin
        y = y0 | y1 | y2 | y3 | y4 | y5 | y6 | y7;
    end

endmodule

