      pc <= 0;
      halt <= 0;
      for (int i = 0; i < 4096; i++) begin
        instructionMemory[i] <= {19'b0, i}; // Initialize with 19-bit values
      end
    end else begin
      pc <= PC;
      outInst <= instructionMemory[pc];
      halt <= (outInst == 19'b0); // Check if the instruction is zero
    end
  end

  // Output the halt signal
  assign halt = halt;
