module sparc_ifu_esl_lfsr
(
    input               clk,
    input               rst_n,


    input [15:0]        lfsr_seed,
    input               lfsr_ld,


    input               lfsr_step,


    output reg [15:0]   lfsr_state_f,


    output reg          lfsr_out_f
)
begin
    reg [15:0] current_state;
    reg [15:0] next_state;
    reg [15:0] feedback;

    // Initialize the LFSR with the seed
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= 16'b0;
        end else begin
            if (lfsr_ld) begin
                current_state <= lfsr_seed;
            end else if (lfsr_step) begin
                next_state <= current_state;
                feedback <= current_state[15] ^ current_state[14] ^ current_state[13] ^ current_state[12];
                next_state[15] <= feedback;
                current_state <= next_state;
            end
        end
    end

    // Output the most significant bit of the current state
    assign lfsr_out_f = current_state[15];

    // Output the current state
    assign lfsr_state_f = current_state;
end

