module FFlr(
input wire clk,
input wire [31:0] f,
output reg [31:0] g
);

reg [31:0] len_raw, x_mask, f_masked, f_incr, f_out, res;
reg [31:0] g_reg1, g_reg2;

always @(posedge clk) begin
    // Compute len_raw
    len_raw <= f[30:23] - 255;

    // Compute x_mask
    x_mask <= (len_raw[0] == 1'b1) ? 32'b1 : 32'b0;

    // Compute f_masked
    f_masked <= f & x_mask;

    // Compute f_incr
    f_incr <= f_masked;

    // Compute f_out
    f_out <= (f[31] == 1'b1) ? f_masked : f_incr;

    // Combine f's sign with modified lower bits
    res <= (f[31] == 1'b1) ? (f[30:23] << 24) | (f[22:0]) : (f[30:23] << 24) | (f[22:0]);

    // Pipeline into g through two registers
    g_reg1 <= res;
    g_reg2 <= g_reg1;
    g <= g_reg2;
end

endmodule

