module button_pulse 
#(
    parameter MAX_COUNT = 8,    
    parameter DEC_COUNT = 2,    
    parameter MIN_COUNT = 1     
)(
    input wire clk,
    input wire clk_en,
    input wire button,
    input wire reset,
    output wire pulse
);

    reg [7:0] comp;
    reg [7:0] count;
    reg [7:0] prev_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            comp <= MAX_COUNT - 1;
            count <= 0;
            prev_count <= 0;
        end else begin
            if (clk_en) begin
                if (button) begin
                    if (count == 0) begin
                        comp <= MAX_COUNT - 1;
                        count <= 0;
                        prev_count <= 0;
                    end else begin
                        comp <= comp - DEC_COUNT;
                        count <= count + 1;
                        prev_count <= count;
                    end
                end else begin
                    comp <= MAX_COUNT - 1;
                    count <= 0;
                    prev_count <= 0;
                end
            end
        end
    end

    always @(posedge clk) begin
        if (button && count == 0 && comp == MIN_COUNT) begin
            pulse <= 1;
        end else begin
            pulse <= 0;
        end
    end

endmodule

