    input signed [31:0] x2,
    input signed [31:0] x3,
    output [127:0] y
);

    // Internal constants
    localparam [31:0] p0 = 32'h00000000;
    localparam [31:0] p1 = 32'h00000001;
    localparam [31:0] p2 = 32'h00000002;
    localparam [31:0] p3 = 32'h00000003;

    // Internal wires
    wire [31:0] x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15;

    // Internal variables
    reg [31:0] y0, y1, y2, y3;

    // Internal logic
    always @(posedge ctrl) begin
        case (ctrl)
            4'b0000: begin
                y0 = x0 + p0;
                y1 = x1 + p1;
                y2 = x2 + p2;
                y3 = x3 + p3;
            end
            4'b0001: begin
                y0 = x0 - p0;
                y1 = x1 - p1;
                y2 = x2 - p2;
                y3 = x3 - p3;
            end
            4'b0010: begin
                y0 = x0 * p0;
                y1 = x1 * p1;
                y2 = x2 * p2;
                y3 = x3 * p3;
            end
            4'b0011: begin
                y0 = x0 / p0;
                y1 = x1 / p1;
                y2 = x2 / p2;
                y3 = x3 / p3;
            end
            4'b0100: begin
                y0 = x0 & p0;
                y1 = x1 & p1;
                y2 = x2 & p2;
                y3 = x3 & p3;
            end
            4'b0101: begin
                y0 = x0 | p0;
                y1 = x1 | p1;
                y2 = x2 | p2;
                y3 = x3 | p3;
            end
            4'b0110: begin
                y0 = x0 ^ p0;
                y1 = x1 ^ p1;
                y2 = x2 ^ p2;
                y3 = x3 ^ p3;
            end
            4'b0111: begin
                y0 = x0 << p0;
                y1 = x1 << p1;
                y2 = x2 << p2;
                y3 = x3 << p3;
            end
            4'b1000: begin
                y0 = x0 >> p0;
                y1 = x1 >> p1;
                y2 = x2 >> p2;
                y3 = x3 >> p3;
            end
            4'b1001: begin
                y0 = x0 & ~p0;
                y1 = x1 & ~p1;
                y2 = x2 & ~p2;
                y3 = x3 & ~p3;
            end
            4'b1010: begin
                y0 = x0 | ~p0;
                y1 = x1 | ~p1;
                y2 = x2 | ~p2;
                y3 = x3 | ~p3;
            end
            4'b1011: begin
                y0 = x0 ^ ~p0;
                y1 = x1 ^ ~p1;
                y2 = x2 ^ ~p2;
                y3 = x3 ^ ~p3;
            end
            4'b1100: begin
                y0 = x0 << ~p0;
                y1 = x1 << ~p1;
                y2 = x2 << ~p2;
                y3 = x3 << ~p3;
            end
            4'b1101: begin
                y0 = x0 >> ~p0;
                y1 = x1 >> ~p1;
                y2 = x2 >> ~p2;
                y3 = x3 >> ~p3;
            end
            4'b1110: begin
                y0 = x0 & p0;
                y1 = x1 & p1;
                y2 = x2 & p2;
                y3 = x3 & p3;
            end
            4'b1111: begin
                y0 = x0 | p0;
                y1 = x1 | p1;
                y2 = x2 | p2;
                y3 = x3 | p3;
            end
        endcase
    end

    // Output concatenation
    assign y = {y0, y1, y2, y3};

endmodule

module echo_server_application_m_axis_read_package_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);

    // FSM states
    typedef enum {ZERO, ONE, TWO} state_t;
    state_t state, next;

    // Registers
    reg [N-1:0] data_p1, data_p2;
    reg load_p1, load_p2, load_p1_from_p2;

    // Control signals
    reg s_ready_t;

    // FSM logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= ZERO;
            data_p1 <= 0;
            data_p2 <= 0;
            load_p1 <= 0;
            load_p2 <= 0;
            load_p1_from_p2 <= 0;
            s_ready_t <= 0;
        end else begin
            state <= next;
            if (state == ZERO) begin
                if (s_valid && m_ready) begin
                    data_p1 <= s_data;
                    load_p1 <= 1;
                    load_p2 <= 0;
                    load_p1_from_p2 <= 0;
                    s_ready_t <= 1;
                end else if (load_p1) begin
                    data_p1 <= data_p1;
                    load_p1 <= 0;
                end
            end else if (state == ONE) begin
                if (s_valid && m_ready) begin
                    data_p2 <= s_data;
                    load_p1 <= 0;
                    load_p2 <= 1;
                    load_p1_from_p2 <= 0;
                    s_ready_t <= 1;
                end else if (load_p2) begin
                    data_p2 <= data_p2;
                    load_p2 <= 0;
                end
            end else if (state == TWO) begin
                if (s_valid && m_ready) begin
                    m_data <= data_p1;
                    m_valid <= 1;
                    load_p1 <= 0;
                    load_p2 <= 0;
                    load_p1_from_p2 <= 0;
                    s_ready_t <= 1;
                end else if (load_p1_from_p2) begin
                    m_data <= data_p2;
                    m_valid <= 1;
                    load_p1 <= 0;
                    load_p2 <= 0;
                    load_p1_from_p2 <= 0;
                    s_ready_t <= 1;
                end
            end
        end
    end

    // Control signals assignment
    assign s_ready = s_ready_t;
    assign m_data = data_p1;
    assign m_valid = load_p1;

endmodule

