module leddec16(
input wire [1:0] dig,
input wire [15:0] data,
output wire [3:0] anode,
output wire [6:0] seg
);

// Lookup table for segment patterns
reg [6:0] seg_table [0:15] = {
    7'b0000000,  // 0
    7'b1111111,  // 1
    7'b0000110,  // 2
    7'b1011011,  // 3
    7'b1001111,  // 4
    7'b1100110,  // 5
    7'b1101101,  // 6
    7'b0111111,  // 7
    7'b1111001,  // 8
    7'b1110001,  // 9
    7'b1111110,  // A
    7'b1111010,  // B
    7'b0011111,  // C
    7'b1001110,  // D
    7'b1111100,  // E
    7'b1110100   // F
};

// Lookup table for anode control
reg [3:0] anode_table [0:15] = {
    4'b0000,  // 0
    4'b0001,  // 1
    4'b0010,  // 2
    4'b0011,  // 3
    4'b0100,  // 4
    4'b0101,  // 5
    4'b0110,  // 6
    4'b0111,  // 7
    4'b1000,  // 8
    4'b1001,  // 9
    4'b1010,  // A
    4'b1011,  // B
    4'b1100,  // C
    4'b1101,  // D
    4'b1110,  // E
    4'b1111   // F
};

// Decode the data and generate the anode and segment outputs
always @(posedge clk or negedge rst) begin
    if (~rst) begin
        anode <= 4'b0000;
        seg <= 7'b0000000;
    end else begin
        // Determine the digit to display
        reg [3:0] digit = dig;

        // Determine the data bits to display
        reg [3:0] data_bits = data[11:8];

        // Generate the anode output
        anode <= anode_table[data_bits];

        // Generate the segment output
        seg <= seg_table[data_bits];
    end
end

endmodule

