          data_mem[write_ptr] <= data_i;
          write_ptr <= next_write_ptr;
          if (write_ptr == 12'b108) begin
            full <= 1'b1;
          end
        end else begin
          ready_o <= 1'b0;
        end
      end else begin
        ready_o <= 1'b1;
      end
    end else begin
      ready_o <= 1'b1;
    end
  end
end

always @(posedge clk_i or posedge reset_i) begin
  if (reset_i) begin
    next_write_ptr <= 12'b0;
    next_read_ptr <= 12'b0;
  end else begin
    if (v_i) begin
      if (yumi_i) begin
        if (read_ptr < 12'b108) begin
          data_o <= data_mem[read_ptr];
          read_ptr <= next_read_ptr;
          if (read_ptr == 12'b108) begin
            empty <= 1'b0;
          end
        end else begin
          ready_o <= 1'b0;
        end
      end else begin
        ready_o <= 1'b1;
      end
    end else begin
      ready_o <= 1'b1;
    end
  end
end

assign full = write_ptr == 12'b108;
assign empty = read_ptr == 12'b0;
assign next_write_ptr = write_ptr + 1'b1;
assign next_read_ptr = read_ptr + 1'b1;
endmodule

module muladd_3_stage_unsigned_17_bit_xor_reduction(
	input  [16:0] a,
	input  [16:0] b,
	input  [16:0] c,
	output [16:0] out,
	input clk);

reg [33:0] stage0, stage1, stage2;
reg [16:0] product, sum;

always @(posedge clk) begin
    // Stage 0: Multiply a and b
    product <= a * b;

    // Stage 1: Add c to the product
    sum <= product + c;

    // Stage 2: Perform XOR reduction on the result
    stage2 <= sum ^ sum;

    // Output the final result
    out <= stage2[16];
end

endmodule

