module IF_stage #(parameter MEM_WIDTH=8, parameter WIDTH, parameter OFF_WIDTH=6)(clk, reset, addr, instr, jump, stall, jumpOffset);
	input clk, reset, jump, stall;
	output [WIDTH-1:0] instr;
	output [MEM_WIDTH-1:0] addr;
	input [OFF_WIDTH-1:0] jumpOffset;

	// Sign extension unit
	assign signExtendedOffset = jumpOffset[OFF_WIDTH-1:0] ? ~jumpOffset[OFF_WIDTH-1:0] : jumpOffset[OFF_WIDTH-1:0];

	// Instruction memory
	reg [MEM_WIDTH-1:0] instructionMemory [0:2**OFF_WIDTH-1];

	// PC register
	reg [WIDTH-1:0] pc;

	// Fetch instruction
	always @(posedge clk or posedge reset) begin
		if (reset) begin
			instr <= 0;
			addr <= 0;
			pc <= 0;
		end else begin
			if (stall) begin
				instr <= 0;
				addr <= 0;
				pc <= pc;
			end else begin
				addr <= pc;
				instr <= instructionMemory[pc];
				pc <= pc + 1;
			end
		end
	end

	// Update PC on jump
	always @(posedge clk or posedge reset) begin
		if (reset) begin
			pc <= 0;
		end else begin
			if (jump) begin
				pc <= pc + signExtendedOffset;
			end
		end
	end

endmodule

