module SynFifo #
(
    parameter DATA_WIDTH = 8,
    parameter FIFO_DEPTH = 256
)
(clk,arstn,data_in,wrreq,rdreq,data_out,usedw,empty,full);

input clk;
input arstn;
input [DATA_WIDTH-1:0]data_in;
input wrreq;
input rdreq;
output [DATA_WIDTH-1:0]data_out;
output reg [clog2_FIFO_DEPTH:0]usedw;
output empty;
output full;

reg [clog2_FIFO_DEPTH-1:0]write_ptr;
reg [clog2_FIFO_DEPTH-1:0]read_ptr;
reg [clog2_FIFO_DEPTH-1:0]used;
reg [clog2_FIFO_DEPTH-1:0]empty_reg;
reg [clog2_FIFO_DEPTH-1:0]full_reg;

always @(posedge clk or negedge arstn) begin
    if (arstn) begin
        write_ptr <= 0;
        read_ptr <= 0;
        used <= 0;
        empty_reg <= 1;
        full_reg <= 0;
    end else begin
        if (wrreq && !full) begin
            write_ptr <= (write_ptr + 1) % FIFO_DEPTH;
            data_out <= data_in;
            used <= used + 1;
            if (used == FIFO_DEPTH) begin
                full_reg <= 1;
            end
        end
        if (rdreq && !empty) begin
            read_ptr <= (read_ptr + 1) % FIFO_DEPTH;
            data_out <= data_in;
            used <= used - 1;
            if (used == 0) begin
                empty_reg <= 1;
            end
        end
    end
end

assign usedw = used;
assign empty = empty_reg;
assign full = full_reg;
endmodule

