module mulor_3_stage_signed_10_bit(
	input signed [9:0] a,
	input signed [9:0] b,
	input signed [9:0] c,
	output [9:0] out,
	input clk);

reg [19:0] stage0, stage1, stage2;
reg [19:0] result;

always @(posedge clk) begin
    // Stage 0: Multiply a and b
    stage0 <= a * b;

    // Stage 1: Perform bitwise OR with c
    stage1 <= stage0 | c;

    // Stage 2: Output the result
    stage2 <= stage1;

    // Assign the result to the output after three clock cycles
    if (clk == 1'b1) begin
        out <= stage2;
    end
end

endmodule

