    reg [2:0] B;
    wire A_greater;
    wire A_equal;
    wire A_less;

    // Instantiate the comparator module
    comparator_3bit comparator (
        .A(A),
        .B(B),
        .A_greater(A_greater),
        .A_equal(A_equal),
        .A_less(A_less)
    );

    // Define the test cases
    initial begin
