        $display("Starting testbench...");
        $display("Test cases: 100");

        // Iterate through 100 test cases
        for (i = 0; i < 100; i++) begin
            // Generate random 3-bit input values for A and B
            A = $random;
            B = $random;

            // Apply the input values to the comparator
            #1;

            // Check the comparison results
            if (A > B) begin
                if (!A_greater) begin
                    $display("Test case %0d failed: A > B but A_greater is not set", i);
                    error = error + 1;
                end
            end else if (A < B) begin
                if (!A_less) begin
                    $display("Test case %0d failed: A < B but A_less is not set", i);
                    error = error + 1;
                end
            end else if (A == B) begin
                if (!A_equal) begin
                    $display("Test case %0d failed: A == B but A_equal is not set", i);
                    error = error + 1;
                end
            end else begin
                $display("Test case %0d failed: Unexpected comparison result", i);
                error = error + 1;
            end
        end

        // Provide a summary of the test results
        if (error == 0) begin
            $display("Test passed!");
        end else begin
            $display("Test failed with %0d errors", error);
        end
    end
