module full_adder(
	A,
	B,
	Cin,
	S,
	C
);

input wire	A;
input wire	B;
input wire	Cin;
output wire	S;
output wire	C;

wire intermediate_sum;
wire intermediate_carry;
wire secondary_carry;

// Half adder
half_adder HA1(
	.A(A),
	.B(B),
	.S(intermediate_sum),
	.C(intermediate_carry)
);

// Full adder with carry-in
full_adder FA1(
	.A(intermediate_sum),
	.B(Cin),
	.S(S),
	.C(secondary_carry)
);

// Additional logic to combine intermediate carry and Cin
always @(posedge clk or negedge rst) begin
	if (!rst) begin
		intermediate_carry <= 0;
		secondary_carry <= 0;
	end else begin
		intermediate_carry <= intermediate_carry | Cin;
		secondary_carry <= secondary_carry | intermediate_sum;
	end
end

endmodule

module ps2_host_to_kb (
    input wire clk,          
    inout wire ps2clk_ext,
    inout wire ps2data_ext,
    input wire [7:0] data,
    input wire dataload,
    output wire ps2busy,
    output wire ps2error
    );

    // PS2 clock and data signals
    wire ps2clk;
    wire ps2data;

    // PS2 state machine
    reg [2:0] state;
    reg [7:0] data_reg;
    reg [7:0] data_out;
    reg [7:0] parity_reg;
    reg [7:0] parity_out;
    reg [7:0] error_reg;
    reg [7:0] error_out;
    reg [7:0] timeout_reg;
    reg [7:0] timeout_out;
    reg [7:0] busy_reg;
    reg [7:0] busy_out;
    reg [7:0] error_flag;
    reg [7:0] error_flag_out;

    // Clock and data synchronization
    always @(posedge clk or negedge ps2clk_ext) begin
        if (ps2clk_ext == 1'b0) begin
            ps2clk <= 1'b0;
            ps2data <= 1'b0;
        end else begin
            ps2clk <= ps2clk_ext;
            ps2data <= ps2data_ext;
        end
    end

    // PS2 state machine logic
    always @(posedge ps2clk) begin
        case (state)
            3'b000: begin
                if (dataload) begin
                    data_reg <= data;
                    state <= 3'b001;
                end
            end
            3'b001: begin
                if (ps2data == 1'b1) begin
                    data_out <= data_reg;
                    state <= 3'b010;
                end else begin
                    state <= 3'b000;
                end
            end
            3'b010: begin
                if (ps2data == 1'b1) begin
                    parity_reg <= parity_reg ^ data_reg[0];
                    state <= 3'b011;
                end else begin
                    state <= 3'b000;
                end
            end
            3'b011: begin
                if (ps2data == 1'b1) begin
                    parity_out <= parity_reg;
                    state <= 3'b100;
                end else begin
                    state <= 3'b000;
                end
            end
            3'b100: begin
                if (ps2data == 1'b1) begin
                    error_reg <= error_reg ^ data_reg[0];
                    state <= 3'b101;
                end else begin
                    state <= 3'b000;
                end
            end
            3'b101: begin
                if (ps2data == 1'b1) begin
                    error_out <= error_reg;
                    state <= 3'b110;
                end else begin
                    state <= 3'b000;
                end
            end
            3'b110: begin
                if (ps2data == 1'b1) begin
                    timeout_reg <= timeout_reg ^ data_reg[0];
                    state <= 3'b111;
                end else begin
                    state <= 3'b000;
                end
            end
            3'b111: begin
                if (ps2data == 1'b1) begin
                    busy_reg <= busy_reg ^ data_reg[0];
                    state <= 3'b000;
                end else begin
                    state <= 3'b000;
                end
            end
        endcase
    end

    // Generate busy and error signals
    always @(posedge ps2clk) begin
        if (state == 3'b000) begin
            busy_reg <= 1'b0;
            error_flag <= 1'b0;
        end else begin
            busy_reg <= 1'b1;
            error_flag <= 1'b1;
        end
    end

    // Output signals
    assign ps2clk_ext = ps2clk;
    assign ps2data_ext = data_out;
    assign ps2busy = busy_reg;
    assign ps2error = error_flag;

endmodule

