module adder_word(
    input wire [31:0] a,
    input wire [31:0] b,
    input wire carry_in,
    output wire [31:0] sum,
    output wire carry_out
);

    // Internal wires for byte adders and carry propagation
    wire [7:0] byte_adder_out[0:3];
    wire [1:0] byte_carry_out[0:3];

    // First byte adder
    byte_adder byte_adder_0(
        .a(a[7:0]),
        .b(b[7:0]),
        .carry_in(carry_in),
        .sum(byte_adder_out[0]),
        .carry_out(byte_carry_out[0])
    );

    // Second byte adder
    byte_adder byte_adder_1(
        .a(a[15:8]),
        .b(b[15:8]),
        .carry_in(byte_carry_out[0]),
        .sum(byte_adder_out[1]),
        .carry_out(byte_carry_out[1])
    );

    // Third byte adder
    byte_adder byte_adder_2(
        .a(a[23:16]),
        .b(b[23:16]),
        .carry_in(byte_carry_out[1]),
        .sum(byte_adder_out[2]),
        .carry_out(byte_carry_out[2])
    );

    // Fourth byte adder
    byte_adder byte_adder_3(
        .a(a[31:24]),
        .b(b[31:24]),
        .carry_in(byte_carry_out[2]),
        .sum(byte_adder_out[3]),
        .carry_out(byte_carry_out[3])
    );

    // Sum construction
    assign sum = byte_adder_out[0] + byte_adder_out[1] + byte_adder_out[2] + byte_adder_out[3];

    // Carry propagation
    assign carry_out = byte_carry_out[3];

endmodule

