module fsm_trafic_light(clk,reset, red,yellow, green);
input clk, reset;

output red,yellow,green;

reg [2:0] state;
reg [2:0] next_state;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= 3'b000;
        next_state <= 3'b000;
    end else begin
        next_state <= state;
        case (state)
            3'b000: begin
                next_state <= 3'b001; // Red
            end
            3'b001: begin
                next_state <= 3'b010; // Yellow
            end
            3'b010: begin
                next_state <= 3'b011; // Green
            end
            3'b011: begin
                next_state <= 3'b000; // Red (loop back)
            end
        endcase
    end
end

assign red = (state == 3'b000) ? 1'b1 : 1'b0;
assign yellow = (state == 3'b010) ? 1'b1 : 1'b0;
assign green = (state == 3'b011) ? 1'b1 : 1'b0;
endmodule

