module sky130_fd_sc_hs__sdfbbp_1 (
    output reg Q,
    output reg Q_N,
    input  wire D,
    input  wire SCD,
    input  wire SCE,
    input  wire CLK,
    input  wire SET_B,
    input  wire RESET_B
);

// Internal flip-flop logic
reg [1:0] state;
always @(posedge CLK or posedge RESET_B) begin
    if (RESET_B) begin
        state <= 2'b00;
    end else begin
        case (state)
            2'b00: begin
                if (SET_B) begin
                    state <= 2'b01;
                end else if (SCD) begin
                    state <= 2'b01;
                end else if (SCE) begin
                    state <= 2'b01;
                end else begin
                    state <= 2'b00;
                end
            end
            2'b01: begin
                if (SCD) begin
                    state <= 2'b01;
                end else if (SCE) begin
                    state <= 2'b01;
                end else if (SET_B) begin
                    state <= 2'b01;
                end else begin
                    state <= 2'b00;
                end
            end
            2'b10: begin
                if (SCE) begin
                    state <= 2'b10;
                end else if (SET_B) begin
                    state <= 2'b10;
                end else if (SCD) begin
                    state <= 2'b10;
                end else begin
                    state <= 2'b00;
                end
            end
            2'b11: begin
                if (SCE) begin
                    state <= 2'b11;
                end else if (SET_B) begin
                    state <= 2'b11;
                end else if (SCD) begin
                    state <= 2'b11;
                end else begin
                    state <= 2'b00;
                end
            end
        endcase
    end
end

// Output logic
always @(posedge CLK or posedge RESET_B) begin
    if (RESET_B) begin
        Q <= 1'b0;
        Q_N <= 1'b1;
    end else begin
        case (state)
            2'b00: begin
                Q <= D;
                Q_N <= ~D;
            end
            2'b01: begin
                Q <= D;
                Q_N <= ~D;
            end
            2'b10: begin
                Q <= D;
                Q_N <= ~D;
            end
            2'b11: begin
                Q <= D;
                Q_N <= ~D;
            end
        endcase
    end
end

endmodule

