module shift(output reg [9:0]remout,
				output reg [8:0]resout,
				input [9:0]remin,
				input [8:0]resin,
				input resone,
				input clk);
	// Temporary register to hold the shifted data
	reg [18:0] shitmp;

	// Process to shift the data
	always @(posedge clk) begin
		// Concatenate the inputs
		shitmp <= resone << 19 | resin << 10 | remin;
		// Shift the data left by one bit
		shitmp <= shitmp << 1;
		// Assign the lower 9 bits to resout
		resout <= shitmp[8:0];
		// Assign the upper 10 bits to remout, discarding the most significant bit
		remout <= shitmp[18:9];
	end
endmodule

