module addmulsub_3_stage_unsigned_14_bit_xor_reduction(
	input  [13:0] a,
	input  [13:0] b,
	input  [13:0] c,
	input  [13:0] d,
	output [13:0] out,
	input clk);

reg [13:0] stage0, stage1, stage2;
reg [27:0] result;

always @(posedge clk) begin
    // Stage 0: Add a and b
    stage0 = a + b;

    // Stage 1: Multiply stage0 by c
    stage1 = stage0 * c;

    // Stage 2: Subtract stage1 from d
    stage2 = d - stage1;

    // Stage 3: Apply XOR reduction to stage2
    result = stage2[27:0];

    // Output the result
    out <= result[13:0];
end

endmodule

