module RC_16_16_12_approx_fa_51_15(IN1, IN2, Out);
input [15:0] IN1;
input [15:0] IN2;
output [16:0] Out;

// 12 approximate full adders for lower bits
reg [11:0] lower_sum;
reg [11:0] lower_carry;
reg [11:0] lower_out;

// 4 standard full adders for higher bits
reg [10:0] higher_sum;
reg [10:0] higher_carry;
reg [10:0] higher_out;

// 17-bit output
reg [16:0] output;
reg overflow;

// 12 approximate full adders for lower bits
always @(posedge clk or negedge rst) begin
    if (rst) begin
        lower_sum <= 12'b0;
        lower_carry <= 12'b0;
        lower_out <= 12'b0;
    end else begin
        lower_sum <= IN1[15:4] + IN2[15:4] + lower_carry;
        lower_carry <= lower_sum[11];
        lower_out <= lower_sum[10:0];
    end
end

// 4 standard full adders for higher bits
always @(posedge clk or negedge rst) begin
    if (rst) begin
        higher_sum <= 4'b0;
        higher_carry <= 4'b0;
        higher_out <= 4'b0;
    end else begin
        higher_sum <= IN1[3:0] + IN2[3:0] + higher_carry;
        higher_carry <= higher_sum[2];
        higher_out <= higher_sum[1:0];
    end
end

// Combine lower and higher bits
always @(posedge clk or negedge rst) begin
    if (rst) begin
        output <= 17'b0;
        overflow <= 1'b0;
    end else begin
        output <= lower_out[11:0] + higher_out[10:0];
        overflow <= lower_carry[11] | higher_carry[10];
    end
end

endmodule

