    wire [24:0] MA_shifted;
    wire [24:0] MB_shifted;
    assign MA_shifted = EA_LT_EB ? {2'b00, M_A[22:0], shifted_MA[22:0]} : {2'b00, M_B[22:0], shifted_MB[22:0]};
    assign MB_shifted = EA_LT_EB ? {2'b00, M_B[22:0], shifted_MB[22:0]} : {2'b00, M_A[22:0], shifted_MA[22:0]};
endmodule

module sum22bit(a,b,kIn,sum);
	input [21:0] a;
	input [21:0] b;
	input [1:0] kIn;
	output [22:0]sum;

	// Generate carry signals for each bit position
	generate
		for (genvar i = 0; i < 22; i = i + 1) begin
			assign carry[i] = (i < 21) ? (a[i] ^ b[i] ^ carry[i-1]) : (a[i] ^ b[i]);
		end
	endgenerate

	// Compute the sum for each bit position
	generate
		for (genvar i = 0; i < 22; i = i + 1) begin
			assign sum[i] = (i < 21) ? (a[i] ^ b[i] ^ carry[i]) : (a[i] ^ b[i]);
		end
	endgenerate

	// Compute the carry-out
	assign sum[22] = carry[21];

endmodule

