module uart(
    input clk,
    input rst_n,
    input [7:0] data_in,
    input start,
    output reg [7:0] data_out,
    output reg done
);

    // State machine states
    typedef enum {IDLE, START_BIT, DATA_BITS, PARITY_BIT, STOP_BIT} state_t;
    state_t state = IDLE;

    // Shift register for data bits
    reg [7:0] shift_reg;
    reg [3:0] bit_counter;

    // Parity bit calculation
    reg parity_bit;

    // Output signals
    reg [7:0] data_out_reg;
    reg done_reg;

    // Clock edge detection
    reg clk_edge;

    // Reset signal detection
    reg rst_edge;

    // State machine logic
    always @(posedge clk or posedge rst_n) begin
        if (rst_n) begin
            state <= IDLE;
            shift_reg <= 8'b0;
            bit_counter <= 4'b0;
            parity_bit <= 1'b0;
            data_out_reg <= 8'b0;
            done_reg <= 1'b0;
            clk_edge <= 0;
            rst_edge <= 0;
        end else begin
            clk_edge <= (clk_edge == 0) ? 1'b1 : 1'b0;
            rst_edge <= (rst_n == 0) ? 1'b1 : 1'b0;

            if (clk_edge) begin
                // Handle reset edge
                if (rst_edge) begin
                    state <= IDLE;
                    shift_reg <= 8'b0;
                    bit_counter <= 4'b0;
                    parity_bit <= 1'b0;
                    data_out_reg <= 8'b0;
                    done_reg <= 1'b0;
                end else begin
                    // Handle clock edge
                    case (state)
                        IDLE: begin
                            if (start) begin
                                state <= START_BIT;
                                bit_counter <= 4'b0;
                                parity_bit <= 1'b0;
                                data_out_reg <= 8'b0;
                                done_reg <= 1'b0;
                            end
                        end
                        START_BIT: begin
                            shift_reg <= data_in;
                            state <= DATA_BITS;
                            bit_counter <= 4'b0;
                            parity_bit <= 1'b0;
                            data_out_reg <= 8'b0;
                            done_reg <= 1'b0;
                        end
                        DATA_BITS: begin
                            if (bit_counter < 7) begin
                                shift_reg[7:bit_counter] <= data_in[7-bit_counter];
                                bit_counter <= bit_counter + 1;
                            end else begin
                                shift_reg[7:bit_counter] <= data_in[7-bit_counter];
                                bit_counter <= 4'b0;
                                parity_bit <= ~shift_reg[0] ^ shift_reg[1] ^ shift_reg[2] ^ shift_reg[3] ^ shift_reg[4] ^ shift_reg[5] ^ shift_reg[6];
                                state <= PARITY_BIT;
                            end
                        end
                        PARITY_BIT: begin
                            if (bit_counter < 1) begin
                                data_out_reg <= shift_reg;
                                state <= STOP_BIT;
                                bit_counter <= 4'b0;
                                done_reg <= 1'b1;
                            end else begin
                                bit_counter <= bit_counter + 1;
                            end
                        end
                        STOP_BIT: begin
                            state <= IDLE;
                            bit_counter <= 4'b0;
                            parity_bit <= 1'b0;
                            data_out_reg <= 8'b0;
                            done_reg <= 1'b0;
                        end
                    endcase
                end
            end
        end
    end

    // Output signals
    assign data_out = data_out_reg;
    assign done = done_reg;

endmodule

