module addr_decode #(
  parameter int unsigned NoIndices = 32'd0, 
  parameter int unsigned NoRules   = 32'd0, 
  parameter type         addr_t    = logic, 
  parameter type         rule_t    = logic, 

  parameter int unsigned IdxWidth  = (NoIndices > 32'd1) ? $clog2(NoIndices) : 32'd1,
  parameter type         idx_t     = logic [IdxWidth-1:0]
) (
  input  addr_t               addr_i,           
  input  rule_t [NoRules-1:0] addr_map_i,       
  output idx_t                idx_o,            
  output logic                dec_valid_o,      
  output logic                dec_error_o,      

  input  logic                en_default_idx_i, 
  input  idx_t                default_idx_i     
) (
  // Local variables
  logic [IdxWidth-1:0] idx;
  logic [NoRules-1:0] matched_rules;
  logic [NoRules-1:0] valid_rules;
  logic [NoRules-1:0] error_rules;

  // Initialize local variables
  idx = default_idx_i;
  matched_rules = 0;
  valid_rules = 0;
  error_rules = 0;

  // Check for overlaps in address ranges
  for (int i = 0; i < NoRules; i++) begin
    if (addr_map_i[i].start > addr_map_i[i].end) begin
      $error("Overlap in address range for rule %0d", i);
    end
  end

  // Check if the address map is valid
  for (int i = 0; i < NoRules; i++) begin
    if (addr_map_i[i].start >= addr_map_i[i].end) begin
      $error("Invalid address range for rule %0d", i);
    end
  end

  // Check if only one rule matches the address
  for (int i = 0; i < NoRules; i++) begin
    if (addr_i >= addr_map_i[i].start && addr_i <= addr_map_i[i].end) begin
      matched_rules = i;
      valid_rules = valid_rules | 1'b1;
      if (en_default_idx_i) begin
        idx = default_idx_i;
      end
      break;
    end
  end

  // Check for no valid rules
  if (valid_rules == 0) begin
    dec_error_o = 1'b1;
  end

  // Update the index based on the matched rules
  if (matched_rules != 0) begin
    idx = addr_map_i[matched_rules].index;
    dec_valid_o = 1'b1;
  end

  // Output the results
  idx_o = idx;
  dec_valid_o = dec_valid_o;
  dec_error_o = dec_error_o;
endmodule

