module apb_master(
                  addr,
                  data_valid,
                  data,
                  data_dir,
             read_out_data,
             transaction_done,


                  apb_clk,
                  apb_reset,
                  apb_write,
                  apb_selx,
                  apb_en,
                  apb_wdata,
                  apb_rdata,
                  apb_ready,
                  apb_addr,
  				  apb_tranerr
                 );

  // State variables
  reg [1:0] state;
  reg [15:0] timeout_count;
  reg [15:0] read_count;
  reg [15:0] write_count;
  reg [15:0] read_data;
  reg [15:0] write_data;
  reg [15:0] read_out_data;
  reg transaction_done;

  // Register for state
  reg [1:0] state_reg;

  // Register for timeout count
  reg [15:0] timeout_count_reg;

  // Register for read count
  reg [15:0] read_count_reg;

  // Register for write count
  reg [15:0] write_count_reg;

  // Register for read data
  reg [15:0] read_data_reg;

  // Register for write data
  reg [15:0] write_data_reg;

  // Register for read out data
  reg [31:0] read_out_data_reg;

  // Register for transaction done
  reg transaction_done_reg;

  // Initialize state and timeout count
  initial begin
    state_reg <= IDLE;
    timeout_count_reg <= 16'b0;
    read_count_reg <= 16'b0;
    write_count_reg <= 16'b0;
    read_data_reg <= 16'b0;
    write_data_reg <= 16'b0;
    read_out_data_reg <= 32'b0;
    transaction_done_reg <= 1'b0;
  end

  // State machine
  always @(posedge apb_clk or posedge apb_reset) begin
    if (apb_reset) begin
      state_reg <= IDLE;
      timeout_count_reg <= 16'b0;
      read_count_reg <= 16'b0;
      write_count_reg <= 16'b0;
      read_data_reg <= 16'b0;
      write_data_reg <= 16'b0;
      read_out_data_reg <= 32'b0;
      transaction_done_reg <= 1'b0;
    end else begin
      state_reg <= state;
      timeout_count_reg <= timeout_count;
      read_count_reg <= read_count;
      write_count_reg <= write_count;
      read_data_reg <= read_data;
      write_data_reg <= write_data;
      read_out_data_reg <= read_out_data;
      transaction_done_reg <= transaction_done;

      case (state_reg)
        IDLE: begin
          if (data_valid) begin
            state_reg <= SETUP;
            timeout_count_reg <= 16'b0;
            read_count_reg <= 16'b0;
            write_count_reg <= 16'b0;
            read_data_reg <= 16'b0;
            write_data_reg <= 16'b0;
            read_out_data_reg <= 32'b0;
            transaction_done_reg <= 1'b0;
          end
        end
        SETUP: begin
          if (data_valid) begin
            state_reg <= ACCESS;
            timeout_count_reg <= 16'b0;
            read_count_reg <= 16'b0;
            write_count_reg <= 16'b0;
            read_data_reg <= 16'b0;
            write_data_reg <= 16'b0;
            read_out_data_reg <= 32'b0;
            transaction_done_reg <= 1'b0;
          end
        end
        ACCESS: begin
          if (apb_ready) begin
            if (data_valid) begin
              read_count_reg <= read_count + 1;
              write_count_reg <= write_count + 1;
              read_data_reg <= data;
              write_data_reg <= data;
              read_out_data_reg <= 32'b0;
              transaction_done_reg <= 1'b0;
            end else begin
              read_count_reg <= read_count + 1;
              write_count_reg <= write_count + 1;
              read_data_reg <= 32'b0;
              write_data_reg <= 32'b0;
              read_out_data_reg <= 32'b0;
              transaction_done_reg <= 1'b0;
            end
          end else begin
            timeout_count_reg <= timeout_count + 1;
            if (timeout_count_reg >= 16'b1000) begin
              read_count_reg <= read_count + 1;
              write_count_reg <= write_count + 1;
              read_data_reg <= 32'b0;
              write_data_reg <= 32'b0;
              read_out_data_reg <= 32'b0;
              transaction_done_reg <= 1'b1;
            end
          end
        end
      endcase
    end
  end

  // Output handling
  assign read_out_data = read_out_data_reg;
  assign transaction_done = transaction_done_reg;

endmodule

