module FIFO_arp_server_arpTableInsertFifo_V_shiftReg (
    clk,
    data,
    ce,
    a,
    q);

input clk;
input [80:0] data; // 81 bits data input
input ce;
input [2:0] a; // 3 bits address input
output [80:0] q; // 81 bits output

reg [80:0] SRL_SIG [0:4]; // 5 entries, each 81 bits wide
reg [2:0] current_index; // Current index in the FIFO

always @(posedge clk or posedge ce) begin
    if (ce) begin
        // Shift all data one position down
        for (int i = 4; i > 0; i = i - 1) begin
            SRL_SIG[i] <= SRL_SIG[i - 1];
        end
        // Insert new data at the beginning
        SRL_SIG[0] <= data;
        // Update the current index
        current_index <= current_index + 1;
    end
end

assign q = SRL_SIG[current_index];

endmodule

