        if_write_ce <= 0;
        if_read <= 0;
        if_write <= 0;
    end else begin
        if (if_read_ce) begin
            if (if_read) begin
                if (write_pointer != read_pointer) begin
                    if_dout <= data_memory[read_pointer];
                    read_pointer <= read_pointer + 1;
                    if_empty_n <= 0;
                end else begin
                    if_empty_n <= 1;
                end
            end else begin
                if_empty_n <= 0;
            end
        end
        if (if_write_ce) begin
            if (if_write) begin
                if (write_pointer != read_pointer) begin
                    data_memory[write_pointer] <= if_din;
                    write_pointer <= write_pointer + 1;
                    if_full_n <= 0;
                end else begin
                    if_full_n <= 1;
                end
            end else begin
                if_full_n <= 0;
            end
        end
    end
end

