// Define ALU module
module ALU (
    input [31:0] A,
    input [31:0] B,
    input [4:0] FS, 
    output wire Out
);

    // Internal signals
    reg [31:0] Result;
    reg [4:0] Operation;

    // Assign operation based on FS
    assign Operation = FS[4:0];

    // Perform arithmetic/logic operation
    case (Operation)
        5'b00000: Out = A + B; // Addition
        5'b00001: Out = A - B; // Subtraction
        5'b00010: Out = A * B; // Multiplication
        5'b00011: Out = A / B; // Division
        5'b00100: Out = A & B; // AND
        5'b00101: Out = A | B; // OR
        5'b00110: Out = A ^ B; // XOR
        5'b00111: Out = A << B; // Left Shift
        5'b01000: Out = A >> B; // Right Shift
        default: Out = 32'b0; // Invalid operation
    endcase

    // Assign result to Out
    assign Out = Result;

endmodule

// Define BarrelShifter32 module
module BarrelShifter32 (
    input [31:0] A,
    input [4:0] SH,
    input [4:0] ShiftSignal,
    output wire Out
);

    // Internal signals
    reg [31:0] Result;
    reg [4:0] ShiftAmount;

    // Assign shift amount based on SH
    assign ShiftAmount = SH[4:0];

    // Perform shift operation
    case (ShiftAmount)
        5'b00000: Out = A; // No shift
        5'b00001: Out = {A[31], A[30:0]}; // Left Shift by 1
        5'b00010: Out = {A[30], A[29:0]}; // Left Shift by 2
        5'b00011: Out = {A[29], A[28:0]}; // Left Shift by 3
        5'b00100: Out = {A[28], A[27:0]}; // Left Shift by 4
        5'b00101: Out = {A[27], A[26:0]}; // Left Shift by 5
        5'b00110: Out = {A[26], A[25:0]}; // Left Shift by 6
        5'b00111: Out = {A[25], A[24:0]}; // Left Shift by 7
        5'b01000: Out = {A[24], A[23:0]}; // Left Shift by 8
        5'b01001: Out = {A[23], A[22:0]}; // Left Shift by 9
        5'b01010: Out = {A[22], A[21:0]}; // Left Shift by 10
        5'b01011: Out = {A[21], A[20:0]}; // Left Shift by 11
        5'b01100: Out = {A[20], A[19:0]}; // Left Shift by 12
        5'b01101: Out = {A[19], A[18:0]}; // Left Shift by 13
        5'b01110: Out = {A[18], A[17:0]}; // Left Shift by 14
        5'b01111: Out = {A[17], A[16:0]}; // Left Shift by 15
        default: Out = 32'b0; // Invalid shift amount
    endcase

    // Assign result to Out
    assign Out = Result;

endmodule

// Define StatusFlags module
module StatusFlags (
    input [31:0] In,
    output wire statC,
    output wire statN,
    output wire statV,
    output wire statZ
);

    // Internal signals
    reg [31:0] Result;
    reg [31:0] Carry;
    reg [31:0] Negative;
    reg [31:0] Overflow;
    reg [31:0] Zero;

    // Perform status flag computation
    assign Carry = In[31];
    assign Negative = In[31] & ~In[30];
    assign Overflow = In[31] & In[30];
    assign Zero = In[31] == 0;

    // Assign status flags to output
    assign statC = Carry;
    assign statN = Negative;
    assign statV = Overflow;
    assign statZ = Zero;

endmodule

// Define Mux module
module Mux (
    input [31:0] A,
    input [31:0] B,
    input [4:0] Select,
    output wire Out
);

    // Internal signals
    reg [31:0] Result;

    // Perform multiplexer operation
    case (Select)
        5'b00000: Out = A; // Select A
        5'b00001: Out = B; // Select B
        default: Out = 32'b0; // Invalid select
    endcase

    // Assign result to Out
    assign Out = Result;

endmodule

