module cyclonev_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );

input  clk;
input  shiftnld;
input  captnupdt;

reg [1:0] mainclk_tmp;
reg [1:0] updateclk_tmp;
reg [1:0] capture_tmp;
reg [1:0] update_tmp;

always @(posedge clk or posedge captnupdt or posedge shiftnld) begin
    case (captnupdt, shiftnld)
        2'b00: begin
            mainclk_tmp <= 2'b00;
            updateclk_tmp <= 2'b00;
            capture_tmp <= 2'b00;
            update_tmp <= 2'b00;
        end
        2'b01: begin
            mainclk_tmp <= 2'b01;
            updateclk_tmp <= 2'b00;
            capture_tmp <= 2'b00;
            update_tmp <= 2'b00;
        end
        2'b10: begin
            mainclk_tmp <= 2'b00;
            updateclk_tmp <= 2'b01;
            capture_tmp <= 2'b00;
            update_tmp <= 2'b00;
        end
        2'b11: begin
            mainclk_tmp <= 2'b00;
            updateclk_tmp <= 2'b00;
            capture_tmp <= 2'b01;
            update_tmp <= 2'b00;
        end
        default: begin
            mainclk_tmp <= 2'b00;
            updateclk_tmp <= 2'b00;
            capture_tmp <= 2'b00;
            update_tmp <= 2'b00;
        end
    endcase

    mainclk <= mainclk_tmp;
    updateclk <= updateclk_tmp;
    capture <= capture_tmp;
    update <= update_tmp;
end

endmodule

