module CLA2 (
	input[1:0] a,b,
	input c_in,
	output g_out,p_out,
	output[1:0] s
	);

	// Instantiate ADD submodules for each bit
	assign s[0] = ADD0.s[0];
	assign s[1] = ADD1.s[1];

