	ADD ADD0 (
		.a(a[0]),
		.b(b[0]),
		.c_in(c_in),
		.s(s[0]),
		.c(c[0])
	);

	ADD ADD1 (
		.a(a[1]),
		.b(b[1]),
		.c_in(c_in),
		.s(s[1]),
		.c(c[1])
	);

endmodule

// Define the ADD submodule
module ADD (
	input a,b,c_in,
	output s,c
	);

	// Instantiate two 1-bit adders for each bit
	assign s[0] = a[0] ^ b[0] ^ c_in;
	assign c[0] = a[0] & b[0] | a[0] & c_in | b[0] & c_in;

	// Instantiate two 1-bit carry lookaheads for each bit
	assign s[1] = a[1] ^ b[1] ^ c_in;
	assign c[1] = a[1] & b[1] | a[1] & c_in | b[1] & c_in;

endmodule

// Define the G_P submodule
module G_P (
	input [1:0] s,
	input c_in,
	output g_out,p_out
	);

	// Compute final carry and propagate outputs
	g_out = s[1] | c_in;
	p_out = s[0];

endmodule

