        if (CE) begin
            // Shift the shift register
            shift_reg = {shift_reg[2:0], CDI};

            // Update the lookup table based on the shift register
            lut = shift_reg;

            // Generate the cascaded output bit
            cascaded_output = shift_reg[3];

            // Generate the output bits
            output_bits = lut;
        end
    end

