module tb_file_to_dvp
#(
	parameter FILE     = "in.bin",
	parameter BITS     = 8, 
	parameter H_FRONT  = 50,
	parameter H_PULSE  = 100,
	parameter H_BACK   = 50,
	parameter H_DISP   = 1280,
	parameter V_FRONT  = 10,
	parameter V_PULSE  = 20,
	parameter V_BACK   = 10,
	parameter V_DISP   = 960,
	parameter H_POL    = 0,
	parameter V_POL    = 1
)
(
	input             xclk,
	input             rst_n,
	output            pclk,
	output reg        href,
	output reg        hsync,
	output reg        vsync,
	output [BITS-1:0] data
);

reg [31:0] raw_data;
reg [31:0] pix_cnt;
reg [31:0] line_cnt;
reg [31:0] data_cnt;
reg [31:0] hsync_cnt;
reg [31:0] vsync_cnt;
reg [31:0] hdisp_cnt;
reg [31:0] vdisp_cnt;
reg [31:0] hfront;
reg [31:0] hpulse;
reg [31:0] hback;
reg [31:0] hdisp;
reg [31:0] vfront;
reg [31:0] vpulse;
reg [31:0] vback;
reg [31:0] vdisp;
reg [31:0] hpol;
reg [31:0] vpol;

always @(posedge xclk or negedge rst_n) begin
	if (rst_n == 1'b0) begin
		raw_data <= 32'h0;
		pix_cnt <= 32'h0;
		line_cnt <= 32'h0;
		data_cnt <= 32'h0;
		hsync_cnt <= 32'h0;
		vsync_cnt <= 32'h0;
		hdisp_cnt <= 32'h0;
		vdisp_cnt <= 32'h0;
		hfront <= H_FRONT;
		hpulse <= H_PULSE;
		hback <= H_BACK;
		hdisp <= H_DISP;
		vfront <= V_FRONT;
		vpulse <= V_PULSE;
		vback <= V_BACK;
		vdisp <= V_DISP;
		hpol <= H_POL;
		vpol <= V_POL;
	end else begin
		if (pix_cnt < hdisp) begin
			pix_cnt <= pix_cnt + 1'b1;
		end else begin
			pix_cnt <= 32'h0;
			line_cnt <= line_cnt + 1'b1;
		end
		if (line_cnt < vdisp) begin
			line_cnt <= line_cnt + 1'b1;
		end else begin
			line_cnt <= 32'h0;
			data_cnt <= data_cnt + 1'b1;
		end
		if (data_cnt < raw_data.size()) begin
			data <= raw_data[data_cnt];
		end else begin
			data <= 32'h0;
		end
		if (pix_cnt == hfront) begin
			hsync_cnt <= hfront;
		end else begin
			hsync_cnt <= hsync_cnt + 1'b1;
		end
		if (hsync_cnt == hfront + hpulse) begin
			hsync_cnt <= 32'h0;
			hsync <= 1'b1;
		end else begin
			hsync <= 1'b0;
		end
		if (hsync_cnt == hfront + hpulse + hback) begin
			hsync_cnt <= 32'h0;
			hsync <= 1'b0;
		end
		if (line_cnt == vfront) begin
			vsync_cnt <= vfront;
		end else begin
			vsync_cnt <= vsync_cnt + 1'b1;
		end
		if (vsync_cnt == vfront + vpulse) begin
			vsync_cnt <= 32'h0;
			vsync <= 1'b1;
		end else begin
			vsync <= 1'b0;
		end
		if (vsync_cnt == vfront + vpulse + vback) begin
			vsync_cnt <= 32'h0;
			vsync <= 1'b0;
		end
		if (pix_cnt == hdisp - 1) begin
			hdisp_cnt <= hdisp - 1;
		end else begin
			hdisp_cnt <= 32'h0;
		end
		if (line_cnt == vdisp - 1) begin
			vdisp_cnt <= vdisp - 1;
		end else begin
			vdisp_cnt <= 32'h0;
		end
		if (data_cnt == raw_data.size() - 1) begin
			data_cnt <= 32'h0;
		end else begin
			data_cnt <= data_cnt + 1'b1;
		end
	end
end

initial begin
	$readmemh(FILE, raw_data);
end

endmodule

module sky130_fd_sc_lp__a32o (
