module RC_8_8_5_approx_fa_170_0(IN1, IN2, Out);
input [7:0] IN1;
input [7:0] IN2;
output [8:0] Out;

reg [7:0] sum;
reg [7:0] carry;

// Approximate full adder for the first five bits
always @(IN1[4:0] or IN2[4:0] or carry) begin
    sum[4:0] = IN1[4:0] + IN2[4:0] + carry;
    carry = sum[5];
end

// Standard full adder for the last three bits
always @(IN1[3:0] or IN2[3:0] or carry) begin
    sum[7:4] = IN1[3:0] + IN2[3:0] + carry;
    carry = sum[8];
end

// Final carry propagation
always @(sum[8]) begin
    Out[8] = carry;
end

// Sum of the first five bits and the last three bits
always @(sum[4:0] or sum[7:4]) begin
    Out[0:4] = sum[4:0] + sum[7:4];
end

endmodule

