module uart_tx_tester (
    input clk_50M,
    input run_test_raw,
    input tx_busy,
    output reg [7:0] data_out,
    output reg trigger
);

// Define states
parameter IDLE = 0;
parameter LOAD_DATA = 1;
parameter TRANSMIT = 2;
parameter POLL_BUSY = 3;
parameter PAUSE = 4;

// Internal registers
reg [2:0] state;
reg [7:0] data_position;
reg [15:0] delay_counter;
reg [15:0] pause_counter;

// State machine logic
always @(posedge clk_50M or posedge run_test_raw) begin
    if (run_test_raw) begin
        state <= IDLE;
        data_position <= 8'b0;
        delay_counter <= 16'b0;
        pause_counter <= 16'b0;
    end else begin
        case (state)
            IDLE: begin
                if (tx_busy) begin
                    state <= LOAD_DATA;
                end
            end
            LOAD_DATA: begin
                data_out <= data_position;
                state <= TRANSMIT;
            end
            TRANSMIT: begin
                if (tx_busy) begin
                    state <= POLL_BUSY;
                end
            end
            POLL_BUSY: begin
                if (!tx_busy) begin
                    state <= PAUSE;
                end
            end
            PAUSE: begin
                if (pause_counter == 0) begin
                    state <= LOAD_DATA;
                    pause_counter <= MSG_DELAY;
                end else begin
                    pause_counter <= pause_counter - 1;
                end
            end
        endcase
    end
end

// Data loading logic
always @(posedge clk_50M) begin
    if (state == LOAD_DATA) begin
        data_position <= data_position + 1;
        if (data_position == 8'b11111111) begin
            data_position <= 8'b0;
        end
    end
end

// Delay logic
always @(posedge clk_50M) begin
    if (state == TRANSMIT) begin
        delay_counter <= delay_counter + 1;
        if (delay_counter == MSG_DELAY) begin
            delay_counter <= 0;
            trigger <= 1'b1;
        end
    end
end

// Pause logic
always @(posedge clk_50M) begin
    if (state == PAUSE) begin
        pause_counter <= pause_counter + 1;
        if (pause_counter == MSG_DELAY) begin
            pause_counter <= 0;
            trigger <= 1'b0;
        end
    end
end

endmodule

