module maxFinder #(parameter numInput=10,parameter inputWidth=16)(
input           i_clk,
input [(numInput*inputWidth)-1:0]   i_data,
input           i_valid,
output reg [31:0]o_data,
output  reg     o_data_valid
) (
    // Register to store the current maximum value
    reg [inputWidth-1:0] maxValue;

    // Buffer to hold all input values
    reg [(numInput*inputWidth)-1:0] inDataBuffer;

    // Counter to track the number of inputs processed
    reg [3:0] counter;

    // Control signal to start the search
    reg startSearch;

    // Control signal to indicate the completion of the search
    reg searchComplete;

    // Control signal to reset the module
    reg reset;

    // Control signal to clear the valid output
    reg clearValid;

    // Control signal to start the search
    always @(posedge i_clk or posedge reset) begin
        if (reset) begin
            maxValue <= 0;
            inDataBuffer <= 0;
            counter <= 0;
            startSearch <= 0;
            searchComplete <= 0;
            clearValid <= 0;
        end else begin
            if (i_valid) begin
                // Start the search if i_valid is high
                if (startSearch == 0) begin
                    startSearch <= 1;
                    maxValue <= i_data;
                    inDataBuffer <= i_data;
                    counter <= 1;
                end else begin
                    // Process the next input
                    inDataBuffer[counter*inputWidth:(counter+1)*inputWidth] <= i_data;
                    counter <= counter + 1;
                    if (counter == numInput) begin
                        // Check if the current input is the maximum
                        if (i_data > maxValue) begin
                            maxValue <= i_data;
                            o_data <= counter;
                        end
                        searchComplete <= 1;
                    end
                end
            end else begin
                // Clear the valid output if i_valid is low
                if (clearValid == 1) begin
                    o_data_valid <= 0;
                    clearValid <= 0;
                end
            end
        end
    end

    // Output the index of the maximum value and a flag signaling the completion of the search
    always @(posedge i_clk or posedge reset) begin
        if (reset) begin
            o_data <= 0;
            o_data_valid <= 0;
        end else begin
            if (searchComplete) begin
                o_data <= counter;
                o_data_valid <= 1;
            end
        end
    end
endmodule

