module carry_ripple_adder(
input wire [3:0] a,
input wire [3:0] b,
input wire ci,
output wire [3:0] s,
output wire co
);
    wire [3:0] carry;
    wire [3:0] sum;

    // Instantiate four full adder stages
    full_adder fa1(a[0], b[0], ci, sum[0], carry[0]);
    full_adder fa2(a[1], b[1], carry[0], sum[1], carry[1]);
    full_adder fa3(a[2], b[2], carry[1], sum[2], carry[2]);
    full_adder fa4(a[3], b[3], carry[2], sum[3], co);

    // Assign the final sum and carry-out
    assign s = sum;
    assign co = co;
endmodule

module full_adder(
input wire a,
input wire b,
input wire cin,
output wire sum,
output wire cout
);
    wire s1, s2, s3, s4;
    wire c1, c2, c3, c4;

    // First stage
    and_gate and1(a, b, s1);
    and_gate and2(a, cin, c1);
    or_gate or1(s1, c1, s2);

    // Second stage
    and_gate and3(b, cin, s3);
    and_gate and4(b, s2, c2);
    or_gate or2(s3, c2, s4);

    // Third stage
    and_gate and5(a, cin, s5);
    and_gate and6(a, s4, c3);
    or_gate or3(s5, c3, s6);

    // Fourth stage
    and_gate and7(b, cin, s7);
    and_gate and8(b, s6, c4);
    or_gate or4(s7, c4, sum);

    // Carry-out
    or_gate or5(c1, c2, c3, c4, cout);
endmodule

module and_gate(
input wire a,
input wire b,
output wire out
