	always @(posedge clk or posedge rst) begin
		// Initialize the output to zero
		out <= 11'b0;
		// Perform the addition of a and d
		signed [10:0] sum = a + d;
		// Perform the multiplication of sum and b
		signed [10:0] product = sum * b;
		// Perform the bitwise OR operation with c
		out <= product | c;
	end
