module gtx_tx_reset_controller(
input wire clk,
input wire ref_clk,
input wire powerup_channel,
output reg tx_running,
output reg txreset,
output reg txuserrdy,
output reg txpmareset,
output reg txpcsreset,
output reg pllpd,
output reg pllreset,
output reg plllocken,
input wire plllock,
output reg resetsel,
input wire txresetdone
);

// State machine states
parameter IDLE = 0,
         RESET = 1,
         PLL_LOCK = 2,
         PLL_RESET = 3,
         TX_RESET = 4,
         TX_USERRDY = 5,
         TX_PMARESET = 6,
         TX_PCSRESET = 7;

// State variable
reg [2:0] state;

// Counter for reference clock detection
reg [15:0] ref_clk_counter;

// PLL lock and reset signals
reg plllock;
reg pllreset;
reg plllocken;
reg resetsel;

// PLL settings
reg pllpd;
reg txresetdone;

// TX reset signals
reg txreset;
reg txuserrdy;
reg txpmareset;
reg txpcsreset;

// TX running signal
reg tx_running;

// Meta registers for synchronization
reg [15:0] meta_counter;
reg [15:0] meta_counter_reset;

// State machine logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= IDLE;
        ref_clk_counter <= 0;
        plllock <= 0;
        pllreset <= 0;
        plllocken <= 0;
        resetsel <= 0;
        pllpd <= 0;
        txresetdone <= 0;
        txreset <= 0;
        txuserrdy <= 0;
        txpmareset <= 0;
        txpcsreset <= 0;
        tx_running <= 0;
        meta_counter <= 0;
        meta_counter_reset <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (powerup_channel) begin
                    state <= RESET;
                    meta_counter_reset <= 0;
                end
            end
            RESET: begin
                if (meta_counter_reset == 0) begin
                    state <= PLL_LOCK;
                    meta_counter_reset <= 1;
                end
            end
            PLL_LOCK: begin
                if (plllock) begin
                    state <= PLL_RESET;
                    meta_counter_reset <= 0;
                end
            end
            PLL_RESET: begin
                if (meta_counter_reset == 0) begin
                    state <= TX_RESET;
                    meta_counter_reset <= 1;
                end
            end
            TX_RESET: begin
                if (meta_counter_reset == 0) begin
                    state <= TX_USERRDY;
                    meta_counter_reset <= 1;
                end
            end
            TX_USERRDY: begin
                if (meta_counter_reset == 0) begin
                    state <= TX_PMARESET;
                    meta_counter_reset <= 1;
                end
            end
            TX_PMARESET: begin
                if (meta_counter_reset == 0) begin
                    state <= TX_PCSRESET;
                    meta_counter_reset <= 1;
                end
            end
            TX_PCSRESET: begin
                if (meta_counter_reset == 0) begin
                    state <= PLL_LOCKEN;
                    meta_counter_reset <= 1;
                end
            end
            PLL_LOCKEN: begin
                if (plllock) begin
                    state <= TX_RUNNING;
                    meta_counter_reset <= 0;
                end
            end
            TX_RUNNING: begin
                if (txresetdone) begin
                    state <= IDLE;
                    meta_counter_reset <= 0;
                end
            end
        endcase
    end
end

// PLL lock and reset control logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        plllock <= 0;
        pllreset <= 0;
        plllocken <= 0;
        resetsel <= 0;
    end else begin
        if (state == PLL_LOCK) begin
            plllock <= 1;
        end else if (state == PLL_RESET) begin
            pllreset <= 1;
        end else if (state == PLL_LOCKEN) begin
            plllocken <= 1;
        end
    end
end

// TX reset control logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        txreset <= 0;
        txuserrdy <= 0;
        txpmareset <= 0;
        txpcsreset <= 0;
    end else begin
        if (state == TX_RESET) begin
            txreset <= 1;
        end else if (state == TX_USERRDY) begin
            txuserrdy <= 1;
        end else if (state == TX_PMARESET) begin
            txpmareset <= 1;
        end else if (state == TX_PCSRESET) begin
            txpcsreset <= 1;
        end
    end
end

// TX running control logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        tx_running <= 0;
    end else begin
        if (state == TX_RUNNING) begin
            tx_running <= 1;
        end
    end
end

// Meta counter logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        meta_counter <= 0;
        meta_counter_reset <= 0;
    end else begin
        if (meta_counter_reset == 1) begin
            meta_counter <= 0;
            meta_counter_reset <= 0;
        end else begin
            meta_counter <= meta_counter + 1;
        end
    end
end

endmodule

