module RC_30_30(IN1, IN2, Out);
input [29:0] IN1;
input [29:0] IN2;
output [30:0] Out;

// Lower 24 bits using approx_fa_17_4 modules
wire [23:0] lower_sum;
wire [23:0] lower_carry;
approx_fa_17_4 lower_adder1(IN1[23:0], IN2[23:0], lower_sum, lower_carry);
approx_fa_17_4 lower_adder2(lower_sum, IN1[22:0], IN2[22:0], lower_sum, lower_carry);
// ... (repeat for lower bits up to 24)

// Upper 6 bits using FullAdder modules
wire [5:0] upper_sum;
wire [5:0] upper_carry;
FullAdder upper_adder1(lower_sum[23:18], lower_sum[17:12], lower_sum[11:6], lower_carry, upper_sum[5:0], upper_carry);
FullAdder upper_adder2(upper_sum[5:0], IN1[11:6], IN2[11:6], upper_sum[5:0], upper_carry, upper_sum[5:0]);
// ... (repeat for upper bits up to 6)

// Final carry from the 29th bit addition
wire final_carry;
FullAdder final_adder(upper_sum[5:0], IN1[5:0], IN2[5:0], final_carry, Out[30], final_carry);

// Output the final 31-bit result
assign Out = {lower_sum[23:0], upper_sum[5:0], final_carry};

endmodule

