module addr_decode #(

  parameter int unsigned NoIndices = 32'd0,

  parameter int unsigned NoRules   = 32'd0,

  parameter type         addr_t    = logic,












  parameter type         rule_t    = logic,



  parameter int unsigned IdxWidth  = cf_math_pkg::idx_width(NoIndices),



  parameter type         idx_t     = logic [IdxWidth-1:0]
) (

  input  addr_t               addr_i,

  input  rule_t [NoRules-1:0] addr_map_i,

  output idx_t                idx_o,

  output logic                dec_valid_o,

  output logic                dec_error_o,



  input  logic                en_default_idx_i,





  input  idx_t                default_idx_i
) (

  // Internal signals
  logic [NoRules-1:0] matched_rules;
  logic [NoRules-1:0] matched_indices;
  logic [NoRules-1:0] matched_start;
  logic [NoRules-1:0] matched_end;

  // Registers for output signals
  reg [IdxWidth-1:0] reg_idx_o;
  reg [NoRules-1:0] reg_dec_valid_o;
  reg [NoRules-1:0] reg_dec_error_o;

  // Loop to iterate through each rule
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      matched_rules <= 0;
      matched_indices <= 0;
      matched_start <= 0;
      matched_end <= 0;
      reg_idx_o <= 0;
      reg_dec_valid_o <= 0;
      reg_dec_error_o <= 0;
    end else begin
      // Check if the default index is enabled
      if (en_default_idx_i) begin
        reg_idx_o <= default_idx_i;
        reg_dec_valid_o <= 1;
        reg_dec_error_o <= 0;
      end else begin
        // Iterate through each rule
        for (int i = 0; i < NoRules; i++) begin
          // Check if the rule has been matched
          if (matched_rules[i]) begin
            // Check if the current address matches the rule's start and end addresses
            if (addr_i >= matched_start[i] && addr_i <= matched_end[i]) begin
              // Output the corresponding index
              reg_idx_o <= matched_indices[i];
              reg_dec_valid_o <= 1;
              reg_dec_error_o <= 0;
