module sonar(
input clk, rst_n, 
input do_measure,
input sonar_pulse,
output reg [7:0] inches,
output reg sonar_trigger = 0,
output reg READY = 0
);

reg [3:0] state;
reg [15:0] timeCount;
reg [15:0] timeoutCounter;
reg [15:0] pulseCount;
reg [15:0] distance;
reg [15:0] timeoutFlag;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= 4'b0000;
        timeCount <= 16'b0;
        timeoutCounter <= 16'b0;
        pulseCount <= 16'b0;
        distance <= 16'b0;
        timeoutFlag <= 1'b0;
    end else begin
        case (state)
            4'b0000: begin
                if (do_measure) begin
                    state <= 4'b0001;
                    sonar_trigger <= 1'b1;
                end
            end
            4'b0001: begin
                if (sonar_pulse) begin
                    state <= 4'b0010;
                    pulseCount <= 16'b0;
                end
            end
            4'b0010: begin
                timeCount <= timeCount + 1'b1;
                if (sonar_pulse) begin
                    pulseCount <= pulseCount + 1'b1;
                end
                if (pulseCount == 16'b10000) begin
                    state <= 4'b0011;
                    timeoutCounter <= 16'b0;
                end
            end
            4'b0011: begin
                timeoutCounter <= timeoutCounter + 1'b1;
                if (timeoutCounter == 16'b10000) begin
                    timeoutFlag <= 1'b1;
                    state <= 4'b0000;
                end
            end
            4'b0100: begin
                distance = timeCount / 58.0;
                inches <= distance[7:0];
                READY <= 1'b1;
                state <= 4'b0000;
            end
        endcase
    end
end

endmodule

