module voting (a0, a1, a2, a3, a4, out);

input    [2:0]   a0, a1, a2, a3, a4;
output reg [2:0]   out;

reg [2:0]   sum0, sum1, sum2;
reg [2:0]   error;
reg [2:0]   temp_sum;
reg [2:0]   temp_error;

always @(posedge clk or negedge rst) begin
    if (rst) begin
        sum0 <= 3'b0;
        sum1 <= 3'b0;
        sum2 <= 3'b0;
        error <= 3'b0;
        temp_sum <= 3'b0;
        temp_error <= 3'b0;
    end else begin
        // Calculate sum0
        temp_sum <= a0[0] + a1[0] + a2[0] + a3[0] + a4[0];
        sum0 <= temp_sum[0] + temp_sum[1] + temp_sum[2];

        // Calculate sum1
        temp_sum <= a0[1] + a1[1] + a2[1] + a3[1] + a4[1];
        sum1 <= temp_sum[0] + temp_sum[1] + temp_sum[2];

        // Calculate sum2
        temp_sum <= a0[2] + a1[2] + a2[2] + a3[2] + a4[2];
        sum2 <= temp_sum[0] + temp_sum[1] + temp_sum[2];

        // Detect errors
        temp_error <= sum0 == sum1 || sum0 == sum2 || sum1 == sum2;

        // Determine output
        if (temp_error) begin
            out <= 3'b0; // Error occurred
        end else begin
            if (sum0 > sum1 && sum0 > sum2) begin
                out <= sum0; // Most votes for sum0
            end else if (sum1 > sum0 && sum1 > sum2) begin
                out <= sum1; // Most votes for sum1
            end else if (sum2 > sum0 && sum2 > sum1) begin
                out <= sum2; // Most votes for sum2
            end else begin
                out <= 3'b0; // Error occurred
            end
        end
    end
end

endmodule

