    if (rst) begin
      state <= 2'b00;
      value <= 64'b0;
      s_input_a_ack <= 1'b0;
    end else begin
      case (state)
        2'b00: begin
          if (input_a_stb) begin
            value <= input_a;
            state <= 2'b01;
          end
        end
        2'b01: begin
          if (s_input_a_ack) begin
            $fopena("resp_z", "a");
            $fdisplay("resp_z", "%08x", value[31:0]);
            $fdisplay("resp_z", "%08x", value[63:32]);
            $fclosea("resp_z");
            state <= 2'b00;
          end
        end
        default: begin
          state <= 2'b00;
        end
      endcase
      s_input_a_ack <= input_a_ack;
    end
  end

