            mux_z <= 2'b0;
            shift_left <= 2'b0;
            shift_right <= 2'b0;
        end else begin
            reg_a <= a;
            reg_b <= b;
            reg_c <= c;

            sum_ab <= reg_a + reg_b;
            sum_ac <= reg_a + reg_c;
            diff_ab <= reg_a - reg_b;

            comp_ab <= (sum_ab > reg_c) ? 2'b1 : 2'b0;
            comp_ac <= (sum_ac > reg_b) ? 2'b1 : 2'b0;

            mux_ab <= comp_ab;
            mux_ac <= comp_ac;

            mux_x <= mux_ab;
            mux_z <= mux_ac;

            shift_left <= comp_ab;
            shift_right <= comp_ac;

            reg_x <= mux_x << shift_left;
            reg_z <= mux_z >> shift_right;
        end
    end
endmodule

