module HWORD (
    input CLK,
    input WE,
    input SELW,
    input SELR,
    input [15:0] Di,
    output [15:0] Do
) 
begin
    // Internal flip-flops for data storage
    reg [15:0] data_reg;

    // Gated clock generation
    reg gated_clk;
    always @(posedge CLK or posedge WE or posedge SELW) begin
        if (WE && SELW) begin
            gated_clk <= 1'b1;
        end else begin
            gated_clk <= 1'b0;
        end
    end

    // Sequential logic for data storage
    always @(posedge gated_clk) begin
        if (WE && SELW) begin
            data_reg <= Di;
        end
    end

    // Output logic
    assign Do = (SELR) ? data_reg : 16'b11111111;
endmodule

module FPAddSub_reduced(
		clk,
		rst,
		a,
		b,
		operation,
		result,
		flags
	);

	input clk ;										
	input rst ;										

	input [31:0] a ;								
	input [31:0] b ;								
	input operation ;								

	output [31:0] result ;						
	output [4:0] flags ;

	reg [31:0] pipe_1, pipe_2, pipe_3 ;	
	reg [4:0] flags_reg ;					

	always @(posedge clk or posedge rst) begin
		if (rst) begin
			pipe_1 <= 32'h00000000;
			pipe_2 <= 32'h00000000;
			pipe_3 <= 32'h00000000;
			flags_reg <= 5'b00000;
		end else begin
			pipe_1 <= a;
			pipe_2 <= b;
			pipe_3 <= pipe_1 + pipe_2;

			if (operation == 1'b1) begin
				// Addition
				if (pipe_3[31] == 1'b1) begin
					// Overflow
					flags_reg <= 5'b10000;
				end else if (pipe_3[31] == 1'b0) begin
					// Underflow
					flags_reg <= 5'b01000;
				end else begin
					// Normal operation
					flags_reg <= 5'b00000;
				end
			end else begin
				// Subtraction
				if (pipe_3[31] == 1'b1) begin
					// Underflow
					flags_reg <= 5'b01000;
				end else if (pipe_3[31] == 1'b0) begin
					// Overflow
					flags_reg <= 5'b10000;
				end else begin
					// Normal operation
					flags_reg <= 5'b00000;
				end
			end
		end
	end

	assign result = pipe_3;
	assign flags = flags_reg;
endmodule

