module add_pu11_mu11_o11
  (
  i0,
  i1,
  o
  );

  input [10:0] i0;
  input [10:0] i1;
  output [10:0] o;

  wire [10:0] i1_inv;
  wire [10:0] i1_inv_plus_one;
  wire [10:0] carry;
  wire [10:0] sum;

  // Invert i1 and add 1
  assign i1_inv = ~i1;
  assign i1_inv_plus_one = i1_inv + 1;

  // Full adder module instantiation
  AL_FADD #(
    .WIDTH(11)
  ) full_adder (
    .A(i0),
    .B(i1_inv_plus_one),
    .C(carry),
    .S(sum),
    .CO(carry)
  );

  // Output assignment
  assign o = sum;

endmodule

module wideexpr_00479(ctrl, u0, u1, u2, u3, u4, u5, u6, u7, s0, s1, s2, s3, s4, s5, s6, s7, y);
