  wire [1:0] neg_ctrl;
  wire [1:0] compare_ctrl;

  // Shift operations
  assign shift_ctrl = {ctrl[0], ctrl[1]};
  assign y0 = u0 << shift_ctrl[0];
  assign y1 = u1 << shift_ctrl[1];
  assign y2 = u2 << shift_ctrl[0];
  assign y3 = u3 << shift_ctrl[1];
  assign y4 = u4 << shift_ctrl[0];
  assign y5 = u5 << shift_ctrl[1];
  assign y6 = u6 << shift_ctrl[0];
  assign y7 = u7 << shift_ctrl[1];

  // Negation operations
  assign neg_ctrl = {ctrl[2], ctrl[3]};
