  assign y1 = ~y1;
  assign y2 = ~y2;
  assign y3 = ~y3;
  assign y4 = ~y4;
  assign y5 = ~y5;
  assign y6 = ~y6;
  assign y7 = ~y7;

  // Comparison operations
  assign compare_ctrl = {ctrl[4], ctrl[5]};
