module full_adder (i_a, i_b, i_carry, o_sum, o_carry);
 input [1:0] i_a;
 input [1:0] i_b;
 input i_carry;
 output [1:0] o_sum;
 output o_carry;
 wire [1:0] sum;
 wire [1:0] carry;

// Lower bit calculation
sum[0] = i_a[0] ^ i_b[0] ^ i_carry;
carry[0] = (i_a[0] & i_b[0]) | (i_a[0] & i_carry) | (i_b[0] & i_carry);

// Higher bit calculation
sum[1] = sum[0][0] ^ i_b[1] ^ i_carry;
carry[1] = (sum[0][0] & i_b[1]) | (sum[0][0] & i_carry) | (i_b[1] & i_carry);

// Output assignment
o_sum = sum;
o_carry = carry[1];
endmodule

