	input signed [13:0] b,
	input signed [13:0] c,
	input signed [13:0] d,
	output [13:0] out,
	input clk);

reg [27:0] intermediate_result;
reg [13:0] final_result;

always @(posedge clk) begin
    // Perform addition of a and b
