module add_saturate(
input wire [15:0] a_i,
input wire [15:0] b_i,
output wire [15:0] s_o
) begin
    // Sign-extend inputs to 17 bits
    wire [16:0] a_ext = {16'b0, a_i};
    wire [16:0] b_ext = {16'b0, b_i};

    // Perform addition
    wire [16:0] ext_sum = a_ext + b_ext;

    // Apply saturation
    wire [15:0] s_o = (ext_sum < -32768) ? 16'b1111_1111 : (ext_sum > 32767) ? 16'b0000_0000 : ext_sum[15:0];

endmodule

