      data_o <= data_mem[read_ptr];
      read_ptr <= read_ptr + 1;
      if (read_ptr == 619) begin
        read_ptr <= 0;
      end
      data_valid <= 0;
      data_ready <= 1;
    end else begin
      data_valid <= 0;
      data_ready <= 0;
