module lfsr (
out             ,  
enable          ,  
clk             ,  
reset              
);

output [7:0] out;

input enable, clk, reset;

reg [7:0] state;
reg [1:0] feedback;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= 8'b00000000;
        feedback <= 2'b00;
    end else begin
        state <= state << 1;
        feedback <= (state[6] ^ state[2]);
        state[7] <= feedback;
    end
end

assign out = state;
endmodule

