module submuladd_2_stage_unsigned_8_bit(
	input  [7:0] a,
	input  [7:0] b,
	input  [7:0] c,
	input  [7:0] d,
	output [7:0] out,
	input clk);

reg [15:0] stage0;
reg [15:0] stage1;
reg [7:0] result;

always @(posedge clk) begin
    if (clk) begin
        // Stage 0: Multiply a and b, add c, and store in stage0
        stage0 = (a * b) + c;

        // Stage 1: Add stage0 and d, and store in stage1
        stage1 = stage0 + d;

        // Output the result after two clock cycles
        out <= stage1;
    end
end

endmodule

module vga_sync_pulse
(
    input   i_clk,
    output  o_hsync,
    output  o_vsync,
    output reg [9:0] o_col_count = 0,
    output reg [9:0] o_row_count = 0
)
begin
    // Parameters for the VGA display
    parameter TOTAL_COLUMNS = 1920,
            TOTAL_ROWS = 1080;

    // Internal signals for column and row counters
    reg [9:0] col_count;
    reg [9:0] row_count;

    // Internal signal for hsync and vsync
    reg hsync;
    reg vsync;

    // Internal signal for the active display area
    reg active_display;

    // Initial state of the counters and synchronization signals
    always @(posedge i_clk)
    begin
        if (col_count == TOTAL_COLUMNS - 1)
        begin
            col_count <= 0;
            active_display <= 0;
        end
        else
        begin
            col_count <= col_count + 1;
            active_display <= 1;
        end

        if (row_count == TOTAL_ROWS - 1)
        begin
            row_count <= 0;
            hsync <= 0;
            vsync <= 0;
        end
        else
        begin
            row_count <= row_count + 1;
            hsync <= 1;
            vsync <= 1;
        end
    end

    // Output signals
    assign o_col_count = col_count;
    assign o_row_count = row_count;
    assign o_hsync = hsync;
    assign o_vsync = vsync;
endmodule

