module FIFO(
    input clock,
    input sclr,
    input rdreq, wrreq,
    output reg full, empty,
    input [7 : 0] data,
    output [7 : 0] q
) begin
    reg [15:0] mem [0:15];
    reg [7:0] wp, rp;
    reg w_flag, r_flag;

    always @(posedge clock or posedge sclr) begin
        if (sclr) begin
            wp <= 0;
            rp <= 0;
            w_flag <= 0;
            r_flag <= 0;
        end else begin
            if (wrreq) begin
                if (wp == 15) begin
                    wp <= 0;
                end else begin
                    wp <= wp + 1;
                end
                mem[wp] <= data;
                w_flag <= 1;
            end
            if (rdreq) begin
                if (rp == 15) begin
                    rp <= 0;
                end else begin
                    rp <= rp + 1;
                end
                q <= mem[rp];
                r_flag <= 1;
            end
        end
    end

    always @(posedge clock) begin
        if (w_flag) begin
            w_flag <= 0;
        end
        if (r_flag) begin
            r_flag <= 0;
        end
    end

    assign full = (wp == rp);
    assign empty = (wp == rp + 1);
endmodule

