module mul8x3u_0BH (
    input [7:0] A,
    input [2:0] B,
    output [10:0] O
);

// Internal signals for intermediate calculations
wire [10:0] intermediate_product;
wire [10:0] intermediate_sum;
wire [10:0] intermediate_carry;

// First stage of multiplication: A[7:0] * B[2:0]
intermediate_product = A[7:0] * B[2:0];

// Second stage of multiplication: A[6:0] * B[2:0] + intermediate_product
intermediate_sum = A[6:0] * B[2:0] + intermediate_product;

// Third stage of multiplication: A[5:0] * B[2:0] + intermediate_sum
intermediate_product = A[5:0] * B[2:0] + intermediate_sum;

// Fourth stage of multiplication: A[4:0] * B[2:0] + intermediate_product
intermediate_sum = A[4:0] * B[2:0] + intermediate_product;

// Fifth stage of multiplication: A[3:0] * B[2:0] + intermediate_sum
intermediate_product = A[3:0] * B[2:0] + intermediate_sum;

// Sixth stage of multiplication: A[2:0] * B[2:0] + intermediate_product
intermediate_sum = A[2:0] * B[2:0] + intermediate_product;

// Seventh stage of multiplication: A[1:0] * B[2:0] + intermediate_sum
intermediate_product = A[1:0] * B[2:0] + intermediate_sum;

// Eighth stage of multiplication: A[0:0] * B[2:0] + intermediate_sum
intermediate_sum = A[0:0] * B[2:0] + intermediate_sum;

// Calculate the final product by adding the intermediate sum and the carry from the previous stage
O = intermediate_sum + intermediate_carry;

