module AdderTreePipelined
#(
    parameter DATA_WIDTH=32,
    parameter LENGTH=8,
    parameter OUT_WIDTH=DATA_WIDTH+$clog2(LENGTH),
    parameter DELAT_STAGES=$clog2(LENGTH)
)
(
    input rst,
    input clk,
    input in_advance,
    input signed [LENGTH*DATA_WIDTH-1:0] in_addends,
    output signed [OUT_WIDTH-1:0] out_sum
);

    // Define the recursive function to add the addends
    function signed [OUT_WIDTH-1:0] adder_tree(signed [LENGTH*DATA_WIDTH-1:0] addends);
        if (LENGTH == 1) begin
            if (in_advance) begin
                adder_tree = in_addends;
            end else begin
                adder_tree = in_addends;
            end
        end else begin
            // Split the addends into two halves
            signed [LENGTH*DATA_WIDTH-1:0] left_addends = addends[0:LENGTH-1];
            signed [LENGTH*DATA_WIDTH-1:0] right_addends = addends[LENGTH:2*LENGTH-1];

            // Recursively add the left and right halves
            signed [OUT_WIDTH-1:0] left_sum = adder_tree(left_addends);
            signed [OUT_WIDTH-1:0] right_sum = adder_tree(right_addends);

            // Combine the results
            adder_tree = left_sum + right_sum;
        end
    endfunction

    // Initialize the output sum
    assign out_sum = 0;

    // Call the recursive function to add the addends
    assign out_sum = adder_tree(in_addends);

endmodule

