  parameter NUM_DIGITS = 4;
  parameter DIV_FACTOR = 1000;
  parameter BIT_WIDTH = 16;

  // Internal signals
  reg [3:0] digit_index;
  reg [3:0] digit_value;
  reg [6:0] segment_activations;
  reg [3:0] display_select;

  // Counter
  reg [3:0] counter;
  reg [3:0] counter_reset;

  // Seven-segment decoder
  reg [6:0] seven_segment_decoder [0:9];

  // Digit decoder
  reg [3:0] digit_decoder [0:9];

  // Initialization
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      digit_index <= 0;
      digit_value <= 0;
      segment_activations <= 0;
      display_select <= 0;
      counter <= 0;
      counter_reset <= 1;
    end else begin
      counter_reset <= 0;
      if (counter == DIV_FACTOR) begin
        counter <= 0;
        digit_index <= digit_index + 1;
        if (digit_index == NUM_DIGITS) begin
          digit_index <= 0;
          digit_value <= 0;
          segment_activations <= 0;
          display_select <= 0;
        end else begin
          digit_value <= value[3 * digit_index:3 * digit_index + 3];
          segment_activations <= seven_segment_decoder[digit_value];
          display_select <= digit_decoder[digit_index];
        end
      end else begin
        counter <= counter + 1;
      end
    end
  end

  // Seven-segment decoder
  always @(*) begin
    seven_segment_decoder[0] = 7'b1111110; // 0
    seven_segment_decoder[1] = 7'b0110000; // 1
    seven_segment_decoder[2] = 7'b1101101; // 2
    seven_segment_decoder[3] = 7'b1111001; // 3
    seven_segment_decoder[4] = 7'b0110111; // 4
    seven_segment_decoder[5] = 7'b1011111; // 5
    seven_segment_decoder[6] = 7'b1111111; // 6
    seven_segment_decoder[7] = 7'b0111001; // 7
    seven_segment_decoder[8] = 7'b1111111; // 8
    seven_segment_decoder[9] = 7'b1111011; // 9
  end

  // Digit decoder
  always @(*) begin
    digit_decoder[0] = 4'b0001; // 0
    digit_decoder[1] = 4'b0010; // 1
    digit_decoder[2] = 4'b0100; // 2
    digit_decoder[3] = 4'b0110; // 3
