reg [31:0] max_value = 100000;

always @(posedge zedboard_clk or posedge reset) begin
    if (reset) begin
        timer_value <= 0;
        timerOutput <= 0;
    end else begin
        if (timer_value < max_value) begin
            timer_value <= timer_value + 1;
        end else begin
            timer_value <= 0;
            timerOutput <= 1;
        end
    end
end

endmodule

module NAND3xp33_ASAP7_75t_R (Y, A, B, C);
output Y;
input A, B, C;

// Invert the inputs
wire A_inv, B_inv, C_inv;

// Apply NOT gates
not #1 A_inv = ~A;
not #1 B_inv = ~B;
not #1 C_inv = ~C;

// Perform OR operation on inverted inputs
or #1 Y = A_inv | B_inv | C_inv;

endmodule

