module jk_flop (
    input J, K, clk,
    output reg Q, Qbar
);

always @(posedge clk) begin
    if (J && K) begin
        Q <= ~Q;
    end else if (J) begin
        Q <= 1;
    end else if (K) begin
        Q <= 0;
    end
    Qbar <= ~Q;
end

endmodule

module Walk2R_example (
	input logic vga_clk,
	input logic [9:0] DrawX, DrawY,
	input logic blank,
	output logic [3:0] red, green, blue
);

// ROM address computation
reg [10:0] ROM_address;
always @(posedge vga_clk) begin
	// Scale DrawX and DrawY for ROM address calculation
	ROM_address = (DrawX >> 2) + (DrawY >> 2) * 1024;
end

// Palette lookup
reg [7:0] palette_data;
always @(posedge vga_clk) begin
	// Fetch palette data from ROM
	palette_data = ROM_address[10:2];
end

// Color mapping
always @(posedge vga_clk) begin
	// Determine color based on palette data and blank signal
	if (blank) begin
		red = 4'b0000; // Black
		green = 4'b0000;
		blue = 4'b0000;
	end else begin
		red = palette_data[3:0];
		green = palette_data[7:4];
		blue = palette_data[11:8];
	end
end

endmodule

