module serial2parallel(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);

    // Internal registers
    reg [7:0] shift_register;
    reg [2:0] counter;

    // Internal signals
    reg valid;

    // Clock and reset sensitive processes
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_register <= 8'b0;
            counter <= 3'b0;
            valid <= 1'b0;
        end else begin
            if (din_valid) begin
                shift_register <= {shift_register[6:0], din_serial};
                counter <= counter + 1'b1;
                if (counter == 3'b111) begin
                    dout_parallel <= shift_register;
                    dout_valid <= 1'b1;
                    counter <= 3'b0;
                end
            end else begin
                dout_parallel <= 8'b0;
                dout_valid <= 1'b0;
            end
        end
    end

endmodule

module NV_NVDLA_HLS_shiftrightsatsu (
   data_in
  ,shift_num
  ,data_out
  ,sat_out
  );
input [IN_WIDTH-1:0] data_in;
input [SHIFT_WIDTH-1:0] shift_num;
output [OUT_WIDTH-1:0] data_out;
output sat_out;
parameter IN_WIDTH = 49;
parameter SHIFT_WIDTH = 6;
parameter OUT_WIDTH = 32;

reg [IN_WIDTH-1:0] shifted_data;
reg [OUT_WIDTH-1:0] saturated_data;
reg sat_flag;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        shifted_data <= 0;
        saturated_data <= 0;
        sat_flag <= 0;
    end else begin
        if (shift_num >= 0) begin
            shifted_data <= data_in >> shift_num;
            if (shifted_data >= (1 << OUT_WIDTH)) begin
                saturated_data <= (1 << OUT_WIDTH) - 1;
                sat_flag <= 1;
            end else if (shifted_data < 0) begin
                saturated_data <= 0;
                sat_flag <= 1;
            end else begin
                saturated_data <= shifted_data;
                sat_flag <= 0;
            end
        end else begin
            shifted_data <= data_in << -shift_num;
            if (shifted_data >= (1 << OUT_WIDTH)) begin
                saturated_data <= (1 << OUT_WIDTH) - 1;
                sat_flag <= 1;
            end else if (shifted_data < 0) begin
                saturated_data <= 0;
                sat_flag <= 1;
            end else begin
                saturated_data <= shifted_data;
                sat_flag <= 0;
            end
        end
    end
end

assign data_out = saturated_data;
assign sat_out = sat_flag;

module Decoder3to8Struct(
input wire [2:0] I,
output wire [7:0] O
);

// First 2-to-4 decoder for the lower two bits
wire [1:0] lowerBits;
assign lowerBits = I[1:0];

// Second 2-to-4 decoder for the upper two bits
wire [1:0] upperBits;
assign upperBits = I[3:2];

// First 4-bit output from the first decoder
wire [3:0] lowerOutput;
assign lowerOutput = lowerBits[1] ? 4'b1111 : 4'b0000;

// Second 4-bit output from the second decoder
wire [3:0] upperOutput;
assign upperOutput = upperBits[1] ? 4'b1111 : 4'b0000;

// Final 8-bit output combining the lower and upper outputs
assign O = lowerOutput | upperOutput;

endmodule

