module adder_sub(s, cout, a, b, cin, cnt, clk, rst);
    parameter n = 32; // Assuming a 32-bit input
    reg [n-1:0] ai, bi, ci, si, co;
    reg [n-1:0] sum, carry;
    reg [n-1:0] result;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            ai <= 0;
            bi <= 0;
            ci <= 0;
            si <= 0;
            co <= 0;
            sum <= 0;
