            if (cnt == 0) begin
                ai <= a;
                bi <= b;
                ci <= cin;
                si <= ai + bi + ci;
                co <= si[31];
                sum <= si[31:0];
            end else begin
                ai <= a;
                bi <= b;
                ci <= cin;
                si <= ai - bi - ci;
                co <= si[31];
                sum <= si[31:0];
            end
        end
