module rca_16b(A, B, S, C_out);
    parameter N = 16;
    input [N-1: 0] A, B;
    output [N-1:0] S;
    output         C_out;

    // Full adder module
    full_adder #(.N(N)) fa(A[N-1], B[N-1], S[N-1], C_out[N-1]);

    // Connect the full adders in a chain
    for (genvar i = 0; i < N-1; i++) begin
        assign fa.A[i] = A[i];
        assign fa.B[i] = B[i];
    end

    // Connect the carry from the last full adder to the output carry
    assign S[N-1] = fa.C_out[N-1];
endmodule

// Full adder module
module full_adder #(parameter N = 16) (
    input [N-1: 0] A, B, S, C_out
);
    input [N-1: 0] A, B;
    output [N-1: 0] S;
    output         C_out;

    // Carry propagation logic
    assign C_out[N-1] = A[N-1] | B[N-1] | S[N-1];

    // Sum calculation logic
    for (genvar i = 0; i < N-1; i++) begin
        assign S[i] = A[i] ^ B[i] ^ C_out[i];
    end
endmodule

module delay (
	input clk,
	input reset,
	input [3:0] variable_pulse_index,
	output slow_pulse,
	output fast_pulse,
	output variable_pulse
);

reg [31:0] counter;
reg [31:0] variable_pulse_threshold;
reg [31:0] slow_pulse_threshold;
reg [31:0] fast_pulse_threshold;

always @(posedge clk or posedge reset) begin
	if (reset) begin
		counter <= 0;
		variable_pulse_threshold <= 0;
		slow_pulse_threshold <= 0;
		fast_pulse_threshold <= 0;
	end else begin
		counter <= counter + 1;
		if (counter == variable_pulse_threshold) begin
			variable_pulse <= 1;
		end else if (counter == slow_pulse_threshold) begin
			slow_pulse <= 1;
		end else if (counter == fast_pulse_threshold) begin
			fast_pulse <= 1;
		end else begin
			variable_pulse <= 0;
			slow_pulse <= 0;
			fast_pulse <= 0;
		end
	end
end

assign variable_pulse_threshold = 2000000 * variable_pulse_index / 24000000;
assign slow_pulse_threshold = 18000000;
assign fast_pulse_threshold = 4800000;

endmodule

