    product = a * b;

    // Extract the lower and upper 10 bits of the product
    lower_product = product[9:0];
    upper_product = product[19:10];

    // Sign-extend c to 20 bits
    sign_extended_c = {10{c[9]}};

    // Perform the OR operation on the lower 10 bits of the product and c
    stage0 = lower_product | sign_extended_c;

    // Pass the result through three sequential registers
    stage1 <= stage0;
    stage2 <= stage1;

    // Assign the final output to out
    out <= stage2;
end

endmodule

