module isqrt
(
    input      [31:0] x,
    output reg [15:0] y
)
begin
    // Internal registers to track the current bit being tested, the remaining part of the input, and the result being constructed
    reg [31:0] input_part;
    reg [31:0] remaining_part;
    reg [15:0] result;
    reg [15:0] bit_index;
    reg [15:0] bit_value;
    reg [15:0] bit_shift;
    reg [15:0] bit_subtract;
    reg [15:0] bit_compare;
    reg [15:0] bit_result;

    // Initialize internal registers
    assign input_part = x;
    assign remaining_part = x;
    assign result = 0;
    assign bit_index = 0;
    assign bit_value = 0;
    assign bit_shift = 0;
    assign bit_subtract = 0;
    assign bit_compare = 0;
    assign bit_result = 0;

    // Main logic to compute the square root
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            input_part <= x;
            remaining_part <= x;
            result <= 0;
            bit_index <= 0;
            bit_value <= 0;
            bit_shift <= 0;
            bit_subtract <= 0;
            bit_compare <= 0;
            bit_result <= 0;
        end else begin
            // Check if the current bit is set
            if (input_part[bit_index] == 1) begin
                bit_value = 1;
            end else begin
                bit_value = 0;
            end

            // Shift the remaining part of the input
            bit_shift = bit_index;

            // Subtract the square of the current bit from the remaining part
            bit_subtract = input_part[bit_index] * input_part[bit_index];

            // Compare the result with the square of the current bit
            bit_compare = result + bit_subtract;

            // If the result is less than or equal to the square of the current bit, set the current bit in the result
            if (bit_compare <= bit_subtract) begin
                bit_result = bit_value;
            end else begin
                bit_result = 0;
            end

            // Update the result
            result = result << 1;

            // Move to the next bit
            bit_index = bit_index + 1;
        end
    end

    // Output the lower 16 bits of the result
    assign y = result[15:0];
end

