module mux_8_1_test();
    // Define the input and output signals
    reg [7:0] input_signal;
    wire [7:0] output_signal;

    // Instantiate the 8-to-1 multiplexer module
    mux_8_1 mux_inst (
        .input_signal(input_signal),
        .select_signal(input_signal[2:0]),
        .output_signal(output_signal)
    );

    // Define the testbench logic
    initial begin
        // Initialize the input signal to a fixed value
        input_signal = 8'b10101010;

        // Cycle through all possible select values
        for (int i = 0; i < 8; i++) begin
            // Set the select signal to the current value
            input_signal[2:0] = i;

            // Wait for 10 units of delay
            #10;

            // Check if the output matches the expected input
            if (output_signal != input_signal) begin
                $display("Test failed: Output does not match input for select value %d", i);
                $finish;
            end
        end

        // If all tests pass, display a success message
        $display("All tests passed!");
        $finish;
    end
endmodule

module ram_64x21(CLK, ADR, D, Q, WE);
input CLK, WE;
input [5:0] ADR;
input [20:0] D;
output [20:0] Q;

// Internal signals
reg [20:0] mem[0:63];
reg [5:0] addr;
reg [20:0] data_in;
reg [20:0] data_out;
reg [1:0] write_enable;

// Internal logic
always @(posedge CLK or posedge WE) begin
    if (WE) begin
        data_in <= D;
        write_enable <= ~WE;
    end else begin
        data_in <= data_out;
        write_enable <= 1'b0;
    end

    addr <= ADR;

    if (write_enable) begin
        mem[addr] <= data_in;
    end else begin
        data_out <= mem[addr];
    end
end

assign Q = data_out;
endmodule

