module rx_dcoffset 
  #(parameter WIDTH=16,
    parameter ADDR=8'd0,
    parameter alpha_shift=20)
   (input clk, input rst, 
    input set_stb, input [7:0] set_addr, input [31:0] set_data,
    input [WIDTH-1:0] in, output [WIDTH-1:0] out);

  // Sub-module for rounding
  reg [WIDTH-1:0] round_reg;
  reg [WIDTH-1:0] round_out;
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      round_reg <= 0;
      round_out <= 0;
    end else if (set_stb) begin
      round_reg <= in;
    end
    round_out <= round_reg + 1;
  end

  // Sub-module for addition with clipping
  reg [WIDTH-1:0] add_reg;
  reg [WIDTH-1:0] add_out;
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      add_reg <= 0;
      add_out <= 0;
    end else if (set_stb) begin
      add_reg <= round_out;
    end
    add_out <= add_reg + set_data;
    if (add_out > 2**WIDTH - 1) begin
      add_out <= 2**WIDTH - 1;
    end else if (add_out < -2**WIDTH) begin
      add_out <= -2**WIDTH;
    end
  end

  // Main module logic
  reg [WIDTH-1:0] dc_offset;
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      dc_offset <= 0;
    end else if (set_stb) begin
      dc_offset <= add_out;
    end
    out <= in - dc_offset;
  end

endmodule

