module Mflipflop_38 (out, din, clock, enable_l) ;
output [37:0] out ;
input [37:0]  din ;
input   clock ;
input   enable_l ;

reg [37:0] reg_array [0:37] ; // Array to hold the flip-flops

always @(posedge clock or posedge enable_l) begin
    if (enable_l == 1'b0) begin
        // Disable flip-flops
        reg_array <= 38'b0;
    end else begin
        // Enable flip-flops
        for (int i = 0; i < 38; i = i + 1) begin
            if (i == 0) begin
                reg_array[i] <= din[i];
            end else begin
                reg_array[i] <= reg_array[i-1];
            end
        end
    end
end

assign out = reg_array ;
endmodule

