module UART_rx(
input wire clk,
input wire reset,
input wire rx_data_in,
output reg [7:0] rx_data_out
);

// Parameters
parameter BAUD_RATE = 9600; // Baud rate in bits per second

// Internal signals
reg [15:0] oversample_counter; // Oversampling counter
reg [3:0] state; // Current state of the UART receiver
reg [7:0] received_data; // Received data
reg [1:0] bit_counter; // Bit counter for each byte
reg [1:0] start_bit_detected; // Flag to indicate if the start bit has been detected
reg [1:0] stop_bit_detected; // Flag to indicate if the stop bit has been detected

// Clock division
always @(posedge clk or posedge reset) begin
    if (reset) begin
        oversample_counter <= 0;
        state <= IDLE;
        received_data <= 0;
        bit_counter <= 0;
        start_bit_detected <= 0;
        stop_bit_detected <= 0;
    end else begin
        oversample_counter <= oversample_counter + 1;
        if (oversample_counter == (16 * BAUD_RATE - 1)) begin
            oversample_counter <= 0;
            case (state)
                IDLE: begin
                    if (rx_data_in == 1'b1) begin
                        start_bit_detected <= 1'b1;
                        state <= START;
                    end
                end
                START: begin
                    if (bit_counter == 0) begin
                        received_data <= rx_data_in;
                    end else if (bit_counter == 1) begin
                        received_data = received_data << 1;
                        received_data = received_data | rx_data_in;
                    end
                    bit_counter <= bit_counter + 1;
                    if (bit_counter == 8) begin
                        state <= DATA;
                        bit_counter <= 0;
                    end
                end
                DATA: begin
                    if (bit_counter == 0) begin
                        received_data = rx_data_in;
                    end else if (bit_counter == 1) begin
                        received_data = received_data << 1;
                        received_data = received_data | rx_data_in;
                    end
                    bit_counter <= bit_counter + 1;
                    if (bit_counter == 8) begin
                        state <= STOP;
                        bit_counter <= 0;
                    end
                end
                STOP: begin
                    if (bit_counter == 0) begin
                        received_data = rx_data_in;
                    end else if (bit_counter == 1) begin
                        received_data = received_data << 1;
                        received_data = received_data | rx_data_in;
                    end
                    bit_counter <= bit_counter + 1;
                    if (bit_counter == 8) begin
                        state <= IDLE;
                        bit_counter <= 0;
                        rx_data_out <= received_data;
                        received_data <= 0;
                    end
                end
            endcase
        end
    end
end

// State definitions
parameter IDLE = 4'b0000;
parameter START = 4'b0001;
parameter DATA = 4'b0010;
parameter STOP = 4'b0011;

endmodule

module serial(clk, reset, rxD,sout,signal,counter);
input clk;      
input reset;    
input rxD;   

output reg [n-1:0]sout; 
output reg signal;   
output reg [31:0]counter;

parameter n = 30;
parameter count = 4;

reg [31:0] counter_reg;
reg [2:0] delay_reg;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        counter_reg <= 0;
        delay_reg <= 0;
        sout <= 0;
        signal <= 0;
    end else begin
        if (counter_reg == count) begin
            delay_reg <= delay_reg + 1;
            if (delay_reg == 3) begin
                sout <= rxD;
                signal <= 1;
                counter_reg <= 0;
                delay_reg <= 0;
            end
        end else begin
            counter_reg <= counter_reg + 1;
        end
    end
end
endmodule

