    reg [GROUP_WIDTH-1:0] x;
    reg [GROUP_WIDTH-1:0] y;
    reg carry_in;

    // Outputs
    reg [GROUP_WIDTH-1:0] z;
    reg carry_out;

    // Adder module instantiation
    adder adder (
        .x(x),
        .y(y),
        .carry_in(carry_in),
        .z(z),
        .carry_out(carry_out)
    );

    // Initial block to set up initial conditions
    initial begin
        // Set initial values for inputs
        x = 8'b00000000;
        y = 8'b00000000;
        carry_in = 1'b0;

        // Start the simulation
        $monitor("x = %b, y = %b, carry_in = %b, z = %b, carry_out = %b", x, y, carry_in, z, carry_out);
        $finish;
    end

    // Stimulus generation block
    initial begin
        // Generate random inputs
        x = $random;
        y = $random;
        carry_in = $random;

        // Wait for 8 time units
        #8;

        // Stop the simulation
        $finish;
    end

    // Waveform dumping block
    initial begin
        // Dump waveforms to a VCD file
        $dumpfile("adder_tb.vcd");
        $dumpvars(0, adder);
    end
