module rx_tb;
    // Parameters
    parameter ref_clk_period = 10; // Reference clock period in ns
    parameter baud_period = 100; // Baud period in ns
    parameter ref_clk_cycles_per_baud = 10; // Number of reference clock cycles per baud period
    parameter num_samples = 100; // Number of data samples to be tested

    // Clock generation
    reg clk;
    reg rst;
    always #(ref_clk_period/2) clk = ~clk;

    // Baud clock generation
    reg baud_clk;
    reg baud_rst;
    always @(posedge clk) begin
        if (baud_rst) begin
            baud_clk <= 0;
        end else begin
            baud_clk <= ~baud_clk;
        end
    end

    // UART receiver module
    UART_Rx uart_rx (
        .ser_in(ser_in),
        .rst(rst),
        .baud_clk(baud_clk),
        .par_out(par_out),
        .Rx_valid(Rx_valid),
        .err_par(err_par),
        .err_stop(err_stop)
    );

    // Memory file for sample data
    initial begin
        $readmemh("sample_data.mem", sample_data);
    end

    // Testbench logic
    reg [7:0] ser_in;
    reg [7:0] par_out;
    reg Rx_valid;
    reg err_par;
    reg err_stop;

    initial begin
        rst = 1'b1;
        #1 rst = 1'b0;
        #1000; // Wait for all samples to be sent
        $finish;
    end

    always @(posedge clk) begin
        if (rst) begin
            ser_in <= 8'b0;
            par_out <= 8'b0;
            Rx_valid <= 1'b0;
            err_par <= 1'b0;
            err_stop <= 1'b0;
        end else begin
            if (baud_clk) begin
                if (ser_in == 8'b0) begin
                    ser_in <= sample_data[0];
                    sample_data = {sample_data[1:end-1]};
                end else begin
                    ser_in <= ser_in << 1;
                end
                if (ser_in == 8'b10010010) begin // End of data
                    Rx_valid <= 1'b1;
                    sample_data = {sample_data[1:end-1]};
                end
            end
        end
    end

    // Error detection logic
    always @(posedge clk) begin
        if (baud_clk) begin
            if (ser_in == 8'b0) begin
                if (par_out != 8'b0) begin
                    err_par <= 1'b1;
                end
            end else begin
                if (par_out != ser_in) begin
                    err_stop <= 1'b1;
                end
            end
        end
    end
endmodule

