module arbiter (
    input clock, 
    input reset, 
    input req_0,
    input req_1, 
    output reg gnt_0,
    output reg gnt_1
);

always @(posedge clock or posedge reset) begin
    if (reset) begin
        gnt_0 <= 0;
        gnt_1 <= 0;
    end else begin
        if (req_0 && !gnt_0) begin
            gnt_0 <= 1;
            gnt_1 <= 0;
        end else if (req_1 && !gnt_1) begin
            gnt_0 <= 0;
            gnt_1 <= 1;
        end else begin
            gnt_0 <= 0;
            gnt_1 <= 0;
        end
    end
end

endmodule

module NAND3C(Y,A,B,C);
 input A,B,C;
 output Y;

// Invert A and B
wire A_inv, B_inv;

assign A_inv = ~A;
assign B_inv = ~B;

// AND gate to combine A_inv and B_inv
wire AND_out;

assign AND_out = A_inv & B_inv;

// NAND gate with inverted C
wire NAND_out;

assign NAND_out = ~AND_out & C;

// Output Y is the result of the NAND operation
assign Y = NAND_out;

// Specify block for propagation delays
specify
  delay(10) from A to AND_out;
  delay(10) from B to AND_out;
  delay(10) from AND_out to NAND_out;
endspecify
endmodule

