    input   [PSUM_WIDTH*PE_SIZE-1:0]    psum_row_i,
    output  [DATA_WIDTH*PE_SIZE-1:0]    ofmap_row_o,
    output                              ofmap_valid_o   
);
    // FIFOs for accumulating partial sums
    reg [PSUM_WIDTH-1:0] psum_fifo[WEIGHT_ROW_NUM*WEIGHT_COL_NUM-1:0];
    reg [PSUM_WIDTH-1:0] psum_fifo_read_ptr;
    reg [PSUM_WIDTH-1:0] psum_fifo_write_ptr;
    reg [PSUM_WIDTH-1:0] psum_fifo_valid;

    // Control signals
    reg [PE_SIZE-1:0] psum_en_col_i;
    reg [PSUM_WIDTH*PE_SIZE-1:0] psum_col_i;
    reg [DATA_WIDTH*PE_SIZE-1:0] ofmap_col_o;
    reg ofmap_col_valid;

    // Slicing logic
    reg [SLICING_IDX-1:0] slicing_idx;
    reg slicing_valid;

    // Weight matrix
    reg [WEIGHT_ROW_NUM-1:0] weight_row[WEIGHT_COL_NUM-1:0];
    reg [WEIGHT_COL_NUM-1:0] weight_col[WEIGHT_ROW_NUM-1:0];

    // Output buffer
    reg [DATA_WIDTH*PE_SIZE-1:0] ofmap_buffer[WEIGHT_ROW_NUM*WEIGHT_COL_NUM-1:0];
    reg [WEIGHT_ROW_NUM*WEIGHT_COL_NUM-1:0] ofmap_buffer_read_ptr;
    reg [WEIGHT_ROW_NUM*WEIGHT_COL_NUM-1:0] ofmap_buffer_write_ptr;
    reg [WEIGHT_ROW_NUM*WEIGHT_COL_NUM-1:0] ofmap_buffer_valid;

    // Initialize FIFOs
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            psum_fifo_read_ptr <= 0;
            psum_fifo_write_ptr <= 0;
            psum_fifo_valid <= 0;
        end else begin
            if (psum_en_row_i) begin
                for (int i = 0; i < PE_SIZE; i++) begin
                    if (psum_row_i[i] != 0) begin
                        psum_fifo[psum_fifo_write_ptr] <= psum_row_i[i];
                        psum_fifo_write_ptr <= psum_fifo_write_ptr + 1;
                        if (psum_fifo_write_ptr == WEIGHT_ROW_NUM*WEIGHT_COL_NUM) begin
                            psum_fifo_write_ptr <= 0;
                        end
                    end
                end
            end
            if (psum_en_col_i) begin
                for (int i = 0; i < PE_SIZE; i++) begin
                    if (psum_col_i[i] != 0) begin
                        psum_fifo[psum_fifo_write_ptr] <= psum_col_i[i];
                        psum_fifo_write_ptr <= psum_fifo_write_ptr + 1;
                        if (psum_fifo_write_ptr == WEIGHT_ROW_NUM*WEIGHT_COL_NUM) begin
                            psum_fifo_write_ptr <= 0;
                        end
                    end
                end
            end
            if (psum_fifo_write_ptr != psum_fifo_read_ptr) begin
                psum_fifo_valid <= 1;
            end else begin
                psum_fifo_valid <= 0;
            end
        end
    end

    // Slicing logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            slicing_idx <= 0;
            slicing_valid <= 0;
        end else begin
            if (slicing_valid) begin
                slicing_idx <= slicing_idx + 1;
                if (slicing_idx == SLICING_IDX) begin
                    slicing_valid <= 0;
                end
            end
        end
    end

    // Weight matrix initialization
    initial begin
        for (int i = 0; i < WEIGHT_ROW_NUM; i++) begin
            for (int j = 0; j < WEIGHT_COL_NUM; j++) begin
                weight_row[i][j] <= 0;
                weight_col[i][j] <= 0;
            end
        end
    end

    // Accumulation logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ofmap_buffer_read_ptr <= 0;
            ofmap_buffer_write_ptr <= 0;
            ofmap_buffer_valid <= 0;
        end else begin
            if (psum_fifo_valid) begin
                for (int i = 0; i < PE_SIZE; i++) begin
                    if (psum_fifo[psum_fifo_read_ptr] != 0) begin
                        ofmap_buffer[ofmap_buffer_write_ptr] <= ofmap_buffer[ofmap_buffer_write_ptr] + psum_fifo[psum_fifo_read_ptr];
                        ofmap_buffer_write_ptr <= ofmap_buffer_write_ptr + 1;
                        if (ofmap_buffer_write_ptr == WEIGHT_ROW_NUM*WEIGHT_COL_NUM) begin
                            ofmap_buffer_write_ptr <= 0;
                        end
                    end
                end
            end
            if (ofmap_buffer_write_ptr != ofmap_buffer_read_ptr) begin
                ofmap_buffer_valid <= 1;
            end else begin
                ofmap_buffer_valid <= 0;
            end
        end
    end

    // Output logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ofmap_col_o <= 0;
            ofmap_col_valid <= 0;
        end else begin
            if (ofmap_buffer_valid) begin
                ofmap_col_o <= ofmap_buffer[ofmap_buffer_read_ptr];
                ofmap_col_valid <= 1;
                ofmap_buffer_read_ptr <= ofmap_buffer_read_ptr + 1;
                if (ofmap_buffer_read_ptr == WEIGHT_ROW_NUM*WEIGHT_COL_NUM) begin
                    ofmap_buffer_read_ptr <= 0;
                end
            end else begin
                ofmap_col_o <= 0;
                ofmap_col_valid <= 0;
            end
        end
    end
