		if (resreg == 1'b0) begin
			choout <= choin;
		end else begin
			reg [15:0] chotmp;
			chotmp <= ~choin[15:0];
			chotmp <= chotmp + 1'b1;
			choout <= {choin[15:0], chotmp[15:0]};
		end
	end
