module zmc2_dot(
	input CLK_12M,
	input EVEN,
	input LOAD,
	input H,
	input [31:0] CR,
	output reg [3:0] GAD, GBD,
	output reg DOTA, DOTB
);

reg [3:0] SR;
reg [3:0] GAD_temp, GBD_temp;
reg [3:0] GAD_final, GBD_final;
reg [3:0] DOTA_temp, DOTB_temp;
reg [3:0] DOTA_final, DOTB_final;

always @(posedge CLK_12M) begin
	if (LOAD) begin
		SR <= CR;
		GAD_temp <= SR[0];
		GBD_temp <= SR[1];
		GAD_final <= SR[2];
		GBD_final <= SR[3];
		DOTA_temp <= SR[4];
		DOTB_temp <= SR[5];
		DOTA_final <= SR[6];
		DOTB_final <= SR[7];
	end else begin
		if (H) begin
			if (EVEN) begin
				GAD_final <= GAD_temp;
				GBD_final <= GBD_temp;
				DOTA_final <= DOTA_temp;
				DOTB_final <= DOTB_temp;
			end else begin
				GAD_final <= GAD_temp << 1;
				GBD_final <= GBD_temp << 1;
				DOTA_final <= DOTA_temp << 1;
				DOTB_final <= DOTB_temp << 1;
			end
		end else begin
			GAD_final <= GAD_temp;
			GBD_final <= GBD_temp;
			DOTA_final <= DOTA_temp;
			DOTB_final <= DOTB_temp;
		end
	end
end

assign GAD = GAD_final;
assign GBD = GBD_final;
assign DOTA = DOTA_final;
assign DOTB = DOTB_final;

endmodule

