module Bin2BCDConverter_4
#(
	parameter INPUT_BIT_WIDTH  = 8
)
(
    input [(INPUT_BIT_WIDTH-1):0] Input,
    output reg [3:0] Digit3,
    output reg [3:0] Digit2,
    output reg [3:0] Digit1,
    output reg [3:0] Digit0
);

    reg [3:0] tempDigit3, tempDigit2, tempDigit1, tempDigit0;
    reg [3:0] carry = 0;

    always @(posedge Input or negedge clk) begin
        if (posedge clk) begin
            tempDigit3 = Digit3;
            tempDigit2 = Digit2;
            tempDigit1 = Digit1;
            tempDigit0 = Digit0;

            for (int i = 0; i < INPUT_BIT_WIDTH; i++) begin
                if (Input[i] == 1) begin
                    if (tempDigit3 == 9) begin
                        tempDigit3 = 0;
                        carry = 1;
                    end else begin
                        tempDigit3 = tempDigit3 + 1;
                    end
                end else begin
                    if (carry == 1) begin
                        if (tempDigit3 == 9) begin
                            tempDigit3 = 0;
                            carry = 1;
                        end else begin
                            tempDigit3 = tempDigit3 + 1;
                        end
                    end else begin
                        carry = 0;
                    end
                end

                if (i < INPUT_BIT_WIDTH - 1) begin
                    tempDigit2 = tempDigit3;
                    tempDigit1 = tempDigit2;
                    tempDigit0 = tempDigit1;
                end

                if (i == INPUT_BIT_WIDTH - 1) begin
                    Digit3 = tempDigit3;
                    Digit2 = tempDigit2;
                    Digit1 = tempDigit1;
                    Digit0 = tempDigit0;
                end
            end
        end
    end

endmodule

