module noise(
  input i_clk,
  output reg signed [15:0] o_data
);

reg [15:0] r_shift16 = 16'b0xDEAD; // Initial state of the LFSR
reg [15:0] o_data_reg = 16'b0; // Register to hold the current state of o_data

always @(posedge i_clk) begin
  // Shift the LFSR bits to the left
  r_shift16 = {r_shift16[14:0], r_shift16[15] ^ r_shift16[12] ^ r_shift16[10] ^ r_shift16[3]};

  // Check if the LFSR state has reached the specific value
  if (r_shift16 == 16'b0x8000) begin
    // Set o_data to 0x8001 when the state is 0x8000
    o_data_reg = 16'b0x8001;
  end else begin
    // Otherwise, set o_data to the current state of r_shift16
    o_data_reg = r_shift16;
  end

  // Assign the current value of o_data_reg to o_data
  o_data <= o_data_reg;
end

endmodule

