module NBitCounterChain #(
   parameter counterSize   = 16,
   parameter numOfCounters = 3054
) (
   input  wire                   clk,
   input  wire                   reset,
   output wire [counterSize-1:0] outCount
);

reg [counterSize-1:0] counts[numOfCounters];
reg [counterSize-1:0] terminalCounts[numOfCounters];
reg [counterSize-1:0] enable[numOfCounters];

always @(posedge clk or posedge reset) begin
   if (reset) begin
      for (int i = 0; i < numOfCounters; i++) begin
         counts[i] <= 0;
         terminalCounts[i] <= 0;
         enable[i] <= 0;
      end
   end else begin
      for (int i = 0; i < numOfCounters; i++) begin
         if (i == 0) begin
            enable[i] <= 1;
         end else begin
            enable[i] <= terminalCounts[i-1];
         end
         if (enable[i] == 1) begin
            counts[i] <= counts[i] + 1;
         end
         if (counts[i] == (2**counterSize) - 1) begin
            terminalCounts[i] <= 1;
         end
      end
   end
end

assign outCount = counts[numOfCounters-1];

endmodule

