module division(A,B,Res);
    parameter WIDTH = 16;
    input [WIDTH-1:0] A;
    input [WIDTH-1:0] B;
    output reg [WIDTH-1:0] Res = 0;

    reg [WIDTH-1:0] a1, b1, p1;
    reg [WIDTH:0] q1;

    always @(posedge A or posedge B) begin
        if (A == 0) begin
            Res <= 0;
            return;
        end

        a1 <= A;
        b1 <= B;
        p1 <= 0;

        for (int i = 0; i < WIDTH; i++) begin
            if (p1 >= b1) begin
                p1 = p1 - b1;
                q1 = q1 | (1 << i);
            end
            p1 = p1 << 1;
        end

        Res <= a1;
    end
endmodule

